(window.TNQ=window.TNQ||[]).push({"terms":{"확정급여형":{"d":"퇴직 때 받을 급여액이 미리 정해지고 회사가 적립금 운용 책임을 지는 퇴직연금 방식입니다.","r":["확정기여형"]},"확정기여형":{"d":"회사가 넣을 부담금만 정해지고 운용 성과에 따라 급여가 달라지는 퇴직연금 방식입니다.","r":["확정급여형"]},"개인형퇴직연금제도":{"d":"가입자가 자기 계정을 설정하여 퇴직급여를 적립, 운용하다가 노후에 연금 등으로 받는 제도이다.","r":[]},"중소기업퇴직연금기금제도":{"d":"상시 100명 미만 사업장들이 공동 기금을 만들어 근로복지공단이 운영하는 퇴직연금 제도입니다.","r":[]},"사전지정운용제도":{"d":"확정기여형 퇴직연금에서 가입자가 운용 방법을 지정하지 않으면 미리 정해 둔 방법으로 적립금을 운용하는 제도이다.","r":[]},"사전지정운용방법":{"d":"고용노동부장관 승인을 받아 가입자가 선택하지 않은 적립금을 대신 굴리는 운용 상품 구성입니다.","r":["사전지정운용제도"]},"근로자대표":{"d":"과반수 노동조합이 없을 때 근로자 과반수를 대표해 동의나 협의의 상대가 되는 사람입니다.","r":[]},"중간정산":{"d":"퇴직금을 퇴직 전에 법정 사유가 있을 때 미리 정산하여 지급하는 것이다.","r":[]},"퇴직금":{"d":"근로자가 퇴직할 때 사용자가 계속근로기간 1년에 대하여 일정 일수의 평균임금으로 지급하는 급여이다.","r":[]},"우선변제":{"d":"퇴직급여 같은 채권을 저당권 채권이나 조세보다 먼저 갚도록 하는 법적 순위 보호입니다.","r":[]},"평균임금":{"d":"이를 산정해야 할 사유가 생긴 날 이전 일정 기간 동안 그 근로자에게 지급된 임금 총액을 그 기간의 총일수로 나눈 금액이다.","r":[]},"기준책임준비금":{"d":"확정급여형퇴직연금에서 적립금이 갖추어야 하는 최소 수준을 계산하는 기준이 되는 금액이다.","r":[]},"최소적립금":{"d":"DB제도에서 매 사업연도 말 반드시 적립해야 하는 최저 금액으로 급여 지급능력을 지키는 장치입니다.","r":["기준책임준비금"]},"재정검증":{"d":"연금사업자가 사업연도 종료 후 적립금이 최소적립금을 넘는지 확인하고 사용자에게 알리는 절차입니다.","r":["최소적립금"]},"간사기관":{"d":"복수의 연금사업자와 계약한 사용자가 업무 조정을 위해 그중에서 정하는 대표 사업자입니다.","r":[]},"적립금운용위원회":{"d":"상시 일정 수 이상의 근로자를 사용하는 사업에서 퇴직연금 적립금의 운용을 심의하기 위해 두는 위원회이다.","r":[]},"운용계획서":{"d":"적립금운용위원회 심의를 거쳐 운용 목적과 방법, 목표수익률 등을 담아 매년 작성하는 문서입니다.","r":["적립금운용위원회"]},"중도인출":{"d":"확정기여형퇴직연금 가입자가 법정 사유가 있을 때 적립금을 퇴직 전에 찾아 쓰는 것이다.","r":[]},"담보 제공":{"d":"급여를 받을 권리를 담보로 대출받는 것으로 법에서 정한 예외 사유에 한해 허용됩니다.","r":[]},"지연이자":{"d":"부담금을 정해진 날까지 내지 않았을 때 늦은 기간에 대해 추가로 내야 하는 이자입니다.","r":[]},"운용관리업무":{"d":"퇴직연금사업자가 가입자에게 운용 방법을 제시하고 적립금 운용 상황을 관리하는 업무이다.","r":[]},"자산관리업무":{"d":"퇴직연금사업자가 계좌 설정, 부담금 수령, 적립금 보관, 운용지시 이행, 급여 지급을 맡는 일입니다.","r":["운용관리업무"]},"퇴직연금사업자":{"d":"퇴직연금제도의 운용관리 업무나 자산관리 업무를 수행하기 위해 등록한 금융회사이다.","r":[]},"모집인":{"d":"퇴직연금사업자로부터 가입 모집 업무를 위탁받아 고용노동부장관에게 등록한 임직원 아닌 사람입니다.","r":[]},"표준계약서":{"d":"근로복지공단이 작성해 장관 승인을 받은 중소기업기금 설정용 계약서 양식입니다.","r":["중소기업퇴직연금기금제도"]},"근로복지공단":{"d":"중소기업퇴직연금기금제도를 운영하며 기금을 다른 회계와 구분해 관리하는 공공기관입니다.","r":["중소기업퇴직연금기금제도"]},"퇴직급여등":{"d":"퇴직금, DB 급여, DC·기금·IRP의 미납 부담금과 지연이자 등을 한데 묶어 부르는 말입니다.","r":["우선변제"]},"소멸시효":{"d":"권리를 행사할 수 있는데도 일정 기간 행사하지 않으면 그 권리가 소멸하는 제도이다.","r":[]},"임금피크제":{"d":"정년 연장이나 보장을 조건으로 일정 나이나 근속 시점부터 임금을 줄이는 제도입니다.","r":["중간정산"]},"낙부통지의무":{"d":"보험자가 청약을 받으면 일정 기간 안에 보험계약자에게 승낙 여부를 알려야 하는 의무이다. 이를 게을리하면 승낙한 것으로 본다.","r":[]},"보험계약자":{"d":"보험자와 보험계약을 체결하고 보험료를 낼 의무를 지는 자이다.","r":[]},"보험자":{"d":"보험계약의 당사자로서 보험료를 받고 보험사고가 생기면 보험금을 지급할 의무를 지는 자이다.","r":[]},"피보험자":{"d":"손해보험에서는 손해를 입는 자, 인보험에서는 생명이나 신체에 보험사고가 생기는 대상이 되는 자이다.","r":[]},"보험수익자":{"d":"인보험에서 보험사고가 발생하면 보험금을 청구할 수 있는 자로 보험계약자가 지정한다.","r":[]},"타인을 위한 손해보험계약":{"d":"보험계약자가 특정 또는 불특정의 타인을 피보험자로 하여 체결하는 손해보험계약이다. 타인의 위임이 없어도 체결할 수 있으나 보험자에게 그 사실을 알려야 한다.","r":[]},"청구권 대위":{"d":"보험자가 보험금을 지급하면 그 한도에서 피보험자가 제3자에게 가진 손해배상청구권을 법률상 당연히 취득하는 제도이다.","r":[]},"보험계약의 부활":{"d":"계속보험료를 내지 않아 해지된 보험계약을 보험계약자가 연체보험료와 이자를 내고 다시 효력을 회복시키는 제도이다.","r":[]},"해지환급금":{"d":"보험계약이 해지될 때 보험자가 보험계약자에게 돌려주는 금액이다.","r":[]},"불이익변경금지":{"d":"상법 보험편의 규정은 당사자 간 특약으로 보험계약자 등에게 불리하게 바꿀 수 없다는 원칙으로 가계보험에 적용된다.","r":[]},"재보험":{"d":"보험자가 인수한 위험의 일부 또는 전부를 다른 보험자에게 넘기는 보험이다.","r":[]},"위험변경·증가":{"d":"보험기간 중 사고발생의 위험이 현저하게 변경되거나 증가된 것으로 보험계약자 등은 이를 지체 없이 보험자에게 알려야 한다.","r":[]},"승낙 전 보호제도":{"d":"청약과 함께 보험료 상당액을 받은 보험자가 승낙 전에 사고가 생기면 청약을 거절할 사유가 없는 한 보험상의 책임을 지는 제도이다.","r":[]},"보험기간":{"d":"보험자의 책임이 존속하는 기간으로 보험사고가 이 기간 중에 발생해야 보험금이 지급된다.","r":[]},"보험계약기간":{"d":"보험계약이 성립하여 존속하는 기간으로 보험기간과 반드시 일치하지는 않는다.","r":[]},"간접의무":{"d":"이행을 강제할 수 없고 위반하면 권리 상실 등 불이익만 받는 의무이다. 통지의무나 손해방지의무 등이 해당한다.","r":[]},"정액보험":{"d":"보험사고가 생기면 손해액과 관계없이 정해진 금액을 지급하는 보험이다.","r":[]},"기업보험":{"d":"기업의 경영활동에서 생기는 위험을 대상으로 하는 보험이다.","r":[]},"가계보험":{"d":"개인이나 가정의 생활에서 생기는 위험을 대상으로 하는 보험으로 불이익변경금지 원칙이 적용된다.","r":[]},"변액보험":{"d":"보험료를 특별계정으로 운용하여 그 투자 성과에 따라 보험금과 해약환급금이 달라지는 보험이다.","r":[]},"실효예고부최고":{"d":"계속보험료를 내지 않을 때 일정 기간 안에 내지 않으면 계약이 실효된다고 미리 알리고 독촉하는 약관상의 절차이다.","r":[]},"미경과보험료":{"d":"보험기간 중 아직 지나지 않은 기간에 해당하는 보험료이다.","r":[]},"임의해지권":{"d":"보험사고가 발생하기 전에 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있는 권리이다.","r":[]},"소급보험":{"d":"보험계약 성립 이전의 일정 시기를 보험기간의 시작으로 정한 보험이다.","r":[]},"보험료 선급의 원칙":{"d":"최초보험료를 지급받은 때부터 보험자의 책임이 개시된다는 원칙이다.","r":[]},"낙성계약":{"d":"당사자의 합의만으로 성립하고 서면 작성 등 일정한 방식이 필요하지 않은 계약이다.","r":[]},"요식계약":{"d":"계약의 성립에 일정한 방식을 갖추어야 하는 계약이다.","r":[]},"개별약정 우선의 원칙":{"d":"약관과 다른 합의를 개별적으로 한 경우 그 합의가 약관보다 우선한다는 원칙이다.","r":[]},"면책약관":{"d":"일정한 사유가 있으면 보험자의 보험금 지급 책임을 면하게 하는 약관 조항이다.","r":[]},"설명의무":{"d":"보험자가 보험계약 체결 시 보험약관의 중요한 내용을 보험계약자에게 설명해야 하는 의무이다.","r":[]},"고지의무":{"d":"보험계약을 체결할 때 보험계약자 또는 피보험자가 중요한 사항을 알리고 부실하게 알리지 않아야 하는 의무이다.","r":[]},"통지의무":{"d":"보험기간 중 위험의 현저한 변경이나 증가 사실을 알게 되면 지체 없이 보험자에게 알려야 하는 의무이다.","r":[]},"보험증권":{"d":"보험계약의 성립과 내용을 증명하기 위해 보험자가 작성하여 보험계약자에게 교부하는 증서이다.","r":[]},"계속보험료":{"d":"최초보험료 이후 계약을 유지하기 위해 계속 지급하는 보험료이다.","r":[]},"중과실":{"d":"현저하게 주의를 게을리한 과실로 조금만 주의하면 결과를 쉽게 예견할 수 있었던 경우이다.","r":[]},"인과관계":{"d":"어떤 사실이 다른 사실의 원인이 되는 관계이다. 고지의무 위반과 보험사고 사이의 인과관계 유무가 보험자의 보험금 지급 여부에 영향을 준다.","r":[]},"보험가액":{"d":"피보험이익을 금전으로 평가한 것으로 보험사고 때 피보험자가 입을 수 있는 최대 손해액이다.","r":[]},"보험금액":{"d":"보험사고가 발생했을 때 보험자가 지급할 최고한도로 계약에서 정한 금액이다.","r":[]},"초과보험":{"d":"보험금액이 보험가액을 초과하는 보험이다.","r":[]},"일부보험":{"d":"보험금액이 보험가액보다 적은 보험으로 보험자는 보험금액의 보험가액에 대한 비율로 보상한다.","r":[]},"중복보험":{"d":"동일한 보험계약의 목적과 사고에 관하여 수 개의 보험계약이 동시에 또는 순차로 체결되어 보험금액의 총액이 보험가액을 초과하는 보험이다.","r":[]},"신가보험":{"d":"보험목적물의 손해액을 감가상각 없이 새 물건의 가액으로 평가하여 보상하는 보험이다.","r":[]},"미평가보험":{"d":"보험계약 체결 시 보험가액을 미리 정하지 않고 사고 발생 시 평가하는 보험이다.","r":[]},"실손보상의 원칙":{"d":"손해보험에서 피보험자가 실제로 입은 손해만 보상하며 보험으로 이득을 얻지 못하게 하는 원칙이다.","r":[]},"잔존물대위":{"d":"보험목적물이 전부 멸실하여 보험금 전부를 지급한 보험자가 그 목적물에 대한 피보험자의 권리를 취득하는 제도이다.","r":[]},"손해방지의무":{"d":"보험사고 발생 시 보험계약자와 피보험자가 손해의 방지와 경감을 위해 노력해야 하는 의무이다.","r":[]},"손해방지비용":{"d":"손해를 방지하거나 줄이기 위해 필요 또는 유익하였던 비용으로 보험자가 부담한다.","r":[]},"방어비용":{"d":"책임보험에서 피보험자가 제3자의 배상청구에 대응하기 위해 지출하는 비용이다.","r":[]},"피보험이익":{"d":"보험사고가 생기지 않는 것에 대하여 피보험자가 가지는 경제적 이해관계이다.","r":[]},"총괄보험":{"d":"집합된 물건을 일괄하여 보험의 목적으로 하는 보험으로 개별 물건이 바뀌어도 하나의 보험의 목적으로 본다.","r":[]},"비율보험":{"d":"손해액의 일정 비율만 보상하기로 약정한 보험이다.","r":[]},"부보비율":{"d":"보험가액에 대한 보험금액의 비율이다.","r":[]},"분손":{"d":"보험목적이 전부 멸실하지 않고 일부만 손해를 입은 경우이다.","r":[]},"책임보험":{"d":"피보험자가 제3자에게 배상책임을 져서 입는 손해를 보상하는 손해보험이다.","r":[]},"배상청구기준 약관":{"d":"보험기간 중에 피해자의 배상청구가 이루어지면 사고가 언제 발생했는지와 관계없이 보상하는 약관이다.","r":[]},"감항능력":{"d":"선박이 안전하게 항해를 할 수 있는 능력이다.","r":[]},"워런티":{"d":"영국 보험법상 피보험자가 엄격히 지켜야 하는 약속으로 위반하면 보험자의 책임이 면해지는 담보 조항이다.","r":[]},"소손해면책":{"d":"일정액 이하의 작은 손해에 대해서는 보험자가 책임을 지지 않는 조항이다.","r":[]},"적하보험":{"d":"선박에 실은 화물의 손해를 보상하는 해상보험이다.","r":[]},"적하예정보험":{"d":"계약 체결 당시 화물을 적재할 선박이 확정되지 않은 적하보험이다.","r":[]},"포괄적 예정보험":{"d":"일정 기간 일정 조건에 따라 정해지는 다수의 선적화물을 포괄적이고 계속적으로 보험의 목적으로 하는 보험이다.","r":[]},"보험위부":{"d":"해상보험에서 피보험자가 보험의 목적에 대한 권리를 보험자에게 넘기고 보험금 전부를 청구하는 제도이다.","r":[]},"형성권":{"d":"권리자의 일방적인 의사표시만으로 법률관계를 발생, 변경, 소멸시키는 권리이다.","r":[]},"선박보험":{"d":"선박 자체의 손해를 보상하는 해상보험이다.","r":[]},"1차 위험담보":{"d":"보험금액의 한도에서 손해 전액을 보상하는 특약으로 비례보상을 배제한다.","r":[]},"단체보험":{"d":"단체의 규약에 따라 구성원을 피보험자로 하여 단체가 계약자로서 체결하는 보험이다.","r":[]},"사망보험":{"d":"피보험자의 사망을 보험사고로 하는 인보험이다.","r":[]},"도덕적 위험":{"d":"보험에 가입한 뒤 보험금을 노려 고의로 사고를 일으키거나 주의를 소홀히 하는 위험이다.","r":[]},"미필적 고의":{"d":"결과의 발생을 확실히 의도하지는 않았지만 그럴 수 있다고 알고도 용인하는 심리상태이다.","r":[]},"추인":{"d":"효력이 확정되지 않은 행위를 사후에 인정하여 그 효력을 확정시키는 의사표시이다.","r":[]},"선량한 풍속 기타 사회질서":{"d":"민법 제103조에 따라 이에 반하는 법률행위는 무효이다.","r":[]},"보험설계사":{"d":"보험회사, 보험대리점, 보험중개사에 소속되어 보험계약의 체결을 중개하는 자이다.","r":[]},"보험중개사":{"d":"독립적으로 보험계약의 체결을 중개하는 자로 금융위원회에 등록해야 한다.","r":[]},"구상권":{"d":"타인을 위해 채무를 변제한 자가 그 타인에게 상환을 청구하는 권리이다.","r":[]},"서면동의":{"d":"타인의 사망을 보험사고로 하는 계약에서 그 타인이 계약 체결 시 서면으로 하는 동의이다.","r":[]},"보증보험":{"d":"채무자의 채무불이행으로 채권자가 입는 손해를 보상하는 보험이다.","r":[]},"직접청구권":{"d":"책임보험에서 피해자가 보험자에게 직접 보험금 상당의 손해배상을 청구할 수 있는 권리이다. 상법 제724조 제2항이 인정한다.","r":[]},"손해사고설":{"d":"책임보험의 보험사고를 제3자에 대한 손해배상책임의 원인이 된 사고로 보는 학설이다.","r":[]},"단기소멸시효":{"d":"불법행위로 인한 손해배상청구권은 손해와 가해자를 안 날부터 일정 기간 행사하지 않으면 소멸하는 시효이다.","r":[]},"강행규정":{"d":"당사자의 합의로 배제하거나 바꿀 수 없는 규정이다.","r":[]},"공동불법행위자":{"d":"여럿이 함께 불법행위를 하여 타인에게 손해를 입힌 자들로 피해자에게 연대하여 책임을 진다.","r":[]},"제3보험업":{"d":"보험업법상 상해보험, 질병보험, 간병보험 등을 영위하는 보험업이다.","r":[]},"전문보험계약자":{"d":"보험계약에 관한 전문성, 자산규모 등에 비추어 보험계약의 내용을 이해하고 이행할 능력이 있는 보험계약자이다.","r":[]},"일반보험계약자":{"d":"전문보험계약자가 아닌 보험계약자로 보험업법상 더 많은 보호를 받는다.","r":[]},"예비허가":{"d":"본허가를 신청하기 전에 금융위원회에서 미리 받는 허가로 조건을 이행하면 본허가를 신청할 수 있다.","r":[]},"소액단기전문보험회사":{"d":"보험업법상 보험금액이 소액이고 보험기간이 짧은 보험만 전문적으로 취급하는 보험회사이다.","r":[]},"외국보험회사":{"d":"대한민국 이외의 국가 법령에 따라 설립되어 그 국가에서 보험업을 경영하는 자이다.","r":[]},"모집":{"d":"보험계약의 체결을 중개하거나 대리하는 것이다.","r":[]},"상호회사":{"d":"보험업을 경영할 목적으로 보험업법에 따라 설립된 회사로 보험계약자를 사원으로 하는 회사이다.","r":[]},"겸영":{"d":"보험회사가 법령에서 허용한 범위에서 본래의 보험업 외에 다른 금융업 등을 함께 영위하는 것이다.","r":[]},"기금":{"d":"상호회사가 보험사업의 기초를 이루기 위해 사원이 출자하여 마련하는 자금이다.","r":[]},"조직변경":{"d":"회사가 법인격을 유지한 채 주식회사에서 상호회사로, 또는 그 반대로 바꾸는 것이다.","r":[]},"창립총회":{"d":"상호회사의 설립 과정에서 발기인이 사원을 모집한 후 열어 설립에 필요한 사항을 결정하는 총회이다.","r":[]},"보험계약 이전":{"d":"보험회사가 보험계약의 전부 또는 일부를 계약의 방법으로 다른 보험회사에 넘기는 것이다.","r":[]},"책임준비금":{"d":"보험회사가 장래의 보험금 지급을 위해 보험료 중에서 적립해 두는 준비금이다.","r":[]},"우선취득권":{"d":"보험계약자 등이 보험회사의 자산에서 다른 채권자보다 먼저 보험금 등을 변제받을 수 있는 권리이다.","r":[]},"특별계정":{"d":"보험업법에 따라 일반 계정과 구분하여 별도로 관리하는 계정으로 변액보험 등에 설정한다.","r":[]},"상계":{"d":"서로 같은 종류의 채권과 채무를 가진 자가 대등액에서 채권과 채무를 소멸시키는 의사표시이다.","r":[]},"영업보증금":{"d":"보험중개사가 보험계약자에게 입힌 손해의 배상을 보장하기 위해 예탁하는 금전이다.","r":[]},"보험대리점":{"d":"보험회사를 위하여 보험계약의 체결을 대리하는 자로 금융위원회에 등록해야 한다.","r":[]},"자기계약":{"d":"대리인이 본인을 위한 계약에서 스스로 상대방이 되는 계약이다.","r":[]},"모집종사자":{"d":"보험설계사, 보험대리점, 보험중개사 및 그 임직원처럼 보험의 모집에 종사하는 자이다.","r":[]},"금융기관보험대리점":{"d":"보험업법상 은행 등 금융기관이 보험대리점으로 등록하여 보험을 모집하는 경우이다.","r":[]},"보험안내자료":{"d":"보험계약자 등에게 보험상품을 설명하기 위해 모집에 쓰는 자료로 기재사항이 법으로 정해져 있다.","r":[]},"사이버몰":{"d":"인터넷 등 전자적 방법으로 보험을 모집하는 전자상거래 공간이다.","r":[]},"교차모집":{"d":"보험설계사가 생명보험, 손해보험, 제3보험 중 둘 이상의 보험회사를 위해 모집하는 것이다.","r":[]},"실손의료보험":{"d":"실제로 부담한 의료비만을 보상하는 제3보험상품이다.","r":[]},"중복계약 체결 확인의무":{"d":"실손의료보험을 모집할 때 피보험자가 될 사람이 이미 다른 실손의료보험에 가입했는지 확인해야 하는 의무이다.","r":[]},"기초서류":{"d":"보험상품에 관한 보험약관, 사업방법서, 보험료 및 해약환급금 산출방법서이다.","r":[]},"보험요율 산출기관":{"d":"보험업법에 따라 순보험요율을 산출하고 통계를 관리하는 기관이다.","r":[]},"보험요율":{"d":"보험가입금액에 대한 보험료의 비율이다.","r":[]},"신용공여":{"d":"대출, 어음 할인, 지급보증 등을 통해 신용을 제공하는 행위이다.","r":[]},"대주주":{"d":"보험업법상 의결권 있는 발행주식 총수의 일정 비율 이상을 소유한 주주 등으로 신용공여 등에 제한이 있다.","r":[]},"상호협정":{"d":"보험회사가 업무에 관한 공동행위를 하기 위해 다른 보험회사와 맺는 협정으로 금융위원회의 인가를 받아야 한다.","r":[]},"비금융주력자":{"d":"은행법상 비금융회사의 자본 비중 등이 일정 비율 이상인 자로 금융회사의 지분 보유가 제한된다.","r":[]},"손해사정":{"d":"보험사고에서 손해액과 보험금을 평가하고 산정하는 업무이다.","r":[]},"손해사정업자":{"d":"손해사정을 업으로 하는 자로 보험업법에 따라 등록한다.","r":[]},"보험계리사":{"d":"보험수리에 관하여 책임준비금 산출 등 계리 업무를 수행하는 전문 자격자이다.","r":[]},"보험계리업자":{"d":"보험계리를 업으로 하는 법인으로 계리 업무를 위탁받아 수행한다.","r":[]},"선임계리사":{"d":"보험회사가 보험계리 업무를 총괄하도록 선임한 보험계리사이다.","r":[]},"지급여력비율":{"d":"보험회사가 보험금을 지급할 수 있는 재무적 능력을 나타내는 비율이다.","r":[]},"비상위험준비금":{"d":"보험회사가 이상 위험에 대비해 적립하는 준비금이다.","r":[]},"기초서류관리기준":{"d":"보험회사가 기초서류의 작성과 변경 및 관리를 위해 지켜야 하는 기준이다.","r":[]},"확정급여형퇴직연금제도":{"d":"근로자가 퇴직 후 받을 급여의 수준이 미리 정해져 있는 퇴직연금제도이다.","r":[]},"확정기여형퇴직연금제도":{"d":"사용자가 부담하는 금액이 미리 정해져 있고 운용 결과에 따라 급여가 달라지는 퇴직연금제도이다.","r":[]},"계속근로기간":{"d":"근로계약을 맺고 사직이나 해고 없이 계속하여 근로한 기간이다.","r":[]},"소정근로시간":{"d":"법정근로시간의 범위에서 근로자와 사용자가 정한 근로시간이다.","r":[]},"퇴직급여제도":{"d":"근로자의 퇴직 후 생활을 위해 사용자가 설정하는 퇴직금제도 또는 퇴직연금제도이다.","r":[]},"후유장해보험금":{"d":"상해나 질병 후 치료를 마친 뒤에도 남은 장해에 대해 지급하는 보험금이다.","r":[]},"기왕증":{"d":"사고 이전부터 피보험자가 가지고 있던 질병이나 신체 이상이다.","r":[]},"외래성":{"d":"상해보험에서 신체 손상의 원인이 피보험자의 신체 외부에서 비롯된 성질이다.","r":[]},"급격성":{"d":"상해보험에서 사고가 갑자기 일어나 원인에서 결과까지 시간적 간격이 짧은 성질이다.","r":[]},"우연성":{"d":"상해보험에서 사고가 피보험자가 예측하지 못한 원인으로 발생한 성질이다.","r":[]},"승낙피보험자":{"d":"자동차보험에서 기명피보험자의 승낙을 받아 피보험자동차를 사용하거나 관리하는 자이다.","r":[]},"기명피보험자":{"d":"자동차보험 증권에 기재되어 있는 피보험자이다.","r":[]},"보험자대위":{"d":"보험자가 보험금을 지급하고 피보험자가 제3자에 대해 가진 권리를 대신 행사하는 제도이다.","r":[]},"중복보험분담금청구권":{"d":"중복보험에서 단독으로 보험금을 지급한 보험자가 다른 보험자에게 각자의 분담 비율만큼 상환을 청구하는 권리이다.","r":[]},"주계약":{"d":"보증보험 등에서 보증의 대상이 되는 기본 계약이다.","r":[]}},"notes":{"(1) 무주택자인 가입자가 본인 명의로 주택 구입, (2) 무주택자인 가입자가 전세금·임차보증금 부담(한 사업에 근로하는 동안 1회), (3) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 질병·부상 의료비 부담, (4) 담보 제공일부터 거꾸로 5년 이내 파산선고, (5) 5년 이내 개인회생절차개시 결정, (6) 본인·배우자·부양가족의 대학등록금·혼례비·장례비 부담, (7) 사업주 휴업으로 임금 감소 또는 재난 피해(고시 요건)":"담보로 쓸 수 있는 경우는 무주택자의 집 구입과 전세금, 오랜 요양 의료비, 파산, 개인회생, 학비와 혼례비, 휴업이나 재난입니다.","15세 미만자·심신상실자·심신박약자의 사망을 보험사고로 한 계약은 무효. 단 심신박약자가 계약 체결 또는 단체보험 피보험자가 될 때 의사능력이 있으면 유효":"사망보험의 피보험자가 심신박약자여도 체결 시점에 의사능력이 있으면 그 계약은 유효하게 인정됩니다.","15세 미만자·심신상실자·심신박약자의 사망을 보험사고로 한 계약은 무효다. 15세 미만은 서면동의가 있어도 무효이고, 심신박약자는 계약 체결 또는 단체보험 피보험자가 될 때 의사능력이 있으면 유효하다":"15세 미만과 심신상실자, 심신박약자를 대상으로 한 사망보험은 무효이나 심신박약자는 의사능력이 있으면 유효합니다.","1차 보험금청구권에 질권이 설정되어 승계 이익이 거의 없는 목적물 양수인의 신규 보험은 중복보험에 해당하지 않는다":"기존 보험금청구권에 질권이 설정되어 승계 이익이 거의 없는 목적물 양수인이 새로 든 보험은 중복보험이 아닙니다.","1차 위험담보: 보험가액 10억, 보험금액 5억, 실손보상특약, 손해 4억이면 4억원을 지급한다":"1차 위험담보 약정에서는 보험금액 한도 안의 실제 손해를 보상하므로 손해 4억원에 대해 4억원을 지급합니다.","1차 위험담보 계산: 보험가액 10억, 보험금액 5억, 실손보상특약, 손해 4억이면 지급보험금은 4억원이다":"1차 위험담보 약정이면 손해가 보험금액 한도 안에서 실제 손해만큼 지급되므로 손해 4억원에 대해 4억원을 줍니다.","2015년 영국보험법: 워런티 위반 시 장래 자동 면책이 아니라 위반이 치유될 때까지만 면책되고, 워런티 불이행과 사고 사이에 인과관계가 없음을 증명하면 보험금을 지급한다":"2015년 영국보험법은 워런티를 어기면 위반이 치유될 때까지만 면책하고 불이행과 사고 사이에 인과관계가 없음을 증명하면 보험금을 줍니다.","2021 기출: 배우자 명의 주택 구입은 중간정산 사유가 아니고, 임금체계를 호봉제에서 직무급제로 바꾸는 것도 아니다. 정년 연장 조건 임금피크제와 재난 피해는 사유다":"2021년 기출에서 배우자 명의 집 구입과 직무급제로의 임금체계 변경은 사유가 아니고 임금피크제와 재난은 사유였습니다.","2022 기출 결과: DC 규약에 포함되는 것은 퇴직연금사업자 선정, 가입자, 가입기간, 급여의 종류 및 수급요건, 수수료 부담, 가입자 교육 방법·절차 6개. 급여 지급능력 확보(DB 항목)는 포함되지 않는다(정답 6개)":"2022년 기출은 DC 규약에 넣는 것이 사업자 선정부터 교육 방법까지 6개이고 지급능력 확보는 DB 항목이라는 점이었습니다.","2022 기출 계산: 전세금 1회, 의료비 6개월 이상·1천분의 125, 파산 5년 → 1+6+125+5=137":"2022년 기출은 전세금 1회, 의료비 6개월과 125, 파산 5년을 모두 더해 137이 답이었습니다.","2025 기출 사례: 배우자 명의 주택 구입(불가), 입사 후 처음 전세금 부담(가능), 2018년 개인회생 결정(5년 경과로 불가), 배우자의 부양가족 대학등록금 부담(가능) — 정답 나·라":"2025년 기출은 배우자 명의 집 구입은 불가, 첫 전세금은 가능, 5년 지난 개인회생은 불가, 가족 학비는 가능으로 답이 나·라였습니다.","2026 기출 결과: 6개월 이상 요양(가), 재난(라), 대출 원리금 상환(마), 5년 내 파산(바)는 중도인출 사유. 대학등록금 등(나)과 휴업(다)은 아니다. 가는 본인 연간 임금총액의 1천분의 125 초과 조건이 빠져 틀린 보기이므로 옳지 않은 것은 가·나·다 3개":"2026년 기출은 가·나·다 세 개가 틀린 보기였는데 의료비는 연간 임금총액의 1천분의 125 초과 조건이 빠졌기 때문입니다.","6개월 이내 업무정지 또는 등록취소(임의적): 모집 관련 법 위반, 보험사기행위(제102조의2) 위반, 명령·처분 위반, 과태료 2회 이상 등. 처분 전 청문":"모집 관련 법 위반과 보험사기행위와 명령 위반 등이 있으면 6개월 이내 업무정지나 등록취소를 할 수 있고 처분 전에 청문을 합니다.","DB 규약 필수 기재사항: 퇴직연금사업자 선정, 가입자, 가입기간, 급여수준, 급여 지급능력 확보, 급여의 종류 및 수급요건, 운용관리·자산관리업무 계약 체결·해지·이전, 운용현황 통지, 급여 지급사유 발생과 지급절차, 제도 폐지·중단 사유와 절차, 부담금의 산정 및 납입, 그 밖의 대통령령 사항(수수료 부담, 가입자 교육 방법·절차, 복수 사업자 업무 처리방안)":"DB 규약에는 사업자 선정, 가입자, 급여수준, 지급능력 확보, 급여 종류, 부담금 산정, 폐지 사유 등이 반드시 적혀야 합니다.","DB 설정: 근로자대표의 동의를 얻거나(새로 성립된 사업은 의견을 들어) 규약을 작성해 고용노동부장관에게 신고한다. 새로 성립된 사업의 사용자는 성립 후 1년 내에 근로자대표의 의견을 들어 설정할 수 있다":"DB를 설정하려면 근로자대표 동의를 받아 규약을 만들고 고용노동부장관에게 신고하며 새 사업은 성립 후 1년 안에 가능합니다.","DB와 DC를 함께 설정할 수 있다. 이 경우 각 설정 비율의 합이 1 이상이 되도록 규약을 정한다":"DB와 DC를 섞어 운영할 수 있으며 규약에서 정한 각 비율을 더하면 1 이상이 되어야 합니다.","DC 가입자는 대통령령 사유가 있으면 적립금을 중도인출할 수 있다":"DC 가입자는 시행령이 정한 사유가 있을 때 적립금의 일부를 중도에 꺼내 쓸 수 있습니다.","IRP 계정 이전 예외(영 제3조의2): 55세 이후 퇴직하여 급여를 받는 경우, 급여가 고용노동부장관 고시 금액 이하인 경우, 근로자가 사망한 경우, 취업 가능 체류자격 근로자가 퇴직 후 출국한 경우, 다른 법령에서 급여의 전부 또는 일부를 공제하도록 한 경우. 50세에 퇴직하는 경우는 예외 사유가 아니다":"55세 이후 퇴직이나 소액, 사망, 출국 근로자 같은 경우는 IRP 이전 예외이지만 50세 퇴직은 해당하지 않습니다.","IRP 급여 수급요건: 연금은 55세 이상 가입자에게 지급하고 지급기간 5년 이상. 일시금은 55세 이상으로서 일시금 수급을 원하는 가입자에게 지급":"IRP 연금은 55세 이상 가입자에게 5년 이상에 걸쳐 주고 일시금도 55세 이상이면서 원하는 사람에게 줍니다.","IRP 중도인출 사유: 주택 구입, 전세금·보증금 부담(제25조 가입자는 한 사업 근로 중 1회), 의료비(제25조 가입자는 본인 연간 임금총액의 1천분의 125 초과 시), 재난 피해, 5년 내 파산선고, 5년 내 개인회생절차개시 결정, 담보대출 원리금 상환":"IRP 중도인출 사유는 집 구입, 전세금, 의료비, 재난, 파산, 개인회생, 대출 원리금 상환으로 DC와 거의 같습니다.","甲이 丙을 수익자로 지정하고 변경권을 행사하지 않고 사망하면 丙의 권리가 확정된다. 丙이 존속 중 사망하면 甲이 다시 지정할 수 있고, 丙의 상속인이 바로 확정되지는 않는다":"계약자가 수익자를 지정하고 변경권을 쓰지 않은 채 숨지면 수익자의 권리가 확정되고 수익자가 먼저 숨으면 계약자가 다시 지정할 수 있습니다.","가계보험·기업보험 구분의 실익: 불이익변경금지(제663조)를 적용하는 데 있다":"가계보험과 기업보험을 나누는 이유는 가계보험에만 약관을 계약자에게 불리하게 바꾸지 못하는 규정을 적용하기 위해서입니다.","가스 폭발 자체에 의한 손해는 특약이 없으면 화재보험자가 보상하지 않는다":"가스 폭발 자체로 생긴 손해는 화재가 아니므로 특약이 없으면 화재보험자가 보상하지 않습니다.","가입기간: 제도 설정 이후 해당 사업에서 근로를 제공한 기간. 설정 전 근로기간도 가입기간으로 할 수 있으나(임의), 주택구입 등으로 퇴직금을 미리 정산한 기간은 제외한다":"가입기간은 제도를 만든 뒤 일한 기간이고 이전 근속도 넣을 수 있으나 이미 정산해 받은 기간은 뺍니다.","가입자가 운용방법을 선정하지 않는 경우 퇴직연금사업자가 통지하고(가입 시, 기존 선정 운용방법 기간 만료일부터 4주 경과 시), 통지를 받은 후 2주 이내에 스스로 선정하지 않으면 사전지정운용방법으로 운용한다. 사전지정운용방법으로 운용하는 가입자도 언제든지 스스로 운용방법을 선정할 수 있다":"운용방법을 고르지 않는 가입자에게 사업자가 알리고 2주 안에 선택이 없으면 사전지정방법으로 굴리며 가입자는 언제든 직접 고를 수 있습니다.","가입자는 적립금의 운용방법을 스스로 선정할 수 있고 반기마다 1회 이상 변경할 수 있다. 퇴직연금사업자는 반기마다 1회 이상 위험과 수익구조가 서로 다른 세 가지 이상의 운용방법을 제시하고, 운용방법별 이익 및 손실 가능성 정보를 제공해야 한다":"가입자는 운용방법을 직접 고르고 반기마다 바꿀 수 있으며 사업자는 반기마다 서로 다른 세 가지 이상을 보여 주고 손익 정보를 줘야 합니다.","가입자는 퇴직할 때 받을 급여를 갈음하여 운용 중인 자산을 가입자가 설정한 IRP 계정으로 이전해 줄 것을 요청할 수 있다. 그러면 급여가 지급된 것으로 본다":"가입자는 퇴직급여 대신 운용 중인 자산을 자기 IRP 계좌로 옮겨 달라고 할 수 있고 그러면 지급한 것으로 칩니다.","가입자부담금: 제24조제2항 각 호에 해당하는 사람은 가입자 명의의 기금제도가입자부담금계정을 설정할 수 있다. 사용자부담금 계정과 구분해 관리":"일정한 사람은 가입자 이름의 기금제도가입자부담금계정을 열 수 있고 사용자부담금 계정과는 나누어 관리합니다.","가입자의 연간 임금총액의 12분의 1 이상에 해당하는 부담금을 현금으로 가입자의 DC 계정에 납입한다. 가입자는 추가 부담금을 납입할 수 있다":"사용자는 가입자 연간 임금총액의 12분의 1 이상을 현금으로 DC 계정에 넣어야 하고 가입자는 더 보탤 수 있습니다.","가입자 제공 정보(제21조의3, 영 제13조의2): 자산배분 현황 및 위험·수익 구조, 위험등급·손실가능성·과거 수익률, 수수료 등 가입자 부담 비용, 예금자 보호 한도 등 보호 사항, 위험도 변경 가능성, 승인일자 등 승인 사항, 변경 가능성과 절차. 사용자의 부담금 수준·납입시기는 이 정보에 포함되지 않는다(사용자 교육 사항)":"가입자에게 줄 정보는 자산배분, 위험등급, 수수료, 예금자 보호, 승인 사항 등이며 사용자의 부담금 수준과 납입시기는 빠집니다.","각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다. 연대책임은 부진정연대책임이다":"각 보험자는 자기 보험금액의 비율대로 보상하며 서로 지는 연대책임은 부진정연대책임입니다.","감항능력: 당사자 약정으로 인과관계 없이도 면책하기로 한 합의는 유효하다. 발항 당시 불감항 사실만 증명하면 면책된다는 조건 약정이 있는 경우 조건 결여 이후 사고는 인과관계를 증명할 필요가 없다":"감항능력 결여는 약정으로 인과관계 없이도 면책하기로 합의할 수 있고 조건이 빠진 이후의 사고는 인과관계를 증명할 필요가 없습니다.","개인과 법인을 구분해 금융위원회에 등록. 다음은 될 수 없다: 보험설계사·보험중개사로 등록된 자, 다른 보험회사등의 임직원, 결격사유자 등":"보험대리점은 개인과 법인으로 나눠 금융위원회에 등록하며 설계사나 중개사로 등록된 자와 다른 보험회사의 임직원과 결격사유자는 될 수 없습니다.","개인형퇴직연금제도(IRP): 가입자의 선택에 따라 가입자가 납입한 일시금이나 사용자·가입자가 납입한 부담금을 적립·운용하기 위해 설정한 제도로 급여 수준이나 부담금 수준이 확정되지 않은 제도":"IRP는 개인이 일시금이나 부담금을 직접 적립해 운용하는 계좌형 제도이며 급여나 부담금 수준이 정해져 있지 않습니다.","객관적이고 합리적인 통계자료를 기초로 대수의 법칙 및 통계신뢰도를 바탕으로 하며, 지나치게 높지 않을 것, 재무건전성을 크게 해칠 정도로 낮지 않을 것, 계약자 간 부당하게 차별적이지 않을 것, 자동차보험은 공정하고 합리적인 수준일 것":"보험요율은 통계 자료와 대수의 법칙을 근거로 너무 높거나 낮지 않고 계약자 사이에 부당한 차별이 없도록 정해야 합니다.","결의한 날부터 2주 이내에 결의의 요지와 재무상태표를 공고해야 한다":"자본감소를 결의하면 결의한 날부터 2주 안에 결의의 요지와 재무상태표를 공고해야 합니다.","결의 후 공고·통지: 결의일부터 2주 이내에 결의의 요지와 재무상태표를 공고하고 주주명부에 적힌 질권자에게 개별 통지한다. 상법 제232조(채권자 이의 절차)를 준용한다":"조직변경을 결의하면 2주 안에 요지와 재무상태표를 공고하고 질권자에게 개별 통지하며 채권자 이의 절차를 준용합니다.","겸영 가능 보험종목(영 제15조제1항): 연금저축계좌 설정 계약, 퇴직보험계약(근퇴법 제29조제2항). 손해보험 일부 종목만 취급하는 보험회사와 제3보험업만 경영하는 보험회사는 겸영할 수 없다":"겸영할 수 있는 종목에는 연금저축계좌 설정 계약과 퇴직보험계약이 있고 손해보험 일부만 취급하거나 제3보험업만 하는 회사는 겸영할 수 없습니다.","겸영업무·부수업무는 보험업과 구분하여 회계처리한다":"겸영업무와 부수업무는 보험업과 섞이지 않도록 회계를 따로 구분해서 처리합니다.","경영건전성과 계약자 보호를 해치지 않는 금융업무를 할 수 있다. 제1호 또는 제3호 업무는 시작 7일 전까지 금융위원회에 신고한다":"보험회사는 경영건전성과 계약자 보호를 해치지 않는 금융업무를 겸영할 수 있으며 일부 업무는 시작 7일 전까지 금융위원회에 신고합니다.","계속근로기간 1년에 대하여 30일분 이상의 평균임금을 퇴직금으로 지급하는 제도를 설정해야 한다. 30일분 이상이므로 45일분 지급 설정도 가능하다":"퇴직금은 근속 1년에 평균임금 30일분 이상이어야 하므로 그보다 후한 45일분으로 정해도 문제가 없습니다.","계속보험료 지체: 약정한 시기에 지급되지 않으면 보험자는 상당한 기간을 정하여 최고하고, 그 기간 내에 지급이 없으면 계약을 해지할 수 있다":"계속보험료를 약정한 때 내지 않으면 보험자가 상당한 기간을 정해 독촉하고 그 기간에도 안 내면 계약을 해지할 수 있습니다.","계약 무효 시 보험료 반환: 보험계약의 전부 또는 일부가 무효인 경우 계약자·피보험자가 선의이며 중대한 과실이 없으면 보험료의 전부 또는 일부의 반환을 청구할 수 있다. 계약자·수익자가 선의·무중과실인 때도 같다":"계약이 무효이면 계약자와 피보험자가 선의이고 중과실이 없을 때 보험료의 전부나 일부를 돌려받을 수 있습니다.","계약의 방법으로 책임준비금 산출 기초가 같은 보험계약의 전부를 포괄하여 다른 보험회사에 이전할 수 있고, 금융위원회의 인가를 받아야 한다. 회사자산 이전도 정할 수 있다":"책임준비금 산출 기초가 같은 계약은 금융위원회 인가를 받아 한꺼번에 다른 보험회사로 옮길 수 있습니다.","계약자가 위 지정권을 행사하기 전에 보험사고가 생기면 피보험자 또는 보험수익자의 상속인이 수익자다":"수익자 재지정권을 쓰기 전에 사고가 나면 피보험자나 수익자의 상속인이 보험금을 받는 수익자가 됩니다.","계약자가 지정권을 행사하지 않고 사망하면 피보험자가 보험수익자다. 변경권을 행사하지 않고 사망하면 보험수익자의 권리가 확정된다":"계약자가 지정권을 쓰지 않고 숨지면 피보험자가 수익자가 되고 변경권을 쓰지 않고 숨지면 지정된 수익자의 권리가 확정됩니다.","계약자가 처음부터 피보험자를 살해해 보험금을 편취할 목적으로 체결한 생명보험은 반사회질서 법률행위로 무효다":"처음부터 피보험자를 해쳐 보험금을 얻으려고 든 생명보험은 반사회질서 행위여서 무효가 됩니다.","계약 체결 당시 이미 존재하던 위험과의 차이(고지의무 위반)는 위험변경증가에 해당하지 않는다":"계약 당시에 이미 있던 위험을 알리지 않은 것은 고지의무 위반이지 보험기간 중 위험이 변경 증가한 것이 아닙니다.","고용보험 피보험자격 취득신고가 늦었더라도 실제 근로 개시일 및 약정 근로시간 기준으로 퇴직급여제도 설정의무가 있다":"고용보험 취득신고를 늦게 했더라도 실제 일을 시작한 날과 약정된 근로시간을 기준으로 설정의무가 생깁니다.","고의는 자신의 행위로 일정한 결과가 발생하리라는 것을 알면서 행하는 심리상태이며 미필적 고의를 포함한다. 심신미약 상태에서 발생한 사고는 고의로 볼 수 없다":"고의는 결과가 생길 줄 알면서 행하는 마음 상태로 미필적 고의도 포함하나 심신미약 상태의 사고는 고의로 보지 않습니다.","고의·중과실 면책: 보험사고가 보험계약자·피보험자·보험수익자의 고의 또는 중대한 과실로 생긴 때 보험자는 보험금액을 지급할 책임이 없다(손해보험 일반)":"사고가 계약자나 피보험자나 수익자의 고의나 중과실로 났다면 손해보험의 보험자는 보험금을 줄 책임이 없습니다.","고의·중과실 사실은 보험자가 증명한다":"사고가 고의나 중대한 과실로 났다는 사실은 책임을 면하려는 보험자가 증명해야 합니다.","고지의무 위반과 보험사고 사이에 인과관계가 없으면 해지는 할 수 있으나 보험금은 지급해야 한다":"고지의무 위반과 사고가 서로 관련이 없다면 계약은 해지할 수 있어도 보험금은 지급해야 합니다.","고지의무 위반을 이유로 해지하는 경우 인보험자는 보험수익자를 위하여 적립한 금액을 보험계약자에게 지급해야 한다":"고지의무 위반으로 해지한 인보험자는 수익자를 위해 쌓아 둔 적립금을 계약자에게 돌려줘야 합니다.","고지의무 위반 해지 시 보험계약자의 보험료 반환청구에 관한 상법 명시 규정은 없다":"고지의무 위반으로 해지했을 때 계약자가 보험료를 돌려받는 것에 관해 상법에는 명시적인 규정이 없습니다.","고지의무자: 보험계약자 또는 피보험자. 대리인이 안 사유는 본인이 안 것으로 본다":"고지의무를 지는 사람은 보험계약자와 피보험자이며 대리인이 아는 사실은 본인이 안 것으로 봅니다.","공고·통지: 이전 결의일부터 2주 이내에 계약 이전의 요지와 각 보험회사의 재무상태표를 공고하고 보험계약자에게 통지한다. 이의 기간은 1개월 이상":"계약 이전은 결의 후 2주 안에 공고와 통지를 하고 이의 기간을 1개월 이상 주어야 합니다.","공고 후 보험계약: 공고일 이후 보험계약을 체결하려면 계약자가 될 자에게 조직변경 절차가 진행 중임을 알리고 승낙을 받아야 하며, 승낙한 계약자는 절차 진행 중 보험계약자가 아닌 자로 본다":"공고 후 새로 계약하려면 조직변경 절차가 진행 중임을 알리고 승낙을 받아야 하며 승낙한 사람은 절차 진행 중 보험계약자가 아닌 것으로 봅니다.","공단은 중소기업퇴직연금기금을 다른 회계와 구분해 관리·운용한다":"공단은 중소기업퇴직연금기금을 다른 회계와 섞이지 않게 따로 관리하고 굴려야 합니다.","공단의 책무: 가입자에 대한 연 1회 이상 교육, 취급실적·운용현황·수익률 공시, 표준계약서 변경 통보. 고용노동부장관이 지도·감독":"공단은 해마다 가입자를 교육하고 운용 실적과 수익률을 공시하며 표준계약서 변경을 알리고 장관의 지도와 감독을 받습니다.","공동불법행위자의 보험자가 손해방지비용을 모두 상환한 경우 다른 공동불법행위자의 보험자가 부담할 부분에 대해 직접 구상할 수 있고, 각 보험자는 보험관계 없는 다른 공동불법행위자에 대해서도 상환의무를 진다":"공동불법행위자의 보험자가 손해방지비용을 모두 갚았다면 다른 보험자의 부담 부분을 직접 구상할 수 있습니다.","공동불법행위자 중 1인의 보험자가 피해자에게 손해배상금을 모두 지급해 다른 보험자들이 공동으로 면책되면 다른 보험자들이 부담할 부분에 대해 직접 구상할 수 있다":"공동불법행위자 한 사람의 보험자가 배상금을 모두 지급해 다른 보험자까지 면책시켰다면 그들의 부담 부분을 직접 구상할 수 있습니다.","공동해손분담액: 피보험자가 지급할 분담액을 보상한다. 공동해손분담가액이 보험가액을 초과하면 그 초과분의 분담액은 보상하지 않는다":"피보험자가 내야 할 공동해손분담액을 보상하되 분담가액이 보험가액을 넘으면 그 초과분의 분담액은 보상하지 않습니다.","공사도급 이행보증보험에서 공사금액과 공사기간은 고지의무의 대상이 되는 중요한 사항이다":"공사도급 이행보증보험에서는 공사금액과 공사기간이 보험자의 인수 판단에 영향을 주므로 고지해야 하는 중요한 사항입니다.","공사도급 이행보증보험의 공사금액·공사기간은 고지의무 대상이다":"공사도급 이행보증보험에서 공사금액과 공사기간은 보험자가 인수를 판단하는 중요한 사항이어서 고지의무 대상입니다.","공제제도는 보험사업과 같은 기능을 하는 유사보험으로, 특별한 사정이 없는 한 상법 보험편을 준용한다":"공제는 보험과 같은 기능을 하는 유사보험이라서 특별한 사정이 없으면 상법의 보험편을 가져와 적용합니다.","과로로 지병인 고혈압이 악화되어 뇌졸중으로 사망한 경우 외래성이 충족되지 않는다. 욕실 페인트 작업 중 고혈압이 악화되어 뇌출혈이 생긴 경우도 보험금 지급의무가 생기지 않는다":"과로로 지병인 고혈압이 나빠져 뇌졸중으로 숨지거나 페인트 작업 중 뇌출혈이 생긴 경우는 외래성이 부족해 보험금 지급의무가 없습니다.","과징금: 보험회사가 제98조(특별이익), 제99조, 제105조, 제106조, 제110조, 제111조, 제127조, 제127조의3, 제128조의3, 제131조를 위반한 경우 부과할 수 있다. 제129조(보험요율 산출 원칙) 위반은 과징금 대상이 아니다. 예: 특별이익 제공은 해당 보험계약의 연간 수입보험료 이하, 모집 위탁 위반은 수입보험료의 100분의 50 이하":"보험회사가 특별이익 제공과 기초서류 작성 원칙 위반 등을 하면 과징금을 부과할 수 있고 보험요율 산출 원칙 위반은 과징금 대상이 아닙니다.","교차모집 예외: 생명보험회사 또는 제3보험업 전업 회사 소속 설계사가 1개의 손해보험회사를 위해, 손해보험회사 또는 제3보험업 전업 회사 소속 설계사가 1개의 생명보험회사를 위해, 생명·손해보험회사 소속 설계사가 1개의 제3보험업 전업 회사를 위해 모집하는 경우":"한 업종의 설계사가 다른 업종 회사 한 곳을 위해 모집하는 교차모집은 정해진 조합에서만 허용됩니다.","교차모집 절차: 교차모집을 하려는 보험설계사는 회사 명칭 등을 적은 서류를 보험협회에 제출하고, 모집하려는 종류에 따른 등록요건을 갖추어 보험협회에 등록한다":"교차모집을 하려는 설계사는 회사 명칭 등을 적은 서류를 보험협회에 내고 모집하려는 종류의 등록요건을 갖춰 보험협회에 등록해야 합니다.","구급차로 환자를 후송한 후 구급차 간이침대로 하차시키다 조작을 잘못해 상해를 입힌 경우. 불법주차된 덤프트럭으로 인한 사고도 운행성이 인정될 수 있다":"구급차로 후송한 환자를 간이침대로 내리다 조작을 잘못해 다친 경우와 불법주차된 덤프트럭 사고도 운행 중 사고로 볼 수 있습니다.","구성: 위원장 포함 5명 이상 7명 이하. 위원장은 해당 사업에서 퇴직연금업무를 담당하는 임원이다. 위원: 근로자 대표 선출자, 자금운용·재무회계·인사노무 부서장, 퇴직연금·자산운용 전문가, 필요 인정자. 적립금이 최소적립금에 미달하면 앞의 세 부류를 각 1명 이상 포함":"위원회는 위원장을 포함해 5명에서 7명이고 위원장은 퇴직연금 담당 임원이며 적립금이 모자라면 세 부류를 각 1명 이상 넣습니다.","구성원이 퇴직하거나 단체 구성원 자격을 상실하면 단체보험 보호는 종료한다. 회사가 퇴직 후에도 보험료를 계속 납입해도 피보험자 지위는 유지되지 않는다":"구성원이 퇴직해 자격을 잃으면 단체보험의 보호가 끝나며 회사가 보험료를 계속 내더라도 피보험자 지위는 유지되지 않습니다.","구조료: 손해 방지를 위해 지급할 구조료를 보상한다. 구조료분담가액이 보험가액을 초과하면 초과분은 보상하지 않는다":"손해를 막기 위해 낸 구조료를 보상하되 구조료분담가액이 보험가액을 넘으면 초과분은 보상하지 않습니다.","국가, 한국은행, 대통령령으로 정하는 금융기관, 주권상장법인, 그 밖에 대통령령으로 정하는 자. 일반보험계약자는 전문보험계약자가 아닌 보험계약자":"전문보험계약자는 국가와 한국은행과 금융기관과 주권상장법인 등 보험을 잘 아는 계약자이고 일반보험계약자는 그 외의 계약자입니다.","국가의 지원: 사용자부담금·가입자부담금·운영 비용 일부 지원. 거짓 부정한 방법으로 지원금을 받으면 환수":"국가는 사용자와 가입자의 부담금과 운영 비용 일부를 지원하고 부정한 방법으로 받은 지원금은 되찾아 갑니다.","국내 대표자: 퇴임한 후에도 후임 대표자 이름·주소의 등기가 있을 때까지 대표자의 권리와 의무를 가진다. 대표자는 이 법상 임원으로 본다":"국내 대표자는 퇴임해도 후임자의 등기가 있을 때까지 권리와 의무를 갖고 이 법에서 임원으로 취급됩니다.","국내자산 보유: 국내에서 체결한 보험계약의 책임준비금·비상위험준비금에 상당하는 자산을 국내에서 보유해야 한다":"외국보험회사 국내지점은 국내에서 맺은 보험계약의 책임준비금과 비상위험준비금에 해당하는 자산을 국내에 두어야 합니다.","국내지점이 영업정지·그 밖의 조치를 받거나 허가취소될 수 있는 사유: 이 법·명령·처분 위반, 금융소비자보호법 위반, 본점이 본국 법령 위반, 그 밖에 보험업 수행이 어렵다고 인정되는 경우. 본점이 외국감독기관으로부터 영업 전부 정지 조치를 받은 것은 허가취소 사유(제1항)이고 영업정지 사유(제2항)가 아니다":"국내지점은 법령 위반이나 본점의 본국 법령 위반 등이 있으면 영업정지나 허가취소를 받을 수 있고 본점의 영업 전부 정지는 허가취소 사유입니다.","그 제3자가 보험계약자·피보험자와 생계를 같이 하는 가족이면 보험자는 권리를 취득하지 못한다. 다만 손해가 가족의 고의로 발생했으면 취득한다":"제삼자가 생계를 같이하는 가족이면 보험자는 권리를 얻지 못하지만 손해가 가족의 고의로 생겼다면 얻습니다.","금융감독원장으로 하여금 하게 할 수 있는 조치는 제134조제1항제1호(주의·경고·문책 요구) 하나뿐이다. 시정명령, 임원 해임권고·직무정지, 영업 일부정지는 금융위원회가 직접 한다":"금융감독원장에게 맡길 수 있는 조치는 주의와 경고와 문책 요구 하나뿐이고 시정명령과 해임권고와 영업 일부정지는 금융위원회가 직접 합니다.","금융기관보험대리점등은 소속 임직원이 아닌 자로 하여금 모집하게 하거나 상담·소개 대가를 지급하지 못한다. 예외: 신용카드업자(겸영여신업자 제외), 농협생명·농협손해보험 상품을 모집하는 조합":"금융기관보험대리점은 소속 임직원이 아닌 자에게 모집을 시키거나 상담 대가를 줄 수 없으며 신용카드업자와 농협의 일부 상품 모집은 예외입니다.","금융위원회는 감독업무 관련 주주 현황과 사업에 관한 보고·자료 제출을 명할 수 있다. 보험회사는 업무와 자산상황에 관해 금융감독원의 검사를 받아야 한다. 금융감독원장은 검사 시 업무·자산 보고, 자료 제출, 관계인의 출석 및 진술을 요구할 수 있고, 외부감사인에게 경영건전성 관련 자료 제출을 요구할 수 있다":"위원회는 주주와 사업 현황을 보고하게 할 수 있고 회사는 금감원 검사를 받으며 감독원장은 자료와 진술을 요구할 수 있습니다.","금융위원회는 보험소비자와 모집종사자 등을 대상으로 보험약관과 안내자료의 이해도를 평가하고 결과를 공시할 수 있다. 평가대행기관은 지정할 수 있다":"위원회는 소비자와 모집종사자를 상대로 약관 이해도를 평가해 공시할 수 있고 평가대행기관도 지정할 수 있습니다.","금융위원회는 선임계리사에게 업무범위에 속하는 사항에 관해 의견을 제출하게 할 수 있다. 선임계리사는 보험상품 개발 직접 수행, 대표이사·최고경영자·최고재무관리책임자 직무 등을 담당할 수 없다":"위원회가 업무범위 사항에 의견을 내게 할 수 있고 선임계리사는 상품 개발을 직접 하거나 대표이사 직무를 맡지 못합니다.","금융위원회는 허가에 조건을 붙일 수 있다. 조건이 붙은 허가를 받은 자는 사정 변경 시 조건 취소·변경을 신청할 수 있고, 금융위원회는 2개월 이내에 결정한다":"금융위원회는 허가에 조건을 붙일 수 있고 조건부 허가를 받은 자는 사정이 바뀌면 조건 변경을 신청할 수 있으며 위원회는 2개월 안에 결정합니다.","금융위원회에 보건복지부, 금융감독원, 보험 관련 기관·단체 등으로 구성하여 둘 수 있다. 위원은 15명 이내(금융위원회 지정 공무원 1, 보건복지부장관 지정 1, 경찰청장 지정 1, 해양경찰청장 지정 1, 금융감독원장 추천 1, 생명·손해보험협회장·보험요율 산출기관장 추천 각 1, 그 밖). 위원 임기는 3년이다":"보험조사협의회는 금융위원회에 두며 관련 기관과 단체의 추천을 받은 15명 이내의 위원으로 구성하고 임기는 3년입니다.","금융위원회의 명령권(제131조제1항): 업무운영이 적정하지 않거나 자산상황이 불량하여 계약자·피보험자 등의 권익을 해칠 우려가 있으면 업무집행방법의 변경, 금융위원회가 지정하는 기관에의 자산 예탁, 자산의 장부가격 변경, 불건전한 자산에 대한 적립금 보유, 가치 없는 자산의 손실처리, 그 밖에 대통령령 조치(계약자 보호에 필요한 사항의 공시 명령)를 명할 수 있다":"운영이 부적정하거나 자산이 부실해 계약자 권익이 우려되면 위원회가 업무 변경, 자산 예탁, 손실처리 등을 명할 수 있습니다.","금융위원회의 조치(제33조 위반 시): 사업자에 대한 주의, 임원에 대한 주의, 직원에 대한 주의·견책·감봉·정직·면직의 요구, 시정명령, 임원 해임권고·직무정지 요구, 6개월 이내 영업 일부정지. 고용노동부장관은 시정명령 불이행 시 업무 이전을 명할 수 있다. 국세청 세무조사 요청 조치는 없다":"제33조를 어기면 주의와 징계 요구, 시정명령, 임원 해임권고, 6개월 이내 영업정지를 할 수 있으나 세무조사 요청 조치는 없습니다.","금융위원회 인가로 설립하는 법인. 순보험요율 산출·검증·제공, 보험정보 수집·제공 및 통계 작성, 조사·연구 등을 한다. 교통법규 위반·운전면허 효력 정보, 질병 통계 등 개인정보를 정해진 범위에서만 이용·제공할 수 있다":"이 법인은 순보험요율과 보험정보, 통계를 다루고 교통법규 위반이나 질병 통계 같은 개인정보는 허용된 범위에서만 씁니다.","금지되는 자산운용: 업무용이 아닌 부동산 소유(저당권 등 실행으로 취득한 부동산은 제외), 특별계정을 통한 부동산 소유, 상품·유가증권 투기 목적 대출, 직접·간접으로 해당 회사 주식을 사도록 하기 위한 대출, 정치자금 대출, 임직원 대출(보험약관대출과 소액대출은 제외)":"업무용 아닌 부동산, 투기 대출, 자사주 매입 대출, 정치자금 대출, 임직원 대출은 금지이고 담보 실행 부동산 등은 예외입니다.","금지행위: 대출 등을 받는 자의 동의를 미리 받지 않고 보험료를 대출등 거래에 포함, 소속 임직원(모집 가능자 제외)에게 모집을 하게 하거나 용인, 점포 외 장소에서의 모집, 모집과 무관한 금융거래로 얻은 개인정보를 동의 없이 모집에 이용 등":"금융기관대리점은 동의 없는 보험료 대출 포함, 무자격 직원 모집, 점포 밖 모집, 개인정보 무단 이용이 금지됩니다.","급여: 기금제도사용자부담금계정의 급여는 DB와 같은 수급요건(연금 55세 이상·가입기간 10년 이상·지급기간 5년 이상), 가입자가 지정한 IRP 계정으로 이전하는 방법으로 지급. 중도인출은 DC 규정(제22조) 준용":"사용자부담금 계정의 급여는 DB와 같은 55세, 10년, 5년 요건을 따르고 가입자가 정한 IRP로 보내며 중도인출은 DC 규정을 준용합니다.","급여는 가입자가 지정한 IRP 계정 등으로 이전하여 지급. 55세 이후 퇴직, 담보대출 상환, 고시 금액 이하, 사망 등은 예외":"DB 급여도 가입자가 정한 IRP 계좌로 보내 주는 것이 원칙이며 55세 이후 퇴직이나 사망 등은 예외입니다.","급여수준: 가입자의 퇴직일을 기준으로 산정한 일시금이 계속근로기간 1년에 대하여 30일분 이상의 평균임금이 되도록 한다":"급여수준은 퇴직일 기준 일시금이 근속 1년당 평균임금 30일분 이상이 되는 정도로 정해야 합니다.","급여의 종류: 연금 또는 일시금. 연금은 55세 이상이고 가입기간 10년 이상인 가입자에게 지급하며 지급기간은 5년 이상. 일시금은 연금 수급요건을 갖추지 못했거나 일시금을 원하는 가입자에게 지급":"DB 급여는 연금과 일시금으로 나뉘며 연금은 55세 이상에 가입 10년 이상이고 5년 이상 나누어 받는 경우에 줍니다.","급여 지급기한: 지급사유 발생일부터 14일 이내에 퇴직연금사업자가 적립금 범위에서 지급의무가 있는 급여 전액을 지급(도산 등은 비율 지급). 부족하면 사용자가 14일 이내에 부족액을 지급":"급여는 사유가 생긴 날부터 14일 안에 연금사업자가 적립금 범위에서 주고 모자라면 사용자가 14일 안에 채웁니다.","기금은 금전 이외의 자산으로 납입하지 못한다":"상호회사의 기금은 현금으로만 납입할 수 있고 금전이 아닌 자산으로는 낼 수 없습니다.","기명피보험자의 승낙을 얻어 자동차를 사용·관리하는 자. 승낙은 명시적·개별적일 필요 없이 묵시적·포괄적이어도 된다. 렌터카를 빌린 사람은 승낙피보험자다":"승낙피보험자는 기명피보험자의 승낙을 얻어 차를 쓰는 사람이며 승낙은 묵시적이거나 포괄적이어도 되고 렌터카를 빌린 사람이 그 예입니다.","기재사항: 보험회사 상호·명칭 또는 설계사·대리점·중개사의 이름·상호, 보험 가입에 따른 권리·의무 주요 사항, 보험약관으로 정하는 보장, 보험금 지급제한 조건, 해약환급금, 예금자보호법에 따른 예금자보호 사항, 그 밖에 대통령령 사항(금리연동 적용금리·보험금 변동, 보험금 지급제한 조건 예시, 안내자료 제작자·제작일·심사 또는 관리번호, 보험 상담 및 분쟁 해결 사항)":"보험안내자료에는 회사와 모집자의 이름과 권리의무와 보장과 지급제한 조건과 해약환급금과 예금자보호 사항과 상담 및 분쟁 해결 사항 등을 적습니다.","기존계약을 부당하게 소멸시키고 새 계약을 청약하게 하는 행위, 실제 명의인이 아닌 자의 계약 모집 또는 실제 명의인의 동의 없는 모집, 자필서명이 필요한 경우 대신 서명, 다른 모집종사자 명의 이용, 금전대차 관계를 이용한 청약 요구, 정당한 이유 없는 장애인 가입 거부, 청약철회·해지 방해":"계약 부당 소멸, 명의 도용, 대리 서명, 금전대차를 이용한 청약 요구, 장애인 가입 거부, 철회 방해는 모집 때 금지됩니다.","기존 계약을 연장·변경한 경우 보험증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다":"이미 있는 계약을 연장하거나 바꿨다면 새 증권 대신 기존 증권에 그 사실을 적어 주는 것으로 대신합니다.","기존계약의 부당 소멸 간주: 기존계약이 소멸된 날부터 1개월 이내에 새 계약을 청약하게 하거나 새 계약 청약일부터 1개월 이내에 기존계약을 소멸하게 하는 행위. 계약자가 손해 가능성을 알고 있음을 자필 서명 등으로 명백히 증명하면 예외. 6개월 이내이면서 중요한 사항을 비교하여 알리지 않은 경우도 포함":"기존계약 소멸 1개월 안에 새 계약을 청약하게 하는 것은 부당 소멸로 보되 계약자가 손해를 알고 서명했으면 예외입니다.","기초서류: 보험종목별 사업방법서, 보험약관, 보험료 및 해약환급금 산출방법서":"기초서류는 보험종목별로 만든 사업방법서와 보험약관과 보험료 및 해약환급금 산출방법서를 가리킵니다.","기초서류관리기준: 작성·변경 절차와 기준, 내부·외부 검증 절차, 오류 통제·수정, 감시·통제·평가 방법과 임직원·선임계리사의 역할과 책임 등을 포함한다. 제정·개정 시 금융위원회에 보고하고 부당하면 변경·개선 명령":"기초서류관리기준은 작성과 변경 절차, 내외부 검증, 오류 통제, 역할과 책임을 정하며 제정과 개정 시 위원회에 보고합니다.","기초서류 변경 권고: 신고 내용·제출 자료가 작성·변경 원칙(제128조의3)이나 요율 원칙(제129조)을 위반하면 금융위원회가 변경을 권고할 수 있다":"신고한 기초서류가 작성 변경 원칙이나 요율 원칙을 어기면 금융위원회가 변경을 권고할 수 있습니다.","기초서류 신고: 작성·변경 시 법령 제정·개정에 따라 새로운 보험상품이 도입되거나 가입이 의무가 되는 경우 등 법정 사유에 한해 미리 금융위원회에 신고. 신고를 받으면 내용을 검토해 이 법에 적합하면 수리해야 한다. 판매개시일 30일 전까지 신고(권고사항 반영 시 15일)":"기초서류는 법정 사유가 있을 때 판매개시일 30일 전까지 미리 신고하며 금융위원회는 내용을 검토해 법에 맞으면 수리해야 합니다.","기초서류에 기재된 사항은 준수해야 한다":"보험회사는 기초서류에 적어 둔 사항을 그대로 지켜야 합니다.","기초서류의 변경·사용정지 명령: 공익·계약자 보호와 건전 경영을 크게 해칠 우려가 있거나 기초서류에 법령 위반·계약자에게 불리한 내용이 있다고 인정되면 청문을 거쳐 명할 수 있다. 법령 개정에 따라 변경이 필요한 경미한 사항은 청문을 생략할 수 있다":"기초서류가 공익을 크게 해치거나 법령 위반이면 청문을 거쳐 변경이나 사용정지를 명하며 경미한 개정 반영은 청문이 필요 없습니다.","기초서류 작성·변경 원칙: 이 법 또는 다른 법령 위반 내용 불포함, 정당한 사유 없는 계약자 권리 축소·의무 확대 등 불리한 내용 불포함, 금융위원회가 정하는 기준 적합":"기초서류에는 법령 위반이나 계약자에게 부당하게 불리한 내용이 없어야 하고 위원회 기준에도 맞아야 합니다.","기초서류 확인: 금융위원회는 필요하면 신고 시 금융감독원의 확인을 받도록 할 수 있고, 보험료·해약환급금 산출방법서에 보험요율 산출기관 또는 독립계리업자의 검증확인서를 첨부하게 할 수 있다. 독립계리업자는 5명 이상 상근 보험계리사를 둔 법인":"기초서류 신고 때 금감원 확인이나 요율산출기관의 검증확인서를 붙이게 할 수 있고 독립계리업자는 상근 계리사 5명 이상의 법인입니다.","기평가보험: 당사자 간에 보험가액을 정한 때 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다. 사고발생시 가액을 현저히 초과하면 사고발생시의 가액을 보험가액으로 한다":"기평가보험에서 정한 보험가액은 사고 때 가액으로 정한 것으로 추정하고 현저히 초과하면 사고 때의 가액을 보험가액으로 합니다.","낙부통지: 보험자가 청약과 함께 보험료 상당액의 전부 또는 일부를 받은 때에는 다른 약정이 없으면 30일 내에 청약자에게 낙부의 통지를 발송해야 한다":"청약과 함께 보험료를 받은 보험자는 다른 약정이 없으면 30일 안에 청약자에게 승낙할지를 알려야 합니다.","낙부통지를 기간 내에 해태하면 승낙한 것으로 본다(간주)":"보험자가 정해진 기간 안에 낙부통지를 하지 않으면 승낙한 것으로 간주되어 계약이 성립합니다.","납입 시기: 매년 1회 이상 정기적으로 납입한다. 납입기일을 지키지 않으면 다음 날부터 지연이자(연 100분의 40 이내의 범위에서 대통령령 이율)를 납입한다. 대통령령 이율은 정해진 날 다음 날부터 퇴직 등 사유 발생 후 14일까지 연 100분의 10, 그 다음 날부터 납입일까지 연 100분의 20":"부담금은 해마다 한 번 이상 내야 하며 늦으면 다음 날부터 지연이자가 붙고 이율은 연 100분의 10에서 100분의 20으로 오릅니다.","다른 보험계약 등에 관한 통지: 피보험자는 위부 시 다른 보험계약과 채무의 유무·종류·내용을 통지해야 하고, 보험자는 통지를 받을 때까지 보험금액 지급을 거부할 수 있다":"위부할 때 피보험자는 다른 보험계약과 채무의 유무와 내용을 통지해야 하고 보험자는 통지를 받을 때까지 지급을 거부할 수 있습니다.","다른 보험계약의 존재: 청약서에서 질문한 경우 고지 대상이 된다. 해지하려면 계약자가 존재를 안 것 외에 중요사항임을 알았거나 중과실로 몰랐다는 사실을 보험자가 입증해야 한다":"청약서가 물은 다른 보험의 존재는 고지 대상이며 보험자가 해지하려면 계약자가 중요사항임을 알았거나 중과실로 몰랐음을 입증해야 합니다.","다른 보험회사등에 소속된 설계사에게 모집을 위탁하지 못하고, 설계사는 자기 소속 외의 자를 위해 모집하지 못한다":"보험회사는 다른 회사에 소속된 설계사에게 모집을 맡기지 못하고 설계사도 자기 소속 외의 회사를 위해 모집할 수 없습니다.","다른 보험회사의 선임계리사를 해당 보험회사의 선임계리사로 선임할 수 없다. 선임계리사가 업무정지 명령을 받으면 대행할 사람을 선임해 금융위원회에 보고한다":"선임계리사는 타사 사람으로 선임할 수 없고 업무정지를 당하면 대행자를 정해 위원회에 보고해야 합니다.","다른 생명보험을 다수 가입했다는 사정만으로는 위험변경증가 통지의무가 없다. 다만 다른 보험 체결 시 통지하게 하는 약정은 유효하고, 위반하면 해지할 수 있다":"생명보험을 여러 개 들었다는 사정만으로 통지의무가 생기지 않지만 통지하기로 약정했다면 위반 시 해지할 수 있습니다.","다른 생명보험 존재를 청약서로 질문한 경우 고지 대상이다. 다수 가입만으로 위험변경증가 통지의무가 생기지는 않는다":"청약서에서 다른 생명보험의 존재를 물었다면 고지 대상이지만 다수 가입했다는 사정만으로 위험 증가 통지의무가 생기지는 않습니다.","다른 약정이 없으면 운송의 필요에 의해 일시 운송을 중지하거나 노순·방법을 변경해도 보험계약은 효력을 잃지 않는다":"운송에 필요해서 잠시 멈추거나 경로와 방법을 바꿔도 다른 약정이 없으면 보험계약은 효력을 잃지 않습니다.","다른 회사 출자 제한: 다른 회사 의결권 있는 발행주식 총수의 100분의 15를 초과하는 주식을 소유할 수 없다(승인받은 자회사 제외)":"보험회사는 다른 회사 의결권 있는 발행주식 총수의 100분의 15를 넘게 소유할 수 없고 승인받은 자회사만 예외입니다.","다만 계약자가 사망한 경우 그 승계인이 지정·변경권을 행사할 수 있다는 약정이 있으면 그에 따른다":"계약자가 사망했을 때 승계인이 지정권과 변경권을 행사할 수 있다는 약정이 있다면 그 약정이 우선합니다.","다수 피해자 총 피해액이 한도를 초과하면 직접청구권자 사이에 우선순위가 없어 각자 자기 권리 전부를 주장할 수 있고, 보험자는 누구에게든 유효하게 변제할 수 있다":"피해자가 여러 명이고 한도를 넘으면 우선순위가 없어 각자 전액을 청구하며 보험자는 아무에게나 갚아도 유효합니다.","단기수출보험 약관이 계약자의 손실만 보상하고 보험금수취인의 손실에 관한 규정이 없다면 타인을 위한 보험으로 볼 수 없다":"약관에 계약자의 손실만 보상한다고 되어 있고 수취인 손실 규정이 없으면 타인을 위한 보험이 아닙니다.","단체가 규약에 따라 구성원의 전부 또는 일부를 피보험자로 하는 생명보험계약을 체결하는 경우 제731조(서면동의)를 적용하지 않는다":"단체가 규약에 따라 구성원을 피보험자로 하는 생명보험은 개별 구성원의 서면동의를 받지 않아도 됩니다.","단체규약에 채용·해고·재해부조만 있고 보험가입에 관한 정함이 없으면 피보험자의 동의를 받아야 한다":"단체규약이 채용, 해고, 재해부조만 정할 뿐 보험가입을 정하지 않았다면 피보험자 개인의 동의를 받아야 합니다.","단체보험은 타인의 생명보험계약이며 구성원이 수익자일 필요는 없다":"단체보험은 구성원의 생명을 보험에 붙이는 타인의 생명보험이고 구성원이 반드시 보험수익자가 될 필요는 없습니다.","담보제공·공탁으로 집행을 면할 수 있는 경우 보험금액 한도 내에서 청구할 수 있다":"담보를 제공하거나 공탁해서 강제집행을 피할 수 있는 상황이면 보험금액 한도 안에서 그 비용을 청구할 수 있습니다.","담보 제공 한도: (1)~(6)은 가입자별 적립금의 100분의 50, (7)은 고용노동부장관 고시 한도. 배우자 명의 주택 구입은 사유에 해당하지 않는다":"담보 제공은 가입자별 적립금의 절반까지만 가능하고 재난이나 휴업은 장관 고시 한도를 따르며 배우자 명의 집은 안 됩니다.","당사자 일방이 약정한 보험료를 지급하고, 상대방이 재산 또는 생명·신체에 불확정한 사고가 발생할 경우 일정한 보험금이나 그 밖의 급여를 지급할 것을 약정함으로써 효력이 생긴다":"보험계약은 한쪽이 보험료를 내고 상대가 사고가 났을 때 보험금을 주기로 약속하면 효력이 생기는 계약입니다.","대리인이 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다":"대리인이 계약을 맺었다면 그 대리인이 알았던 사정은 본인이 안 것과 같이 취급합니다.","대선에 의한 운송 계속: 선박이 심하게 훼손된 경우(제710조제2호)에 선장이 지체없이 다른 선박으로 적하의 운송을 계속하면 피보험자는 그 적하를 위부할 수 없다":"선박이 심하게 훼손되었어도 선장이 곧바로 다른 선박으로 적하 운송을 이어 가면 피보험자는 그 적하를 위부할 수 없습니다.","대주주가 다른 회사에 출자하는 것을 지원하기 위한 신용공여 금지, 무상 양도·불리한 조건 거래 금지. 일정 금액 이상 신용공여·대주주 발행 채권·주식 취득은 미리 이사회 의결(재적이사 전원의 찬성)":"대주주의 출자 지원용 신용공여와 무상 양도는 금지이고 일정 금액 이상 거래는 재적이사 전원 찬성의 이사회 의결이 필요합니다.","대주주 거래 보고: 일정 금액 이상 신용공여, 대주주 발행 채권·주식 취득, 대주주 발행 주식에 대한 의결권 행사는 7일 이내에 금융위원회에 보고하고 공시. 대주주 신용공여·취득 사항은 분기별로 보고·공시":"대주주와의 일정 규모 이상 거래는 7일 안에 보고하고 공시하며 분기마다 모아서도 보고하고 공시합니다.","대주주에 대한 조치: 대주주(회사)의 부채가 자산을 초과하는 등 재무구조가 부실하면 금융위원회는 신규 신용공여·유가증권 신규 취득 금지 등을 할 수 있다":"대주주인 회사의 부채가 자산을 넘는 등 재무구조가 부실하면 금융위원회는 그 대주주에 대한 신규 신용공여와 유가증권 취득을 금지할 수 있습니다.","대통령령으로 정하는 자본감소(주식 금액 또는 주식 수의 감소에 따른 자본금의 실질적 감소)는 미리 금융위원회의 승인을 받아야 한다":"주식 금액이나 수를 줄여 자본금이 실질적으로 줄어드는 자본감소는 미리 금융위원회의 승인을 받아야 합니다.","대한민국 이외의 국가의 법령에 따라 설립되어 대한민국 이외의 국가에서 보험업을 경영하는 자":"외국보험회사는 우리나라가 아닌 다른 나라의 법에 따라 만들어져 그 나라에서 보험업을 하는 회사입니다.","독립적으로 보험계약 체결을 중개하는 자로 제89조에 따라 등록된 자":"보험중개사는 특정 회사에 매이지 않고 독립적으로 보험계약 체결을 중개하는 사람으로 등록한 자입니다.","동산과 부동산을 함께 부보한 화재보험에서 동산이 중고품인데 신품으로 고지한 경우, 특별한 사정이 없으면 해지는 동산에 관한 부분에 한하고 부동산 계약까지 해지하는 것은 아니다(2026 기출 보기 가는 틀린 보기)":"동산과 부동산을 함께 가입한 화재보험에서 동산만 허위고지했다면 특별한 사정이 없는 한 동산 부분만 해지하고 부동산 계약은 그대로입니다.","동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시 또는 순차로 체결되고 보험금액 총액이 보험가액을 초과한 때 보험자는 각자의 보험금액의 한도에서 연대책임을 진다":"여러 보험이 겹쳐 보험금액 합계가 보험가액을 넘으면 보험자들이 각자 보험금액 한도에서 연대해 책임집니다.","될 수 있는 금융기관: 은행, 투자매매업자·투자중개업자, 상호저축은행, 한국산업은행, 중소기업은행, 신용카드업자(겸영여신업자 제외), 농협 조합·농협은행 등. 신탁업자는 아니다":"금융기관보험대리점이 될 수 있는 곳은 은행과 투자매매 중개업자와 상호저축은행과 신용카드업자와 농협 등이며 신탁업자는 해당하지 않습니다.","둘 이상의 사용자가 참여하는 DC제도: 퇴직연금사업자가 표준규약과 표준계약서에 대해 고용노동부장관의 승인을 받아야 한다":"여러 사용자가 함께 DC를 운영하려면 연금사업자가 표준규약과 표준계약서에 대해 장관 승인을 받아야 합니다.","둘 이상의 수익자 중 일부가 고의로 피보험자를 사망하게 해도 보험자는 다른 수익자에 대한 지급책임을 면하지 못한다":"수익자가 여러 명일 때 일부가 고의로 피보험자를 숨지게 해도 보험자는 다른 수익자에 대한 지급책임을 면하지 못합니다.","등록: 개인과 법인으로 구분해 금융위원회에 등록(등록업무는 금융감독원장 위탁). 생명·손해·제3보험중개사로 구분. 될 수 없는 자: 결격사유자, 설계사·대리점으로 등록된 자, 다른 보험회사등 임직원, 부채가 자산을 초과하는 법인":"보험중개사는 개인과 법인으로 나눠 등록하고 결격사유자와 설계사와 대리점으로 등록된 자와 부채가 자산을 넘는 법인은 될 수 없습니다.","등록 제한 대상(영 제32조): 국가기관과 특별법에 따라 설립된 기관 및 그 기관 퇴직자로 구성된 법인·단체, 그런 기관·금융지주회사·금융기관의 지배를 받는 법인·단체, 금융위법 제38조의 기관 일부, 이들의 임직원 등":"국가기관과 특별법상 기관과 그 퇴직자로 구성된 단체와 금융기관의 지배를 받는 단체와 그들의 임직원은 보험대리점으로 등록할 수 없습니다.","등록취소: 해산한 경우, 거짓·부정한 방법으로 등록한 경우는 반드시 취소. 등록요건 상실, 장관·금융위 명령 불이행은 시정명령 또는 취소(임의). 취소된 업자는 3년, 말소된 업자는 2년간 재등록할 수 없다":"해산하거나 부정하게 등록한 업자는 반드시 등록이 취소되고 요건 상실이나 명령 불이행은 임의 취소이며 재등록 제한은 3년과 2년입니다.","만취 상태에서 건물에 올라갔다 구토 중 추락한 사고, 자동차상해보험에서 무면허 또는 안전띠 미착용으로 인한 사고는 보험금 지급의무가 있다":"만취해 건물에 올라갔다가 구토 중 추락한 사고나 무면허나 안전띠 미착용 사고는 보험자가 보험금을 지급해야 합니다.","매수인이 소유권이전등록 없이 인도받아 운행하며 매도인과의 합의로 매도인을 피보험자로 하는 종합보험을 체결한 경우 승낙피보험자가 될 수 있다":"등록 이전 없이 차를 인도받아 운행하는 매수인이 매도인과 합의해 매도인을 피보험자로 보험을 든 경우에는 승낙피보험자가 될 수 있습니다.","면책약관은 제한적·엄격하게 해석하여 적용범위를 확대하지 않는다":"보험자의 책임을 덜어 주는 면책약관은 좁고 엄격하게 풀어야 하며 적용 범위를 넓혀서는 안 됩니다.","명칭에 '상호회사' 글자를 포함해야 한다. 사원은 100명 이상으로 설립한다":"상호회사는 명칭에 상호회사라는 글자를 넣어야 하고 사원이 100명 이상이어야 설립할 수 있습니다.","모집 방법: 점포 내 지정 장소에서 대면 모집, 인터넷 홈페이지 안내, 통신수단(신용카드업자만). 점포별 2명 범위에서 등록된 소속 임직원으로 모집에 종사하게 할 수 있다(신용카드업자 제외)":"점포 안 지정 장소에서의 대면과 홈페이지 안내가 모집 방법이고 점포별 2명까지 등록 임직원이 모집에 종사합니다.","모집인 준수사항: 위탁받은 업무를 다시 위탁하지 말 것, 둘 이상의 퇴직연금사업자와 위탁계약을 체결하지 말 것, 허위 사실에 근거한 모집 금지, 사업자·가입예정 사용자를 대리해 계약을 체결하지 말 것, 사용자·가입자로부터 금전·재산상 가치 있는 것을 받지 말 것, 사용자·가입자의 적립금 운용방법 지시를 대리하지 말 것. 지시를 단순히 전달하는 업무는 가능":"모집인은 재위탁과 이중 위탁, 허위 모집, 계약 대리, 금품 수수, 운용지시 대리를 하면 안 되고 지시를 단순히 전달하는 것은 됩니다.","무면허 운전은 중과실에 해당할 수 있으나 사망·상해에 대한 고의는 아니므로 보험자는 면책되지 않는다":"무면허 운전은 중과실일 수 있지만 사망이나 상해에 대한 고의가 아니므로 보험자는 면책되지 않습니다.","무보험자동차 상해 담보는 실손보상 성격으로 중복보험 법리가 적용된다. 자기신체사고는 상해보험에 속하며, 대인배상으로 받을 금액을 공제하는 약관은 제729조 위반이 아니다(판례)":"무보험자동차 상해 담보는 실손보상이라 중복보험 법리가 적용되고 자기신체사고는 상해보험이어서 대인배상액을 공제하는 약관은 법 위반이 아닙니다.","무역보험도 무역보험법에 특별한 규정이 없으면 상법 보험편이 적용된다":"무역보험은 무역보험법에 특별한 규정이 없는 사항에 대해서는 상법 보험편이 적용됩니다.","무효인 보험계약에 따라 납부한 보험료 반환청구권의 소멸시효는 각 보험료를 납부한 때부터 진행한다":"무효 계약에서 낸 보험료의 반환청구권은 보험료를 낸 때마다 각각 그때부터 소멸시효가 진행합니다.","미등기건물도 금전으로 산정할 수 있는 이익이면 화재보험의 목적이 될 수 있다":"등기가 없는 건물도 금전으로 따질 수 있는 이익이 있으면 화재보험에 들 수 있는 대상입니다.","미평가보험: 보험가액을 정하지 않은 때 사고발생시의 가액을 보험가액으로 한다":"미평가보험은 보험가액을 미리 정하지 않았으므로 사고가 났을 때의 가액을 보험가액으로 삼습니다.","반면 보험계약 체결 후 매매되어 기명피보험자가 인도·이전등록을 마쳐 운행지배를 상실했다면 매수인은 승낙피보험자가 아니다":"계약 뒤 차를 팔고 인도와 이전등록까지 마친 기명피보험자는 운행지배를 잃어 매수인이 승낙피보험자가 되지 못합니다.","발기인이 정관을 작성하여 취급 보험종목·사업의 범위, 명칭, 사무소 소재지, 기금 총액, 기금 갹출자의 권리, 기금·설립비용 상각 방법, 잉여금 분배 방법, 공고 방법, 성립 후 양수할 자산, 존립시기·해산사유 등을 적고 기명날인한다":"상호회사는 발기인이 보험종목과 명칭과 기금 총액과 잉여금 분배 방법 등을 적은 정관을 만들어 기명날인해서 설립합니다.","배당보험계약: 이익의 일부를 계약자에게 배당하기로 약정한 보험계약. 다른 계약과 구분하여 회계처리. 재평가적립금은 금융위원회 허가를 받아 계약자 배당에 처분할 수 있다":"배당보험은 이익의 일부를 계약자에게 나누기로 한 보험이며 별도로 회계처리하고 재평가적립금은 허가를 받아 배당에 씁니다.","배상책임보험에서 추가 누수 방지를 위한 방수공사비·누수 정밀검진비는 손해방지비용이다":"배상책임보험에서 추가 누수를 막으려고 쓴 방수공사비와 누수 정밀검진비는 손해방지비용에 해당합니다.","배상청구기준 약관: 배상청구가 보험기간 내에 이루어지면 원인사고가 보험기간 개시 전이어도 보험자의 책임을 인정하는 약관은 유효하다":"배상청구가 보험기간 안에 있었다면 원인 사고가 기간 전이어도 보험자 책임을 인정하는 배상청구기준 약관은 유효합니다.","벌칙: 퇴직금 미지급(5년 이하 징역 또는 5천만원 이하 벌금), 사업자 가입자 보호조치 불이행·제33조제3항·제4항 위반(3년 이하/3천만원 이하), 퇴직급여제도 차등 설정(2년 이하/2천만원 이하), 근로자대표 동의·의견 청취 위반(500만원 이하 벌금)":"퇴직금을 안 주면 5년 이하 징역이나 5천만원 이하 벌금이고 차등 설정이나 동의 위반 등은 각각 더 낮은 형이 정해져 있습니다.","법령에 규정된 내용을 반복하거나 부연하는 정도의 약관은 설명의무의 대상이 아니다":"법령에 이미 있는 내용을 되풀이하거나 풀어 쓴 정도의 약관은 따로 설명하지 않아도 됩니다.","법인보험중개사의 임원: 금고 이상 실형을 선고받고 집행 종료·면제 후 3년이 지나지 않은 자는 될 수 없다. 보험모집 위반 시 6개월 이내 업무정지 또는 등록취소 가능":"법인중개사 임원은 실형 집행이 끝나고 3년이 안 되면 될 수 없고 모집 위반 때 6개월 이내 정지나 취소를 받습니다.","변경: 사전지정운용방법은 고용노동부장관의 승인을 받아 변경할 수 있다(금융위원회 승인이 아님). 변경 승인 후 14일이 지난 날부터 변경된 방법으로 운용될 수 있다":"사전지정운용방법을 바꾸려면 고용노동부장관 승인이 필요하고 승인 14일 뒤부터 바뀐 방법이 적용될 수 있습니다.","변경명령의 효력: 특히 필요하다고 인정하면 이미 체결된 계약에도 장래에 향하여 효력이 미치게 할 수 있다. 부당한 불이익이 명백하면 납입 보험료의 일부 환급 또는 보험금 증액을 하게 할 수 있다. 변경명령을 받은 보험회사는 전국 배포 둘 이상의 일간신문에 각 1회 이상 공고한다":"변경명령은 이미 맺은 계약에도 앞으로 효력을 줄 수 있고 불이익이 분명하면 환급이나 보험금 증액을 하게 하며 신문에 공고합니다.","변액보험의 경우 안내자료에 원금 손실 가능성(손실은 계약자 귀속)과 최저보장 보험금이 설정되어 있으면 그 내용을 적는다":"변액보험의 안내자료에는 원금 손실 가능성과 그 손실이 계약자에게 돌아간다는 점과 최저보장 보험금이 있다면 그 내용을 적어야 합니다.","보고사항(5일 이내): 상호·명칭 변경, 본점 영업 중지·재개, 최대주주 변경, 대주주 소유 주식 총수가 의결권 있는 발행주식 총수의 100분의 1 이상 변동, 자본금·기금 증액, 조직변경 결의, 벌칙 처분, 조세 체납처분·조세법 위반 형벌, 해외투자·외국 영업소 설치, 주주 또는 주주였던 자가 제기한 소송의 당사자가 된 경우":"상호나 최대주주 변경, 증자, 조직변경 결의, 소송 당사자가 된 사실 등은 5일 안에 위원회에 보고합니다.","보증보험에는 성질에 반하지 않는 범위에서 보증채무에 관한 민법 규정을 준용한다":"보증보험에는 성질에 어긋나지 않는 범위에서 민법의 보증채무 규정을 준용합니다.","보증보험에는 제639조제2항 단서(타인을 위한 손해보험에서 계약자의 배상 후 보험금 청구)를 적용하지 않는다":"보증보험에는 타인을 위한 손해보험에서 계약자가 먼저 배상한 뒤 보험금을 청구하게 한 규정을 적용하지 않습니다.","보증보험자는 약관상 절차에 따라 보험금액 한도 내에서 피보험자가 실제 입은 손해를 보상한다. 정액보상 합의가 있으면 약정된 정액금을 지급한다":"보증보험자는 약관 절차대로 한도 안에서 실제 손해를 메우되 정액 합의가 있으면 약정액을 지급합니다.","보증보험 체결 당시 이미 주계약상 채무불이행이 불가능한 경우 보증보험계약은 무효이며 선의의 제3자도 유효를 주장할 수 없다":"보증보험을 맺을 때 이미 주계약상 채무불이행이 불가능했다면 계약은 무효이고 선의의 제삼자도 유효를 주장할 수 없습니다.","보험가액의 일부를 보험에 붙인 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상한다. 당사자 간 다른 약정이 있으면(1차 위험담보 등) 보험금액 한도 내에서 손해를 보상한다":"보험가액의 일부만 보험에 들었다면 비율대로 보상하고 1차 위험담보처럼 다르게 약정하면 보험금액 한도에서 손해를 보상합니다.","보험계리사는 금융감독원장이 실시하는 시험 합격과 실무수습 후 금융위원회에 등록한다. 보험계리업을 하려는 자는 금융위원회에 등록하며(수수료 총리령), 법인은 2명 이상의 상근 보험계리사를 두고 등록일부터 1개월 내에 업무를 시작해야 한다":"계리사는 감독원장 시험과 실무수습을 거쳐 등록하고 계리업 법인은 상근 2명 이상을 두며 등록 1개월 안에 영업을 시작합니다.","보험계리사만(및 보험계리업자) 수행할 수 있는 업무: 상품 공시자료 중 기초서류와 관련된 사항. 선임계리사는 이 업무를 수행할 수 없다":"상품 공시자료 중 기초서류와 관련된 사항은 보험계리사와 보험계리업자만 할 수 있고 선임계리사는 이 업무를 할 수 없습니다.","보험계리사 업무 범위(총리령): 책임준비금·비상위험준비금 등 준비금의 적립과 그 자산의 적정성, 잉여금의 배분·처리 및 계약자 배당금 배분, 지급여력비율 계산 중 보험료·책임준비금 관련 사항, 기초서류 관련 사항 등. 기초서류와 관련 없는 상품 공시자료는 업무 대상이 아니다":"계리사는 준비금 적립과 자산 적정성, 잉여금과 배당금 배분, 지급여력비율 중 일부, 기초서류 사항을 다루며 상품공시 자료는 제외됩니다.","보험계약 당시 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 중요한 사항을 고지하지 않거나 부실하게 고지하면 보험자가 계약을 해지할 수 있다":"계약 당시 고의나 중과실로 중요한 사항을 알리지 않거나 거짓으로 알리면 보험자가 계약을 해지할 수 있습니다.","보험계약으로 생긴 권리를 피보험자가 아닌 자에게 양도하는 경우에도 타인의 서면동의가 필요하다":"보험계약에서 생긴 권리를 피보험자가 아닌 사람에게 넘길 때도 타인의 서면동의가 필요합니다.","보험계약으로 생긴 권리를 피보험자가 아닌 자에게 양도하는 경우에도 타인의 서면동의를 얻어야 한다":"보험계약으로 생긴 권리를 피보험자가 아닌 사람에게 넘길 때도 그 타인의 서면동의를 받아야 합니다.","보험계약의 당사자: 보험자와 보험계약자. 피보험자와 보험수익자는 관계자다":"계약 당사자는 보험자와 보험계약자뿐이고 피보험자와 보험수익자는 계약에 이해관계를 가진 관계자입니다.","보험계약의 무효를 보험자가 사고 후에 비로소 주장해도 특별한 사정이 없는 한 신의칙 위반이 아니다":"보험자가 사고가 난 뒤에 비로소 계약의 무효를 주장해도 특별한 사정이 없다면 신의칙 위반이 아닙니다.","보험계약의 체결을 중개하거나 대리하는 것":"모집은 보험계약의 체결을 중개하거나 대리하는 행위를 가리킵니다.","보험계약자가 보험료 전부 또는 최초의 보험료를 지급하지 않은 때는 교부의무가 없다":"보험계약자가 보험료 전부나 첫 보험료를 내지 않았다면 보험자는 증권을 교부할 의무가 없습니다.","보험계약자가 자기 이외의 제3자를 보험수익자로 지정한 계약":"타인을 위한 생명보험계약은 보험계약자가 자기가 아닌 제삼자를 보험수익자로 지정해 맺은 계약입니다.","보험계약자가 타인을 수익자로 한 상해보험이 무효인 경우 보험자는 수익자에게 이미 급부한 것의 반환을 청구할 수 있다":"타인을 수익자로 한 상해보험이 무효라면 보험자는 이미 수익자에게 준 보험금을 돌려 달라고 청구할 수 있습니다.","보험계약자가 피보험자에게 계약상 채무불이행 또는 법령상 의무불이행으로 입힌 손해를 보상한다":"보증보험자는 계약자가 계약상 채무나 법령상 의무를 지키지 않아 피보험자에게 입힌 손해를 보상합니다.","보험계약자는 동일할 필요가 없으나 피보험자는 동일해야 하며, 보험기간은 전부 공통될 필요 없이 중복되는 기간에 한해 중복보험이다":"중복보험은 계약자는 달라도 피보험자는 같아야 하며 보험기간은 겹치는 기간에 한해서만 중복보험이 됩니다.","보험계약자는 보험료를 지급할 의무가 있다. 계약자가 파산하거나 보험료 지급을 지체한 때는 타인이 권리를 포기하지 않는 한 타인도 지급 의무가 있다":"보험료를 낼 의무는 계약자에게 있으나 계약자가 파산하거나 지체하면 권리를 포기하지 않은 타인도 보험료를 내야 합니다.","보험계약자는 보험수익자를 지정 또는 변경할 권리가 있다. 지정·변경권은 보험자나 수익자의 동의가 필요 없는 형성권이고, 상대방 없는 단독행위다":"계약자는 수익자를 지정하거나 바꿀 권리가 있고 이는 보험자나 수익자의 동의 없이 혼자 하는 형성권이며 상대방 없는 단독행위입니다.","보험계약자는 위임을 받거나 받지 않고 특정 또는 불특정의 타인을 위하여 계약할 수 있다":"보험계약자는 타인의 위임이 없어도 특정이나 불특정의 타인을 위한 보험계약을 맺을 수 있습니다.","보험계약자와 피보험자는 손해의 방지와 경감을 위해 노력해야 한다. 필요 또는 유익하였던 비용과 보상액의 합계가 보험금액을 초과해도 보험자가 부담한다":"계약자와 피보험자는 손해를 막고 줄이려 노력해야 하며 그 비용과 보상액의 합이 보험금액을 넘더라도 보험자가 부담합니다.","보험계약자의 대리인과 계약을 체결한 경우 그 대리인에게 설명하면 된다":"계약자 쪽 대리인과 계약했다면 본인이 아니라 그 대리인에게 설명하는 것으로 충분합니다.","보험계약자의 사기·고의·중과실이 있어도 피보험자에게 책임 있는 사유가 없으면 제651조(고지의무), 제652조·제653조(위험변경증가), 제659조제1항(고의·중과실 면책)을 적용하지 않는다":"피보험자 본인에게 책임이 없으면 계약자의 사기나 고의가 있어도 고지의무 등 면책 규정을 적용하지 않습니다.","보험계약자·피보험자가 고지한 후 보험료 불가분 원칙: 보험료는 보험기간 전체에 대한 것으로 나뉘지 않는다. 약관이 위험증가 해지 시 미경과보험료 반환을 정해도 무효가 아니다":"보험료는 보험기간 전체에 대한 값이라 나누어 따지지 않으며 약관이 미경과보험료 반환을 정해도 무효는 아닙니다.","보험계약자·피보험자·보험수익자는 보험사고 발생을 안 때 지체없이 보험자에게 통지를 발송해야 한다. 해태하여 손해가 증가되면 보험자는 증가된 손해를 보상할 책임이 없다":"사고가 났음을 알면 바로 보험자에게 알려야 하고 게을러서 손해가 커졌다면 보험자는 커진 만큼을 보상하지 않습니다.","보험계약자·피보험자·보험수익자의 고의 또는 중대한 과실로 위험이 현저하게 변경·증가된 때 보험자는 그 사실을 안 날부터 1월 내에 보험료 증액을 청구하거나 계약을 해지할 수 있다":"관계자의 고의나 중과실로 위험이 현저히 늘면 보험자는 안 날부터 1월 안에 보험료 증액을 청구하거나 해지할 수 있습니다.","보험계약 체결 후 보험의 목적의 물가 상승으로 보험금액이 보험가액에 미달하게 된 자연적 일부보험은 일부보험으로 다룰 수 없다는 견해가 있다":"계약 후 물가가 올라 보험금액이 보험가액에 못 미치게 된 자연적 일부보험은 일부보험으로 다룰 수 없다는 견해가 있습니다.","보험 관련 정보의 수집·제공 및 통계의 작성은 보험요율 산출기관의 업무다":"보험 정보를 수집하고 제공하며 통계를 만드는 일은 보험요율 산출기관이 맡는 업무입니다.","보험금 부정취득 목적의 다수 보험계약은 민법 제103조 위반으로 무효이며, 보험금 부당이득반환청구권은 상사시효 5년이다":"보험금을 부정하게 타려고 여러 보험을 든 계약은 민법 제103조 위반으로 무효이고 그 반환청구는 상사시효 5년입니다.","보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다. 보험료 감액은 장래에 대해서만 효력이 있다":"보험금액이 목적의 가액을 현저하게 넘으면 보험자와 계약자는 보험료와 보험금액의 감액을 청구할 수 있으며 보험료 감액은 장래에만 효력이 있습니다.","보험금 지급기한: 약정기간이 있으면 그 기간 내, 없으면 제657조 통지를 받은 후 지체없이 보험금액을 정하고 그 정하여진 날부터 10일 내에 지급한다":"보험금은 약정한 기간 안에 주고 없으면 통지를 받은 후 지체 없이 금액을 정해 그 날부터 10일 안에 지급합니다.","보험금청구권 소멸시효: 3년. 보험료 또는 적립금의 반환청구권: 3년. 보험료청구권: 2년(현행). (2023 기출 당시 보험금청구권은 2년)":"보험금청구권과 보험료나 적립금의 반환청구권은 3년이고 보험료청구권은 2년의 소멸시효가 적용됩니다.","보험기간 개시 전 사고로 장해가 있던 피보험자의 동일 부위 새 후유장해는 최종 후유장해보험금에서 기존 장해분을 차감하기로 한 약관이 유효하다":"보험기간 전 사고로 장해가 있던 부위에 새로 후유장해가 생기면 최종 보험금에서 기존 장해분을 빼기로 한 약관은 유효합니다.","보험기간과 보험계약기간은 반드시 일치할 필요가 없다":"보험자가 책임지는 보험기간과 계약이 유지되는 보험계약기간은 서로 다르게 정할 수 있습니다.","보험기간의 개시(항해단위 선박): 하물 또는 저하의 선적에 착수한 때. 적하: 하물의 선적에 착수한 때, 출하지를 정한 경우 그곳에서 운송에 착수한 때":"항해 단위 보험의 기간은 하물이나 저하를 싣기 시작한 때에 시작하고 적하는 선적에 착수한 때 또는 출하지에서 운송을 시작한 때입니다.","보험기간의 종료: 선박은 도착항에서 하물 또는 저하를 양륙한 때, 적하는 양륙항 또는 도착지에서 하물을 인도한 때. 불가항력이 아닌 양륙 지연은 보통 종료될 때에 종료된 것으로 본다":"선박은 도착항 하역 때, 적하는 인도 때 보험기간이 끝나고 불가항력 아닌 하역 지연은 정상 종료로 간주합니다.","보험기간 중 보험계약자 또는 피보험자가 사고발생의 위험이 현저하게 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 통지해야 한다":"보험기간 중 사고 위험이 현저하게 달라지거나 늘어난 사실을 알면 계약자와 피보험자는 바로 보험자에게 알려야 합니다.","보험기간 중 보험자가 파산선고를 받으면 보험계약자는 계약을 해지할 수 있다. 해지하지 않은 계약은 파산선고 후 3월이 지나면 효력을 잃는다":"보험자가 파산하면 계약자는 해지할 수 있고 해지하지 않은 계약도 파산선고 후 3월이 지나면 효력을 잃습니다.","보험대리상의 권한: 보험료 수령, 보험증권 교부, 청약·고지·통지·해지·취소 등 의사표시의 수령, 보험계약 체결·변경·해지 등 의사표시. 보험자는 일부를 제한할 수 있으나 선의의 보험계약자에게 대항하지 못한다":"보험대리상은 보험료를 받고 증권을 주고 각종 의사표시를 받고 계약을 체결하는 권한이 있고 제한해도 선의의 계약자에게 맞서지 못합니다.","보험대리상이 아니면서 특정 보험자를 위해 계속적으로 체결을 중개하는 자는 영수증 교부 방식의 보험료 수령권과 증권 교부권만 있다":"보험대리상이 아닌 중개인은 영수증을 주며 보험료를 받는 권한과 증권을 건네는 권한만 가집니다.","보험대리점 등록취소·업무정지(6개월 이내): 모집 관련 법 위반, 명령·처분 위반, 소속 설계사의 위반 등. 자기계약 금지 위반(제101조)은 필요적 등록취소 사유":"모집 위반이나 명령 위반이 있으면 6개월 이내 업무정지나 취소를 받고 자기계약 금지 위반은 취소가 필수입니다.","보험대리점 또는 보험중개사는 자기 또는 자기를 고용하고 있는 자를 계약자·피보험자로 하는 보험 모집을 주된 목적으로 하지 못한다. 그런 보험의 보험료 누계액이 자기가 모집한 보험료의 100분의 50을 초과하면 주된 목적으로 한 것으로 본다(간주)":"자기나 고용주를 계약자로 하는 보험을 주로 모집하면 안 되고 그 보험료 누계가 100분의 50을 넘으면 주된 목적으로 봅니다.","보험료적립금 반환의무: 임의해지(제649조), 계속보험료 불지급 해지(제650조), 고지의무 위반(제651조), 위험변경증가 해지(제652조·제653조), 보험자 파산 해지(제654조), 사고 후 해지(제655조)로 해지되거나 제659조·제660조로 지급책임이 면제된 때 보험자는 보험수익자를 위해 적립한 금액을 계약자에게 지급한다":"해지되거나 면책되어 지급책임이 없어진 경우 보험자는 쌓아 둔 보험료적립금을 계약자에게 돌려줘야 합니다.","보험료적립금 반환청구권 소멸시효는 3년이다":"보험료적립금의 반환을 청구하는 권리는 3년이 지나면 소멸시효가 완성되어 청구할 수 없습니다.","보험료 지급은 보험계약의 성립요건이 아니고 보험자의 책임개시요건이다":"보험료를 냈는지는 계약이 성립했는지와 무관하고 보험자가 책임을 지기 시작하는 시점을 정하는 조건입니다.","보험료채권 지급 확보를 위해 받은 수표에 관한 소송상 청구는 보험료채권의 소멸시효 중단 효력이 있다":"보험료 지급을 위해 받은 수표에 대해 소송으로 청구하면 보험료채권의 소멸시효가 중단됩니다.","보험목적에 관한 보험대위(잔존물대위): 보험의 목적의 전부가 멸실한 경우 보험금액의 전부를 지급한 보험자는 그 목적에 대한 피보험자의 권리를 취득한다. 일부보험이면 보험금액의 보험가액에 대한 비율로 취득한다":"목적 전부가 없어져 보험금액 전부를 지급한 보험자는 그 목적에 대한 피보험자의 권리를 얻고 일부보험이면 비율만큼만 얻습니다.","보험사고가 송하인 또는 수하인의 고의 또는 중대한 과실로 발생한 때 보험자는 이로 인해 생긴 손해를 보상할 책임이 없다":"사고가 송하인이나 수하인의 고의나 중과실로 났다면 운송보험자는 그로 인한 손해를 보상하지 않습니다.","보험사고로 인하여 생길 피보험자의 재산상의 손해를 보상한다":"손해보험자는 보험사고 때문에 피보험자가 입는 재산상의 손해를 보상하는 책임을 집니다.","보험사고 발생 이전의 손해 발생 방지 비용은 손해방지비용에 포함되지 않는다. 보험사고가 발생한 것과 같게 볼 수 있는 경우 피보험자의 법률상 책임 여부가 판명되지 않았어도 긴급 행위의 필요·유익 비용은 보험자가 부담한다":"사고 전의 예방 비용은 손해방지비용이 아니고 사고와 같게 볼 때의 긴급 비용만 보험자가 부담합니다.","보험사고 발생 후에도 고지의무 위반을 이유로 해지할 수 있고, 이 경우 보험금 지급책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다":"사고가 난 뒤에도 고지의무 위반을 이유로 해지할 수 있고 그러면 보험금 지급책임이 없어 이미 낸 보험금도 돌려받을 수 있습니다.","보험사고와 손해 사이에 상당인과관계가 있으면 보상한다. 진화용 물, 철거비·폐기물 처리비는 화재와 상당인과관계가 있다":"화재와 상당인과관계가 있는 소화용 물, 철거비, 폐기물 처리비 손해도 보험으로 보상합니다.","보험사고의 객관적 확정: 계약 당시 보험사고가 이미 발생했거나 발생할 수 없는 것이면 계약은 무효다. 당사자 쌍방과 피보험자가 이를 알지 못한 때는 유효하다":"계약 때 사고가 이미 났거나 날 수 없는 것이었다면 무효이지만 양 당사자와 피보험자가 몰랐다면 유효합니다.","보험사기행위 금지: 계약자, 피보험자, 보험금을 취득할 자 등은 보험사기행위를 해서는 안 되며, 보험 관계 업무 종사자는 고의 사고 조작·사고 내용 과장 유도를 해서는 안 된다":"계약자와 피보험자, 수취인은 보험사기를 해선 안 되고 업무 종사자도 사고를 꾸미거나 과장하도록 유도하면 안 됩니다.","보험상품 비교·공시: 보험협회가 하며 보험상품공시위원회를 구성한다. 위원은 위원장 1명 포함 9명이고, 당연직은 금융감독원 상품담당 부서장, 보험협회 상품담당 임원, 보험요율 산출기관 상품담당 임원 3명. 협회장 위촉: 보험회사 상품담당 임원 또는 선임계리사 2명, 법률 자격자 1명, 소비자단체 추천 2명, 학식경험자 1명. 임기 2년":"보험협회가 상품 비교공시를 맡고 위원 9명의 공시위원회를 두며 당연직 3명 외에는 협회장이 위촉하고 임기는 2년입니다.","보험상품의 취급과 관련하여 발생하는 보험의 인수, 보험료 수수 및 보험금 지급 등을 영업으로 하는 것. 생명보험업·손해보험업·제3보험업으로 나뉜다":"보험업은 보험의 인수와 보험료 수수와 보험금 지급 등을 영업으로 하는 것이며 생명보험업과 손해보험업과 제3보험업으로 나뉩니다.","보험설계사, 보험대리점, 보험중개사, 보험회사의 임원 또는 직원. 보험회사의 대표이사·사외이사·감사·감사위원은 제외한다":"모집할 수 있는 자는 설계사와 대리점과 중개사와 보험회사의 임직원이며 대표이사와 사외이사와 감사와 감사위원은 제외됩니다.","보험설계사가 위험변경증가 사실을 알았더라도 보험자가 안 것으로 볼 수 없다":"보험설계사는 보험자를 대신해 통지를 받을 권한이 없어서 그가 위험 증가를 알았어도 보험자가 안 것으로 보지 않습니다.","보험설계사 교육: 최초 유효한 등록일부터 2년마다 2년이 된 날부터 6개월 이내에 교육한다. 법인이 아닌 보험대리점·보험중개사는 등록한 날부터 2년마다 같은 방식으로 교육을 받는다":"설계사는 최초 등록일부터 2년마다 그 2년이 된 날부터 6개월 이내에 교육을 받고 법인이 아닌 대리점과 중개사도 같은 방식으로 받습니다.","보험설계사에 대한 불공정 행위 금지: 위탁계약서 미교부, 계약사항 불이행, 해지요건 외 사유 해지, 정당한 사유 없는 해지 요청 거부, 위탁업무 외 업무 강요, 수수료 미지급·지연, 수수료 환수, 보험료 대납 강요 등":"보험회사는 설계사에게 위탁계약서를 주지 않거나 부당하게 해지하거나 수수료를 지연하거나 보험료 대납을 강요하는 불공정 행위를 해서는 안 됩니다.","보험설계사의 주의의무 해태·불법행위로 보험금을 지급받지 못한 경우 보험자는 보험계약자에게 보험금 상당의 손해를 배상한다":"보험설계사가 주의의무를 소홀히 하거나 불법행위를 해서 보험금을 못 받았다면 보험자가 계약자에게 보험금 상당의 손해를 배상합니다.","보험수익자가 보험 존속 중에 사망하면 계약자는 다시 수익자를 지정할 수 있다. 이 경우 계약자가 지정권을 행사하지 않고 사망하면 보험수익자의 상속인이 수익자다":"수익자가 보험이 유지되는 중에 숨지면 계약자가 다시 지정할 수 있고 지정하지 않은 채 숨지면 그 수익자의 상속인이 수익자가 됩니다.","보험수익자는 지정 시점에 특정될 필요 없이 사고 발생 당시 특정될 수 있으면 족하다. 특정인뿐 아니라 불특정인도 지정할 수 있다":"수익자는 지정할 때 이미 정해져 있을 필요가 없고 사고가 났을 때 특정될 수 있으면 되며 불특정인도 지정할 수 있습니다.","보험수익자를 지정 또는 변경하려면 그 타인(피보험자)의 서면동의를 얻어야 한다":"타인의 생명보험에서 보험수익자를 지정하거나 바꾸려면 피보험자인 타인의 서면동의를 받아야 합니다.","보험업을 경영하려는 자는 보험종목별로 금융위원회의 허가를 받아야 한다. 허가를 받을 수 있는 자는 주식회사, 상호회사, 외국보험회사로 제한한다":"보험업은 종목별로 금융위원회 허가가 있어야 하고 허가 대상은 주식회사, 상호회사, 외국보험회사로 한정됩니다.","보험업을 경영할 목적으로 이 법에 따라 설립된 회사로서 보험계약자를 사원으로 하는 회사":"상호회사는 보험업을 하려고 보험업법에 따라 세운 회사로 보험계약자가 곧 사원이 되는 회사입니다.","보험영업의 양도·양수는 허가가 아니라 인가 사항이다":"보험영업을 넘기거나 넘겨받는 것은 금융위원회의 허가가 아니라 인가를 받아야 하는 사항입니다.","보험요율 산출기관: 순보험요율의 공정·합리적 산출과 보험 정보의 관리를 위해 금융위원회의 인가를 받아 설립한다. 업무: 순보험요율 산출·검증·제공, 보험 정보 수집·제공·통계 작성, 조사·연구 등. 순보험요율을 산출해 금융위원회에 신고할 수 있고, 정관에 따라 보험회사로부터 수수료를 받는다. 민법 중 사단법인 규정 준용":"요율산출기관은 인가를 받아 순보험요율 산출과 검증, 보험정보와 통계 관리, 조사와 연구를 하며 회사로부터 수수료를 받습니다.","보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 않는다":"보험자 한 사람에 대한 권리를 포기하더라도 다른 보험자의 권리와 의무는 그대로입니다.","보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때에는 해지할 수 없다":"보험자가 계약할 때 이미 알았거나 중대한 과실로 몰랐다면 그 사실을 이유로 해지할 수 없습니다.","보험자가 부담할 손해가 생긴 후 보험자가 부담하지 않는 사고로 목적이 멸실되어도 이미 생긴 손해의 보상책임을 면하지 못한다":"보험자가 보상해야 할 손해가 먼저 생긴 뒤 다른 사고로 목적이 없어져도 이미 생긴 손해는 보상해야 합니다.","보험자가 약관 내용과 다른 설명을 한 경우 그 설명이 개별약정이면 개별약정 우선의 원칙에 따라 계약내용이 된다":"보험자가 약관과 다르게 설명했고 그것이 개별약정이면 약관보다 개별약정이 우선해 계약 내용이 됩니다.","보험자가 제3자와 손해배상금액에 대해 합의를 시도하면 그때마다 채무를 승인한 것이므로 직접청구권의 소멸시효가 중단된다":"보험자가 피해자와 배상액을 합의하려 할 때마다 채무를 승인한 것이 되어 직접청구권의 소멸시효가 중단됩니다.","보험자가 피보험자의 피해자에 대한 손해배상채무를 병존적으로 인수한 것으로서 피해자가 보험자에 대해 가지는 손해배상청구권. 지연손해금에는 상사법정이율이 아니라 민사법정이율이 적용되고, 보험자와 피보험자의 채무는 연대채무 관계다":"직접청구권은 보험자가 피보험자의 배상채무를 함께 떠안은 것이라 지연손해금에 민사법정이율이 적용되고 둘의 채무는 연대채무입니다.","보험자는 계약이 성립하면 지체없이 보험증권을 작성하여 보험계약자에게 교부해야 한다":"보험자는 계약이 성립하는 대로 바로 보험증권을 만들어 보험계약자에게 줘야 합니다.","보험자는 단체보험계약자에게만 보험증권을 교부하면 된다":"단체보험에서는 구성원이 아니라 단체인 보험계약자에게만 보험증권을 주면 충분합니다.","보험자는 보험계약을 체결할 때 보험계약자에게 보험약관을 교부하고 그 약관의 중요한 내용을 설명해야 한다. 시기는 계약 체결 때다":"보험자는 계약을 맺을 때 약관을 주고 중요한 내용을 설명해야 하며 그 시점은 계약 체결 때입니다.","보험자는 손해를 보상할 때 보험료를 받지 못한 잔액이 있으면 지급기일 도래 전이라도 보상액에서 공제할 수 있다":"보험자는 손해를 보상할 때 받지 못한 보험료 잔액이 있다면 지급기일 전이라도 보상액에서 그만큼 뺄 수 있습니다.","보험자는 양수사실 통지를 받으면 지체없이 낙부를 통지하고, 통지받은 날부터 10일 내에 낙부의 통지가 없으면 승낙한 것으로 본다":"보험자는 양수 통지를 받으면 바로 승낙 여부를 알려야 하고 10일 안에 알리지 않으면 승낙한 것으로 봅니다.","보험자는 제3자가 배상을 받기 전에는 보험금액의 전부 또는 일부를 피보험자에게 지급하지 못한다":"보험자는 피해자가 배상을 받기 전에는 보험금의 전부나 일부를 피보험자에게 먼저 줄 수 없습니다.","보험자는 제3자의 직접청구를 받으면 지체없이 피보험자에게 통지해야 하고, 피보험자는 보험자의 요구가 있으면 필요한 서류·증거 제출, 증언 또는 증인 출석에 협조해야 한다":"보험자는 피해자의 직접청구를 받으면 바로 피보험자에게 알려야 하고 피보험자는 요구가 있으면 서류와 증거 제출과 증언에 협조해야 합니다.","보험자 면책 약관의 효력을 보험금청구권 양수인·질권자에게도 주장할 수 있다. 이의를 보류하지 않았어도 같다":"면책 약관은 보험금청구권을 넘겨받은 양수인이나 질권자에게도 주장할 수 있고 이의를 보류하지 않았어도 같습니다.","보험자의 지시에 의한 행위이면 손해액에 가산한 금액이 보험금액을 초과해도 보험자가 부담한다":"보험자가 지시해서 한 방어 행위의 비용은 손해액에 더한 금액이 보험금액을 넘더라도 보험자가 부담합니다.","보험자의 책임개시: 당사자 간에 다른 약정이 없으면 최초의 보험료를 지급받은 때부터 개시한다":"보험자의 책임은 다른 약정이 없다면 처음 보험료를 받은 때부터 시작됩니다.","보험중개사에게는 통지 수령 권한이 없다":"보험중개사는 계약자와 보험자를 이어 주는 사람이라서 통지를 대신 받을 권한이 없습니다.","보험중개사의 의무: 중개 관련 내용을 장부에 적고 보험계약자에게 알리며, 수수료에 관한 사항을 비치하여 열람하게 한다. 보험회사 임직원이 될 수 없고, 보험회사·설계사·대리점·보험계리사·손해사정사 업무를 겸할 수 없다":"중개사는 중개 내용을 장부에 남겨 알리고 수수료를 열람시켜야 하며 회사 임직원이나 설계사 등을 겸할 수 없습니다.","보험증권·청약서 작성이 성립요건이 아니다":"보험증권이나 청약서는 계약이 성립한 뒤에 쓰는 문서일 뿐 계약 성립에 필요한 조건이 아닙니다.","보험협회·요율산출기관·보험 관계 단체에는 제131조제1항, 제133조~제135조를 준용하고 민법 중 사단법인 규정을 준용한다":"보험협회와 요율산출기관과 보험 관계 단체에는 금융위원회의 명령과 검사와 제재 규정을 준용하고 민법의 사단법인 규정도 준용합니다.","보험회사, 금융지주회사, 농협·산림조합·수협·신협 중앙회, 상호저축은행 및 그 중앙회, 새마을금고연합회, 여신전문금융회사, 은행, 금융투자업자(겸영 제외), 증권금융회사, 종합금융회사, 자금중개회사, 중소기업은행, 산업은행, 수출입은행, 이에 준하는 외국금융기관":"전문보험계약자가 되는 금융기관에는 보험회사와 은행과 금융투자업자와 각종 중앙회와 정책금융기관 등이 들어갑니다.","보험회사가 다른 회사(민법·특별법에 따른 조합 포함)의 의결권 있는 발행주식 총수의 100분의 15를 초과하여 소유하는 경우의 그 다른 회사(2026 기출 보기의 100분의 10은 틀림)":"자회사는 보험회사가 다른 회사의 의결권 있는 발행주식 총수의 100분의 15를 넘게 가진 경우 그 다른 회사를 말합니다.","보험회사가 상호 간의 업무질서 유지와 보험업 발전을 위해 설립할 수 있는 법인. 업무: 건전한 업무질서 유지, 보험설계사에 대한 불공정 위탁행위 방지를 위한 규약 제정·개정, 보험회사 간 분쟁(교통사고 과실비율 분쟁)의 자율조정, 보험상품 비교·공시, 정부 위탁 업무":"보험협회는 보험회사들이 업무질서와 업계 발전을 위해 세운 법인이며 불공정 위탁 방지 규약, 과실비율 조정, 상품 공시를 맡습니다.","보험회사는 보험계리 업무(기초서류의 내용 및 배당금 계산 등의 정당성 확인)를 보험계리사를 고용해 담당하게 하거나 보험계리업자에게 위탁해야 한다. 보험계리 업무 전반을 총괄하는 선임계리사를 선임해야 한다":"회사는 기초서류와 배당금 계산이 타당한지 따지는 계리 업무를 계리사 고용이나 위탁으로 하고 총괄하는 선임계리사를 둡니다.","보험회사는 생명보험업과 손해보험업을 겸영하지 못한다. 예외: 생명보험의 재보험 및 제3보험의 재보험, 다른 법령에 따라 겸영 가능한 종목, 제3보험의 보험종목에 부가되는 보험":"보험회사는 생명보험업과 손해보험업을 함께 하지 못하며 재보험과 다른 법령상 허용 종목과 제3보험에 부가되는 보험만 예외입니다.","보험회사는 청약 내용 확인·정정, 청약 철회, 체결 계약 내용 확인, 계약 해지(본인 확인을 받은 경우에 한함)에 통신수단을 이용할 수 있게 해야 한다":"보험회사는 청약 내용의 확인과 정정과 청약 철회와 계약 내용 확인과 본인 확인을 거친 계약 해지에 통신수단을 쓸 수 있게 해야 합니다.","보험회사를 위하여 보험계약 체결을 대리하는 자로 제87조에 따라 등록된 자":"보험대리점은 보험회사를 대신해 보험계약 체결을 대리하는 사람으로 법에 따라 등록한 자입니다.","보험회사·보험대리점·보험중개사가 소속 설계사가 되려는 자를 금융위원회에 등록한다. 구분: 생명보험설계사, 손해보험설계사(간단손해보험설계사 포함), 제3보험설계사. 등록업무는 보험협회에 위탁":"설계사는 회사나 대리점, 중개사가 금융위원회에 등록하고 생명, 손해, 제3보험으로 나뉘며 접수는 협회가 대행합니다.","보험회사·보험대리점·보험중개사에 소속되어 보험계약 체결을 중개하는 자로 제84조에 따라 등록된 자":"보험설계사는 보험회사와 대리점과 중개사에 소속되어 계약 체결을 중개하는 사람으로 법에 따라 등록된 사람입니다.","보험회사에 하지 못하는 행위: 해당 금융기관을 계약자로 하는 보험계약의 할인·신용공여·보험료 예탁 요구, 비용·손실을 보험회사에 부당하게 떠넘기기, 모집수수료 외에 모집한 계약에서 발생한 이익의 배분 요구(고시 기준에 따른 요구 제외)":"금융기관은 자기를 계약자로 하는 보험의 할인과 신용공여를 요구하거나 비용 전가, 수수료 외 이익 배분을 요구하지 못합니다.","보험회사의 설명의무: 보험계약 체결 시부터 보험금 지급 시까지의 주요 과정을 일반보험계약자에게 설명. 보험금을 감액하여 지급하거나 지급하지 않는 경우 그 사유 설명. 체결 단계에서 상법 제638조의3제2항에 따라 3개월 이내 취소할 수 있다는 사실과 절차도 설명":"회사는 체결부터 지급까지의 주요 과정과 감액 또는 부지급 사유, 3개월 이내 취소 가능 사실까지 일반계약자에게 설명합니다.","보험회사의 파산 등으로 계약자 이익을 크게 해칠 우려가 있는 경우의 조치(2023 기출): 보험금 전부·일부의 지급정지, 보험계약 체결의 제한 등. 보험계약 전부의 이전은 이 조치 목록의 항목이 아니다(정답 1)":"보험회사의 파산 등으로 계약자 이익을 크게 해칠 우려가 있으면 보험금 전부나 일부의 지급정지와 보험계약 체결 제한 등을 명할 수 있습니다.","복수 원인 경합 시 보험자가 면책되려면 고의행위가 유일하거나 결정적인 원인임을 증명해야 한다. 면책사유 해당 사실의 증명책임은 보험자에게 있다":"원인이 여러 개일 때 보험자가 면책되려면 고의 행위가 유일하거나 결정적 원인임을 증명해야 하며 증명책임은 보험자에게 있습니다.","복수 원인 중 하나가 피보험자 등의 고의행위여서 면책되려면 보험자가 그 행위가 유일하거나 결정적인 원인임을 증명해야 한다":"고의 행위가 여러 원인 중 하나일 뿐이면 보험자가 그 행위가 유일하거나 결정적인 원인임을 입증해야 면책됩니다.","복수의 퇴직연금사업자와 운용관리업무 계약을 체결한 사용자는 그 중 하나를 간사기관으로 선정한다":"사용자가 여러 연금사업자와 운용관리 계약을 맺었다면 그중 한 곳을 간사기관으로 정해야 합니다.","본점에 제1항 사유(소멸, 외국감독기관 조치, 휴업·영업중지)가 생기면 국내지점은 그 사유가 발생한 날부터 7일 이내에 금융위원회에 알려야 한다":"본점에 소멸이나 외국감독기관 조치나 휴업 같은 사유가 생기면 국내지점은 발생한 날부터 7일 안에 금융위원회에 알려야 합니다.","본허가를 신청하려는 자는 미리 예비허가를 신청할 수 있다. 금융위원회는 2개월 이내에 심사하여 통지하며 총리령으로 기간을 연장할 수 있고, 조건을 붙일 수 있다. 예비허가 조건을 이행한 후 본허가를 신청하면 허가해야 한다":"예비허가는 2개월 안에 심사하고 조건을 붙일 수 있으며 그 조건을 지킨 뒤 본허가를 신청하면 허가해야 합니다.","부담금은 자기 부담으로 납입하며 대통령령 한도(이전 사업 퇴직급여 일시금 등을 제외한 금액으로 소득세법 시행령 제40조의2제2항제1호 금액)를 초과해 납입할 수 없다. 운용방법·정보 제공은 DC 규정(제21조, 제21조의2~제21조의4)을 준용":"IRP 부담금은 본인 돈으로 내며 시행령이 정한 한도를 넘길 수 없고 운용 정보는 DC 규정을 그대로 따릅니다.","부담금의 부담, 부담금의 산정 및 납입, 적립금의 운용, 적립금의 운용방법 및 정보 제공, 사전지정운용제도, 적립금의 중도인출, 퇴직연금사업자 선정·가입자·가입기간·급여 종류 및 수급요건 등·계약 체결·해지·이전·운용현황 통지·급여 지급절차·폐지 사유, 그 밖의 대통령령(수수료 부담, 가입자 교육 방법·절차)":"DC 규약에는 부담금과 운용방법, 사전지정운용, 중도인출, 사업자 선정과 가입기간, 수수료와 교육 방법 같은 사항이 들어갑니다.","부당 소멸된 기존계약의 부활: 계약자는 계약 소멸일부터 6개월 이내에 소속 보험회사에 부활을 청구하고 새 계약을 취소할 수 있다. 보험회사는 특별한 사유가 없으면 승낙해야 하며, 청구받은 날부터 30일 이내에 통지하지 않으면 승낙한 것으로 본다":"부당 소멸된 계약은 6개월 안에 부활을 청구할 수 있고 회사가 30일 안에 통지하지 않으면 승낙한 것으로 봅니다.","부동산 소유 자산운용비율은 시행령으로 총자산의 100분의 15로 인하되어 있다":"부동산 소유의 자산운용비율은 시행령에서 총자산의 100분의 15로 내려 정해져 있습니다.","부부싸움 중 극도의 공황 상태에서 몸을 던져 사망한 경우 '고의로 자신을 해친 경우'에 해당하지 않는다. 면책사유 해당 사실의 증명책임은 보험자가 진다":"극도의 공황 상태에서 몸을 던져 숨졌다면 고의 자해가 아니며 면책 증명의 책임은 보험자에게 있습니다.","부수업무: 보험업에 부수하는 업무를 하려면 하려는 날의 7일 전까지 신고한다. 다른 보험회사가 공고된 같은 부수업무는 신고 없이 가능":"보험업에 부수하는 업무는 시작 7일 전까지 신고해야 하며 다른 회사가 이미 신고해 공고된 같은 부수업무는 신고 없이 할 수 있습니다.","부수업무 제한·시정명령 사유: (1) 보험회사의 경영건전성을 해치는 경우 (2) 보험계약자 보호에 지장을 가져오는 경우 (3) 금융시장의 안정성을 해치는 경우 — 세 가지 모두":"경영건전성, 계약자 보호, 금융시장 안정 가운데 하나라도 해치면 부수업무를 제한하거나 시정하게 할 수 있습니다.","부활: 계속보험료 미지급으로 해지되고 해지환급금이 지급되지 않은 경우, 보험계약자는 일정한 기간 내에 연체보험료에 약정이자를 붙여 지급하고 계약의 부활을 청구할 수 있다":"계속보험료 미납으로 해지됐고 환급금을 받지 않았다면 일정 기간 안에 연체보험료와 이자를 내고 계약의 부활을 청구할 수 있습니다.","부활청구에는 제638조의2(낙부통지·승낙 전 보험보호)가 준용된다":"부활을 청구하는 경우에도 낙부통지와 승낙 전 보험보호 규정이 같은 방식으로 적용됩니다.","분손의 경우 다른 약정이 없으면 손해액에 부보비율(보험금액/보험가액)을 곱한 금액을 지급한다. 비율보험에는 일부보험 규정이 준용되지 않는다":"일부 손해에는 다른 약정이 없으면 손해액에 보험금액을 보험가액으로 나눈 부보비율을 곱해 지급하고 비율보험에는 일부보험 규정을 준용하지 않습니다.","불이익변경금지에 위반한 보험계약은 불이익하게 변경된 약관 조항에 한해서 무효가 된다":"불이익변경금지를 어긴 계약도 계약 전체가 아니라 불리하게 바뀐 약관 조항만 무효가 됩니다.","불이익변경금지 원칙은 사적자치 원칙의 예외다":"계약 내용을 자유롭게 정하는 사적자치의 원칙을 보험 약자 보호를 위해 제한하는 것이 불이익변경금지 원칙입니다.","비보험회사와 보험계약 체결·중개·대리 금지: 누구든지 보험회사가 아닌 자와 보험계약을 체결하거나 중개 또는 대리하지 못한다. 예외로 외국보험회사와의 생명보험·수출입적하보험·항공보험·여행보험·선박보험·장기상해보험·재보험 계약 등":"누구도 보험회사가 아닌 자와 보험계약을 맺거나 중개하거나 대리할 수 없으며 외국보험회사와의 일부 보험계약만 예외로 허용됩니다.","사고가 계약자·피보험자·수익자의 중대한 과실로 발생해도 보험자는 보험금 지급책임을 면하지 못한다":"사망보험에서는 사고가 계약자나 피보험자나 수익자의 중대한 과실로 났더라도 보험자는 보험금 지급책임을 면하지 못합니다.","사고발생 후 임의해지: 보험금액을 지급한 후에도 보험금액이 감액되지 아니하는 보험은 사고 후에도 해지할 수 있다":"보험금을 지급한 뒤에도 보험금액이 줄지 않는 보험은 사고가 난 뒤에도 계약자가 해지할 수 있습니다.","사기적 보험금 청구: 가액을 다소 높게 신고한 정도로는 면책되지 않는다. 보험목적이 수개이고 청구권자가 동일인이면 하나에 대한 사기가 다른 목적에는 미치지 않는다":"가액을 조금 높게 신고한 정도로는 면책되지 않고 보험목적이 여러 개이면 하나에 대한 사기가 다른 목적까지 미치지 않습니다.","사기 중복보험의 보험료: 중복보험에서 계약자가 C를 기망하면 C와의 계약만 무효이고 C는 안 때까지의 보험료를 청구할 수 있다(반환할 필요 없음)":"계약자가 C를 속여 맺은 중복보험은 C와의 계약만 무효이고 C는 안 때까지의 보험료를 청구할 수 있어 돌려줄 필요가 없습니다.","사기 초과보험: 계약이 보험계약자의 사기로 체결된 때 무효다. 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다":"사기로 맺은 초과보험은 무효이며 보험자는 그 사실을 알 때까지의 보험료를 계약자에게 청구할 수 있습니다.","사람의 생존 또는 사망에 관하여 약정한 금전 및 그 밖의 급여를 지급할 것을 약속하고 대가를 수수하는 계약":"생명보험상품은 사람의 생존이나 사망에 관해 정한 금전 등을 지급하기로 약속하고 대가를 받는 계약입니다.","사람의 질병·상해 또는 이에 따른 간병에 관하여 급여를 지급하기로 하는 계약":"세 번째 보험 분야는 질병이나 상해, 간병을 이유로 급여를 지급하기로 약속하는 보험계약입니다.","사례 계산: 보험가액 20억, 보험금액 A 16억·B 14억·C 10억. B가 20억을 지급하면 A·C에게 부담 부분으로 각 8억·5억 구상하고, 부담 비율은 16:14:10이다. B가 무자력이면 A와 C는 각자 보험금액(16억, 10억) 한도에서 연대책임을 진다":"B가 20억을 내면 A에게 8억, C에게 5억을 구상하고 B가 무자력이면 A와 C가 한도까지 연대합니다.","사망보험계약에서 면책사유인 자살은 자기의 생명을 끊는다는 것을 의식하고 의도적으로 절단하여 사망의 결과를 발생시킨 행위다. 책임개시일 2년 후 자살에 보상한다는 약관은 유효하다":"자살 면책은 스스로 목숨을 끊는다는 의식과 의도가 있어야 하며 책임개시 2년 뒤 자살을 보상하는 약관도 유효합니다.","사망보험의 중과실 면책 제한 조항(제732조의2)은 상해보험·질병보험에도 준용된다. 중과실로 인한 보험사고에 보험자가 면책되도록 한 약정은 제663조 불이익변경금지 위반으로 무효다":"사망보험의 중과실 면책 제한은 상해보험과 질병보험에도 준용되어 중과실 사고에 면책되게 한 약정은 불이익변경금지 위반으로 무효입니다.","사업자의 의무: 선량한 관리자의 주의, 취급실적 제출, 약관·표준계약서 제정·변경 시 금융감독원장에 보고, 매년 말 적립금 운용 수익률 및 수수료 공시, 운용현황 연 1회 이상 통지, IRP 운영 사업자의 연 1회 이상 가입자 교육":"사업자는 선량한 관리자의 주의로 일하며 실적 제출, 약관 보고, 연말 수익률과 수수료 공시, 연 1회 이상 통지와 가입자 교육을 해야 합니다.","사용자가 부담금을 연간 임금총액의 12분의 1에 미달하게 납입한 경우, 가입자는 퇴직일부터 14일이 지난 후 사용자에게 직접 차액과 법정 지연이자를 청구할 수 있을 뿐, 퇴직금제도에 따라 평균임금을 재산정해 추가 퇴직금을 청구할 수는 없다":"부담금을 모자라게 냈다면 가입자는 퇴직 14일 후 차액과 지연이자만 청구할 수 있고 평균임금으로 퇴직금을 다시 계산해 달라고는 못 합니다.","사용자가 부정 행위로 금지되는 것: 약관 등에서 정해진 부가서비스 외에 경제적 가치 있는 서비스를 요구하거나 제공받는 행위, 계약 체결을 이유로 물품 구매를 요구하는 행위, 확정되지 않은 운용방법의 수익을 확정적으로 제시하도록 요구하는 행위 등":"사용자는 약관 밖의 경제적 이익 요구, 계약을 이유로 한 물품 구매 요구, 불확실한 수익을 확정처럼 제시시키는 행위를 하면 안 됩니다.","사용자는 사업 또는 사업장 단위로 사전지정운용방법을 설정해 근로자대표의 동의를 받아 DC 규약에 반영한다(협의가 아니라 동의)":"사용자는 사업장 단위로 사전지정운용방법을 정하고 근로자대표의 동의를 받아 DC 규약에 넣으며 단순 협의로는 부족합니다.","사용자부담금: 매년 1회 이상 정기적으로 가입자의 연간 임금총액의 12분의 1 이상을 현금으로 납입. 기일을 어기면 지연이자. 퇴직 등 사유 발생 시 14일 이내에 미납 부담금과 지연이자를 납입":"사용자는 해마다 한 번 이상 연간 임금총액의 12분의 1 이상을 현금으로 내고 늦으면 지연이자를 내며 퇴직 땐 14일 안에 미납분을 냅니다.","사이버몰 모집: 약관 주요 내용을 표시하고 청약 내용에 대해 전자서명 등 자필서명에 갈음하는 확인을 받는다. 약관·증권을 전자문서로 발급한 경우 수령 여부를 확인하고, 서면 발급 요청 시 서면으로 발급한다":"사이버몰 모집은 약관 요지를 보여 주고 전자서명 등으로 확인받으며 전자문서 수령 여부를 확인하고 요청 시 서면을 줍니다.","사전지정운용방법 승인 요건: 투자설명서상 운용내용 명시, 자산배분 적절·전략 단순, 손실가능성 허용 범위, 합리적 예상수익, 손실가능성과 수익의 균형, 수수료 과다 아님, 상시 가입 가능·환매 신청 후 14일 이내 환매 가능":"승인 요건은 투자설명서 명시, 단순한 자산배분, 합리적 수익과 손실 균형, 과하지 않은 수수료, 환매 신청 후 14일 안 환매 등입니다.","사전지정운용제도: 가입자가 적립금의 운용방법을 스스로 선정하지 않은 경우 사전에 지정한 운용방법으로 운용하는 제도":"사전지정운용제도는 가입자가 운용 방법을 고르지 않을 때 미리 정해 둔 방법으로 자동 운용해 주는 제도입니다.","산업재해보상보험과 자동차종합보험(대인배상)은 보험의 목적과 보험사고가 동일하지 않아 중복보험이 아니다":"산재보험과 자동차종합보험은 보험의 목적과 사고가 서로 같지 않아서 중복보험이 아닙니다.","상법 보험편의 규정은 당사자 간 특약으로 보험계약자·피보험자·보험수익자에게 불이익하게 변경하지 못한다. 재보험·해상보험·그 밖에 유사한 보험은 예외다":"상법 보험편은 특약으로도 계약자 쪽에 불리하게 바꿀 수 없지만 재보험과 해상보험 같은 기업보험은 예외입니다.","상법상 보험자의 해지사유: 계속보험료 지급 지체(최고 후 해지), 고지의무 위반, 위험변경증가 통지의무 해태, 고의·중과실로 인한 위험증가, 선박미확정 적하예정보험의 통지의무 해태. 사기로 체결된 초과보험은 해지가 아니라 무효다":"보험료 지체와 고지의무 위반과 위험 증가와 통지 해태 등이 해지 사유이고 사기로 맺은 초과보험은 해지가 아니라 무효입니다.","상법에 규정된 통지의무와 동일한 내용의 약관, 보험계약자가 이미 알고 있는 내용 등은 설명의무가 면제되며, 면제 사유의 증명책임은 보험자가 진다":"법에 이미 있는 내용이나 계약자가 아는 내용은 설명이 면제되며 면제 사유는 보험자가 증명해야 합니다.","상법 제731조제1항 위반으로 무효인 보험계약의 보험료 반환청구권은 보험료를 납부한 때 발생하여 행사할 수 있고 시효도 그때부터 진행한다":"서면동의 위반으로 무효가 된 보험의 보험료 반환청구권은 보험료를 낸 때 생겨 행사할 수 있고 시효도 그때부터 갑니다.","상시 10명 미만 근로자를 사용하는 사업에서 사용자가 개별 근로자의 동의를 받거나 근로자의 요구에 따라 IRP를 설정하면 그 근로자에 대해 퇴직급여제도를 설정한 것으로 본다(근로자대표와 협의가 아님)":"상시 10명 미만 사업장은 개별 근로자의 동의나 요구로 IRP를 만들면 제도를 설정한 것으로 보며 근로자대표와의 협의는 아닙니다.","상시 300명 이상의 근로자를 사용하는 사업의 사용자는 퇴직연금제도 적립금의 합리적 운용을 위해 구성해야 한다":"상시 300명 이상 근로자를 둔 사업의 사용자는 적립금을 합리적으로 굴리기 위한 위원회를 꾸려야 합니다.","상실이익·보수는 당사자 간에 다른 약정이 없으면 보상할 손해액에 산입하지 않는다":"사고로 얻지 못한 이익과 보수는 당사자 사이에 다른 약정이 없으면 보상할 손해액에 넣지 않습니다.","상해보험에는 제732조(15세 미만 등 무효)를 제외하고 생명보험 규정을 준용한다":"상해보험에는 15세 미만자 등의 사망보험을 무효로 하는 규정을 뺀 나머지 생명보험 규정을 가져와 적용합니다.","상해보험 예외: 당사자 간에 다른 약정이 있으면 피보험자의 권리를 해하지 않는 범위에서 보험자가 그 권리를 대위하여 행사할 수 있다. 별도 약정이 없으면 제3자로부터 손해배상을 받아도 보험금 지급의무가 있고 대위도 못한다":"상해보험은 특약이 있을 때만 대위가 가능하고 특약이 없으면 배상을 받았어도 보험금을 줘야 하며 대위도 안 됩니다.","상해보험은 중과실로 보험사고가 발생해도 보험금 지급의무가 있다":"상해보험은 사고가 피보험자의 중과실로 났더라도 보험자가 보험금을 지급할 의무가 있습니다.","상해보험증권: 피보험자와 보험계약자가 동일인이 아닐 때 제728조제2호(피보험자의 주소·성명·생년월일)에 갈음하여 피보험자의 직무 또는 직위만 기재할 수 있다":"피보험자와 계약자가 다른 상해보험증권에는 피보험자의 주소와 성명과 생년월일 대신 피보험자의 직무나 직위만 적을 수 있습니다.","상호 또는 명칭: 보험회사는 상호 중에 주로 경영하는 보험업의 종류를 표시해야 하고, 보험회사가 아닌 자는 보험회사임을 표시하는 글자를 포함할 수 없다":"보험회사는 상호에 주로 하는 보험업의 종류를 밝혀야 하고 보험회사가 아닌 자는 상호에 보험회사임을 나타내는 글자를 넣을 수 없습니다.","상호보험·공제·그 밖에 이에 준하는 계약에는 성질에 반하지 않는 범위에서 보험편을 준용한다":"상호보험과 공제와 비슷한 계약에는 성질에 어긋나지 않는 범위에서 상법 보험편을 준용합니다.","상호협정: 업무에 관한 공동행위를 위해 다른 보험회사와 체결·변경·폐지하려면 금융위원회의 인가를 받는다(경미한 변경은 신고). 금융위원회는 특히 필요하면 체결·변경·폐지를 명하거나 전부 또는 일부에 따를 것을 명할 수 있다. 인가나 명령을 하려면 미리 공정거래위원회와 협의해야 한다(경미한 사항은 제외)":"보험회사들이 공동행위를 하려고 맺는 상호협정은 금융위원회 인가를 받아야 하며 인가나 명령 전에 공정위와 협의합니다.","상호협정의 경미한 사항: 보험회사의 상호 변경·합병·신설 등으로 구성원이 변경되는 사항, 조문체제 변경·자구수정 등 실질적 내용이 변경되지 않는 사항, 법령 개정에 따른 수정·반영 사항. 인가 심사 항목: 보험회사 간 공정한 경쟁을 저해하는지, 계약자의 이익을 침해하는지":"구성원 변경과 자구 수정, 법령 개정 반영은 경미한 사항이고 인가 심사에서는 공정경쟁 저해와 계약자 이익 침해를 확인합니다.","상호회사는 정관으로 보험금액의 삭감에 관한 사항을 정해야 한다":"상호회사는 재정이 나빠질 때를 대비해 보험금액을 줄이는 방법을 정관으로 정해 두어야 합니다.","새로 성립된 사업(합병·분할된 경우 제외)의 사용자는 근로자대표의 의견을 들어 사업 성립 후 1년 이내에 DB 또는 DC를 설정해야 한다":"새로 생긴 사업의 사용자는 근로자대표 의견을 들어 성립 후 1년 안에 DB나 DC를 마련해야 합니다.","생명보험약관에서 인과관계 존재의 증명책임을 보험자로 정한 약정은 유효하다(보험계약자에게 유리)":"인과관계가 있다는 점을 보험자가 증명하게 하는 약관은 계약자에게 유리하므로 유효합니다.","생명보험업과 제3보험업의 겸영은 허용된다":"생명보험업과 제3보험업은 한 회사가 함께 영위하는 것이 허용됩니다.","생명보험업·손해보험업의 전 종목(보증보험·재보험 제외)을 허가받은 자는 제3보험업 허가를 받은 것으로 본다":"생명보험업이나 손해보험업의 모든 종목을 허가받은 자는 보증보험과 재보험을 제외하면 제3보험업 허가도 받은 것으로 봅니다.","생명보험업의 보험종목: 생명보험, 연금보험(퇴직보험 포함), 그 밖에 대통령령으로 정하는 종목":"생명보험업의 보험종목에는 생명보험과 퇴직보험을 포함한 연금보험과 대통령령이 정하는 종목이 있습니다.","서면동의는 계약 체결 시점까지 갖춰야 하며 사후 추인으로 유효가 되지 않는다":"서면동의는 계약을 맺는 시점까지 갖춰야 하며 나중에 추인해도 이미 무효인 계약이 유효가 되지 않습니다.","서면동의는 타인이 청약서에 직접 서명하는 경우만을 뜻하지 않는다. 구체적·개별적으로 권한을 수여받은 사람이 대행한 서면동의도 유효하다":"서면동의는 타인이 직접 서명한 경우에 한하지 않고 구체적이고 개별적으로 권한을 받은 사람이 대신한 동의도 유효합니다.","서면 질문: 보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다. 청약서에 답변을 구하는 취지가 있으면 같다":"보험자가 서면으로 물은 사항은 중요한 사항으로 추정하며 청약서에 답을 구하는 취지가 있어도 같습니다.","선박미확정의 적하예정보험: 하물을 적재할 선박을 지정하지 않은 경우 선적을 안 때 지체없이 선박의 명칭·국적과 하물의 종류·수량·가액을 통지해야 한다. 해태하면 보험자는 그 사실을 안 날부터 1월 내에 계약을 해지할 수 있다":"선박을 미리 못 정한 예정보험은 선적 사실을 안 즉시 알려야 하고 게을리하면 1월 안에 해지될 수 있습니다.","선박변경: 적하를 보험에 붙인 경우 보험계약자·피보험자의 책임 있는 사유로 선박을 변경하면 변경 후의 사고에 책임이 없다":"적하보험에서 계약자나 피보험자의 책임으로 선박을 바꾸면 보험자는 변경한 뒤에 난 사고에 책임이 없습니다.","선박보험: 보험자의 책임이 개시될 때의 선박가액이 보험가액이고, 속구·연료·양식 기타 항해에 필요한 모든 물건은 보험의 목적에 포함된다":"선박보험의 보험가액은 책임이 개시될 때의 선박가액이며 속구와 연료와 양식 등 항해에 필요한 물건도 보험의 목적에 포함됩니다.","선박보험의 보험가액은 보험자의 책임이 개시될 때의 선박가액이다":"선박보험에서 보험가액이 되는 것은 보험자의 책임이 시작되는 순간의 선박 가치입니다.","선박 승무원 직무 중 상해 면책약관은 선원이 직무상 선박에 탑승 중 잠수하여 그물을 제거하다 사망한 경우에도 적용되어 면책된다":"선박 승무원이 직무 중 입은 상해를 면책하는 약관은 선원이 배에 탑승해 잠수해서 그물을 제거하다 숨진 경우에도 적용됩니다.","선박·운임 보험에서 발항 당시 안전하게 항해할 준비를 하지 않거나 필요한 서류를 비치하지 않아 생긴 손해(감항능력 결여), 적하 보험에서 용선자·송하인·수하인의 고의 또는 중대한 과실로 생긴 손해, 도선료·입항료·등대료·검역료 등 항해 중 통상비용":"출항 때 안전 항해 준비나 서류를 갖추지 않아 생긴 손해와 용선자나 송하인의 고의나 중과실 손해와 항해 중 통상비용은 해상보험자가 면책됩니다.","선박의 양도·선급 변경·새로운 관리로 옮김 중 하나가 있으면 선박보험 계약은 종료한다. 보험자의 동의가 있으면 그렇지 않다":"선박을 양도하거나 선급을 바꾸거나 새로운 관리로 옮기면 선박보험은 종료하되 보험자가 동의했다면 종료하지 않습니다.","선박의 일부손해: 훼손된 부분을 전부 수선하면 수선비용을 1회 사고에 대해 보험금액 한도로 보상한다. 일부만 수선하면 수선비용과 수선하지 않은 감가액을 보상한다. 수선하지 않으면 감가액을 보상한다":"선박의 일부 손해는 전부 수선하면 수선비용을 보험금액 한도로 보상하고 일부만 수선하면 수선비용과 감가액을 수선하지 않으면 감가액을 보상합니다.","선박의 행방불명: 선박의 존부가 2월간 분명하지 않으면 행방불명이며 전손으로 추정한다. 위부 통지 없이 선박 보험금을 청구할 수 있다":"선박의 존재 여부를 2월간 알 수 없으면 행방불명으로 전손으로 추정하며 위부 통지 없이 선박 보험금을 청구할 수 있습니다.","선임계리사·보험계리사·보험계리업자의 금지행위: 고의로 진실을 숨기거나 거짓으로 보험계리를 하는 행위, 업무상 비밀 누설, 타인으로 하여금 자기 명의로 보험계리업무를 하게 하는 행위 등":"선임계리사와 보험계리사와 보험계리업자는 진실을 숨기거나 거짓으로 계리하거나 업무상 비밀을 누설하거나 자기 명의를 남에게 쓰게 하면 안 됩니다.","선임계리사의 의무: 기초서류 내용 및 배당금 계산이 정당한지 검증·확인. 기초서류관리기준 준수 여부를 점검하고 위반 시 조사해 이사회에 보고하며, 기초서류에 법령 위반 내용이 있으면 금융위원회에 보고한다":"선임계리사는 기초서류와 배당금 계산을 검증하고 관리기준 준수를 점검하며 위반은 이사회에, 법령 위반 기초서류는 위원회에 보고합니다.","선임계리사 임면: 이사회 의결을 거쳐 선임 후 금융위원회에 보고, 해임 전에 이사회 의결을 거쳐 금융위원회에 신고. 외국보험회사 국내지점은 이사회 의결을 거치지 않을 수 있다. 해임 신고 시 해임사유를 제출하고 금융위원회는 선임계리사의 의견을 들을 수 있다":"선임계리사 선임은 이사회 의결 후 위원회에 보고하고 해임은 사전에 이사회 의결과 신고를 거치며 위원회가 그 의견을 들을 수 있습니다.","선임계리사 자격: 등록된 보험계리사, 보험계리업무 10년 이상 종사(손해보험회사는 대통령령 업무 3년 포함), 최근 5년 내 경고·문책, 해임·직무정지, 등록취소, 업무정지·해임 조치를 받은 사실 없음":"선임계리사가 되려면 계리사로 등록하고 10년 이상 일했으며 최근 5년 내 경고나 해임, 등록취소 등을 받은 적이 없어야 합니다.","선주상호보험은 보험관계의 성질에 반하거나 특칙이 없는 한 상법 제4편이 준용된다":"선주상호보험도 보험관계의 성질에 어긋나거나 특별한 규정이 없으면 상법 보험편이 준용됩니다.","설계사, 대리점, 중개사, 보험계리사, 손해사정사, 그 밖에 보험 관계 업무 종사자가 공익과 계약자 보호, 모집질서 유지를 위해 각각 설립할 수 있는 법인. 회원 간 건전한 업무질서 유지, 연수·교육 업무 등":"설계사와 대리점, 중개사, 계리사, 손해사정사 등은 공익과 계약자 보호를 위해 업종별 단체를 법인으로 만들 수 있습니다.","설계사 등록취소(필요적): 결격사유 해당, 등록 당시 결격이었음이 밝혀진 경우, 부정 등록, 업무정지 2회 이상":"결격사유에 해당하거나 등록 당시부터 결격이었거나 부정하게 등록하거나 업무정지를 2회 이상 받으면 등록을 반드시 취소해야 합니다.","설립등기: 창립총회가 끝난 날부터 2주 이내. 이사 및 감사의 공동신청":"설립등기는 창립총회가 끝난 날부터 2주 안에 이사와 감사가 함께 신청합니다.","설명의무는 보험대리상도 부담한다":"약관을 설명할 의무는 보험자뿐 아니라 보험자를 대리하는 보험대리상도 부담합니다.","설명의무 대상으로 본 약관: 상해보험의 외과적 수술·의료처치로 인한 손해 면책, 기왕장해 감액, 연금보험의 연금액 변동가능성 규정(2024 기출 정답 가·다·바)":"수술로 인한 손해 면책과 기왕장해 감액과 연금액 변동가능성 규정은 계약자의 이익에 큰 영향이 있어 설명 대상으로 봤습니다.","설명의무 대상이 아닌 약관: 업무용자동차보험 피보험자동차 양도 통지의무, 해상구간 사고 제외 규정, 입주자 모집공고 승인 취소 시 보증계약 취소 규정(2024 기출)":"자동차 양도 통지의무와 해상구간 사고 제외 규정과 모집공고 승인 취소 시 보증계약 취소 규정은 설명 대상이 아니라고 봤습니다.","설명의무를 위반한 경우에는 고지의무 위반을 이유로 계약을 해지할 수 없다는 것이 판례다":"보험자가 약관 설명의무를 어겼다면 판례는 고지의무 위반을 이유로 계약을 해지하는 것을 허용하지 않습니다.","설명의무 위반으로 면책약관을 주장하지 못해 보험금을 지급한 경우에도 청구권대위를 할 수 있다":"설명의무를 어겨 면책약관을 내세우지 못한 채 보험금을 준 경우에도 보험자는 청구권대위를 할 수 있습니다.","설명의무 위반의 효과: 보험계약자는 보험계약이 성립한 날부터 3개월 이내에 그 계약을 취소할 수 있다(2026 기출 보기의 6월은 틀림)":"설명의무를 어기면 보험계약자가 계약 성립일부터 3개월 안에 계약을 취소할 수 있습니다.","소급보험: 보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다. 보험기간이 보험계약기간보다 길다":"소급보험은 계약을 맺기 전의 시점부터 보험기간을 시작하게 정할 수 있어서 보험기간이 계약기간보다 깁니다.","소멸시효 기산점: 보험금청구권은 권리를 행사할 수 있는 때(민법 제166조제1항)다. 보험사고 발생 여부가 객관적으로 분명하지 않아 과실 없이 알 수 없었다면 알았거나 알 수 있었던 때부터 진행한다":"보험금청구권의 시효는 권리를 행사할 수 있는 때부터 가며 사고 여부가 불분명해 과실 없이 몰랐다면 알 수 있었던 때부터입니다.","소방 등의 조치: 보험자는 화재의 소방 또는 손해의 감소에 필요한 조치로 인하여 생긴 손해를 보상한다. 소방관의 조치로 인한 손해도 포함한다":"화재 진압이나 손해 줄이기에 필요한 조치로 생긴 손해도 화재보험자가 보상하며 소방관의 조치로 인한 손해도 들어갑니다.","소손해면책: 분손에만 적용되고, 손해가 면책한도액을 초과하면 보험자는 손해 전부를 보상한다":"소손해면책은 분손에 쓰이며 손해가 면책한도를 넘으면 보험자는 전체 손해를 물어 줍니다.","소액단기전문보험회사가 모집할 수 있는 상품(2024 기출 정답): 생명보험, 책임보험, 동물보험, 질병보험. 연금·화재·자동차·간병보험은 해당하지 않는다":"소액단기전문보험회사가 팔 수 있는 상품은 생명보험과 책임보험과 동물보험과 질병보험이고 연금과 화재와 자동차와 간병보험은 대상이 아닙니다.","손실보전준비금: 각 사업연도 잉여금에서 적립한다. 손실 보전 전에는 기금이자 지급을 못하고, 설립비용·사업비 상각과 준비금 공제 전에는 기금 상각·잉여금 분배를 못한다":"잉여금에서 손실보전준비금을 적립해야 하고 손실을 메우기 전에는 기금이자 지급과 잉여금 분배가 제한됩니다.","손해방지비용은 손해 방지·경감의 효과가 생기지 않은 경우에도 필요 또는 유익했다면 보험자가 부담한다":"손해를 막으려고 쓴 비용은 결과적으로 효과가 없었더라도 그때 필요하거나 유익했다면 보험자가 부담합니다.","손해배상 보장: 보험계리업자 또는 손해사정업자가 고의 또는 과실로 타인에게 손해를 발생시킨 경우 금융위원회는 금융위원회가 지정하는 기관에의 자산 예탁, 보험 가입 등을 하게 할 수 있다":"계리업자나 손해사정업자가 고의나 과실로 손해를 입히면 위원회는 지정 기관 자산 예탁이나 보험 가입을 하게 할 수 있습니다.","손해보험상품의 정의에는 계약상 채무불이행 또는 법령상 의무불이행으로 발생하는 손해에 관한 계약이 포함된다":"손해보험상품은 우연한 사건으로 생기는 손해뿐 아니라 채무불이행이나 의무불이행에서 생기는 손해에 관한 계약도 포함합니다.","손해보험업의 보험종목: 화재보험, 해상보험(항공·운송보험 포함), 자동차보험, 보증보험, 재보험, 그 밖의 종목(책임, 기술, 권리, 도난·유리·동물·원자력, 비용, 날씨보험)":"손해보험업의 보험종목에는 화재와 해상과 자동차와 보증과 재보험과 책임과 기술 등 그 밖의 종목이 있습니다.","손해보험에서 다른 보험계약을 체결한 것은 통지의무 대상인 위험변경증가가 아니다":"손해보험에서 다른 보험계약을 새로 든 사실은 사고 위험을 늘리는 것이 아니라서 통지의무 대상이 아닙니다.","손해보험에서 보험의 목적의 성질·하자·자연소모로 인한 손해는 보상하지 않는다":"보험의 목적이 가진 성질이나 하자나 자연적 소모로 생긴 손해는 우연한 사고가 아니라서 보상하지 않습니다.","손해보험에서 타인의 위임이 없으면 보험계약자는 이를 보험자에게 고지해야 하고, 고지가 없으면 타인이 계약 체결 사실을 몰랐다는 사유로 보험자에게 대항하지 못한다":"타인의 위임 없이 계약했다면 계약자가 그 사실을 보험자에게 알려야 하고 알리지 않으면 타인이 몰랐다는 이유로 보험자에게 맞서지 못합니다.","손해보험증권에 기재되는 보험금액·보험기간은 보험증권 기재사항이다. 보험기간은 보험자의 책임이 존속하는 기간이고, 계약기간과 일치할 필요가 없다":"보험기간은 보험자가 책임지는 기간이라서 증권에 적힌 보험금액과 함께 기재되며 계약기간과 같을 필요가 없습니다.","손해보험증권의 기재사항: 보험의 목적, 보험사고의 성질, 보험금액, 보험료와 그 지급방법, 보험기간의 시기와 종기, 무효와 실권의 사유, 보험계약자의 주소·성명(상호), 피보험자의 주소·성명(상호), 계약 연월일, 증권 작성지와 작성 연월일":"손해보험증권에는 보험의 목적과 사고의 성질과 보험금액과 보험료와 보험기간과 당사자 정보와 계약일과 작성일 등이 적힙니다.","손해보험협회: 제3자 보험금 지급 보장을 위해 출연금을 받아 보험금을 지급하고 구상권을 가진다. 필요 시 정부, 예금보험공사 등에서 금융위원회 승인을 받아 자금을 차입할 수 있다":"손해보험협회는 출연금으로 제삼자 보험금을 대신 지급한 뒤 구상권을 행사하며 승인을 받아 정부 등에서 자금을 빌릴 수 있습니다.","손해사정: 보험사고에 따른 손해액 및 보험금의 사정. 손해보험상품(보증보험 제외)이나 제3보험상품을 판매하는 보험회사는 직접 수행하거나 손해사정사·손해사정업자에게 위탁해야 한다. 외국 발생 사고, 계약자가 손해사정사를 따로 선임하고 보험회사가 동의한 경우는 예외":"손해사정은 손해액과 보험금을 정하는 일이며 손해보험과 제3보험 회사는 직접 하거나 위탁하되 외국 사고 등은 예외입니다.","손해사정사는 금융감독원장이 실시하는 시험 합격과 실무수습 후 금융위원회에 등록한다. 손해사정업은 금융위원회에 등록하고, 법인은 상근 손해사정사 2명 이상(수행 업무 종류별 1명 이상)을 둔다. 결원은 2개월 이내 충원. 등록일부터 1개월 내에 업무를 시작한다":"손해사정사는 시험과 실무수습 뒤 등록하고 업 법인은 상근 2명 이상을 두며 결원은 2개월 안에 채우고 1개월 안에 업무를 개시합니다.","손해사정사를 고용해 담당하게 하는 것과 위탁기준을 마련해 준수하는 것은 금지행위가 아니다":"손해사정사를 고용해 맡기는 것과 위탁기준을 마련해 지키는 것은 준수사항일 뿐 금지행위가 아닙니다.","손해사정사·손해사정업자의 업무: 손해 발생 사실 확인, 보험약관 및 관계 법규 적용의 적정성 판단, 손해액 및 보험금 사정, 관련 서류 작성·제출 대행, 보험회사에 대한 의견 진술":"손해사정사의 일은 사실 확인, 약관 적용 판단, 손해액과 보험금 산정, 서류 작성 대행, 회사에 대한 의견 진술입니다.","손해사정사·업자·보험계리사 등에 대한 감독: 직무를 게을리하거나 부적절한 행위를 하면 6개월 이내의 업무정지 또는 해임. 등록취소 규정(제86조)을 준용한다":"손해사정사와 계리사 등이 직무를 게을리하거나 부적절하게 행동하면 6개월 이내 업무정지나 해임을 받을 수 있고 등록취소 규정도 준용합니다.","손해사정사의 의무: 손해사정서를 작성하면 지체 없이 보험회사·계약자·피보험자 등에게 내어 주고 중요한 내용을 알린다. 고의로 진실을 숨기거나 거짓 사정, 보험회사 또는 계약자 일방에 유리한 사정, 개인정보 누설, 명의 대여, 정당한 사유 없는 지연, 중복 서류 요청, 보험금 지급을 요건으로 한 합의서 작성 등은 금지":"손해사정서는 지체 없이 관계인에게 내주고 중요한 점을 알려야 하며 거짓 사정, 일방 유리 사정, 개인정보 누설, 명의 대여는 금지됩니다.","손해사정업자에 대한 조치: 자산상황이 불량하여 계약자 등의 권익을 해칠 우려가 있으면 불건전한 자산에 대한 적립금 보유 등을 명할 수 있다(제131조제1항 준용)":"손해사정업자의 자산이 불량해 계약자 권익을 해칠 우려가 있으면 불건전한 자산에 대한 적립금 보유 등을 명할 수 있도록 명령 규정을 준용합니다.","손해사정 위탁 시 금지행위: 위탁계약서 미교부, 계약사항 불이행·위탁계약서 외 업무 강요, 해지요건 외 사유로 해지, 정당한 사유 없는 해지 요청 거부, 수수료 미지급·지연, 수수료 환수, 손해사정을 보험회사에 유리하게 하도록 강요하는 등 개입, 자회사 우대 평가":"위탁 시 계약서 미교부, 계약 외 업무 강요, 부당 해지, 수수료 지연, 회사에 유리한 사정 강요, 자회사 우대 평가는 금지입니다.","손해액의 산정기준: 손해가 발생한 때와 곳의 가액. 다른 약정이 있으면 신품가액으로 산정할 수 있다(신가보험). 산정 비용은 보험자가 부담한다":"손해액은 손해가 생긴 때와 곳의 가액으로 정하고 약정하면 신품가액으로도 정할 수 있으며 산정 비용은 보험자가 부담합니다.","수수료: 운용관리·자산관리 업무 수수료는 사용자가 부담한다. 다만 가입자 스스로 부담하는 추가 부담금에 대한 수수료는 가입자가 부담한다":"운용과 자산관리 수수료는 사용자가 내지만 가입자가 자기 돈으로 더 넣은 부분의 수수료는 가입자 몫입니다.","수수료: 퇴직연금사업자의 수수료는 업무 수행 비용과 적립금 운용 손익을 고려해 합리적으로 정하고 부과기준(업무 구분·비용, 운용 손익 고려, 중소기업·사회적기업 감면)을 준수한다":"연금사업자의 수수료는 업무 비용과 운용 손익을 고려해 합리적으로 정하고 부과기준과 감면 규정을 따라야 합니다.","수수료 지급 등의 금지: 보험회사는 모집할 수 있는 자 이외에게 모집을 위탁하거나 수수료를 지급하지 못한다. 보험중개사는 대통령령 사유 외에 계약자에게 중개 수수료를 청구하지 못한다":"회사는 자격 없는 사람에게 모집을 맡기거나 수수료를 줄 수 없고 중개사는 법정 사유 밖에서 계약자에게 중개료를 못 받습니다.","수시 교체: 집합된 물건의 일부가 보험기간 중 수시로 교체된 경우에도 보험사고 발생 시 현존한 물건은 보험의 목적에 포함된다":"집합된 물건이 보험기간 중 수시로 교체되더라도 사고 당시 존재하던 물건은 보험의 목적에 해당합니다.","수익자를 단순히 상속인으로 지정하면 피보험자의 민법상 법정상속인을 뜻하고, 보험금청구권은 상속인의 고유재산이다. 수인이면 법정상속분 비율로 청구권을 가진다":"수익자를 상속인으로만 지정하면 피보험자의 법정상속인을 뜻하며 보험금청구권은 상속인 고유의 재산이고 여럿이면 법정상속분 비율로 갖습니다.","수협중앙회 어선공제처럼 영세어민을 주된 대상으로 하는 공제는 불이익변경금지 원칙의 적용 대상이 될 수 있다":"영세어민을 주로 상대하는 어선공제처럼 약자 보호가 필요한 공제는 불이익변경금지 원칙의 적용 대상이 될 수 있습니다.","순수한 건강검진 목적의 의료처치로 생긴 상해는 '외과적 수술, 그 밖의 의료처치' 면책 조항에 해당하지 않는다":"순수한 건강검진 목적의 의료처치로 생긴 상해는 외과적 수술이나 의료처치를 면책하는 조항의 대상이 아닙니다.","술에 취해 선로에 내려가 전동열차에 부딪혀 사망한 경우 판단능력 상실·미약 정도의 과음 중과실이 있어도 우연성이 충족된다":"술에 취해 선로에 내려가 열차에 부딪혀 숨졌다면 판단능력이 약해질 만큼 과음한 중과실이 있어도 우연성이 인정됩니다.","술을 마시고 잠을 자다 구토하여 기도폐색으로 질식·사망한 경우 외래성이 인정되고 급격성도 충족된다":"술을 마시고 자다가 구토해 기도가 막혀 숨진 경우에도 외래성이 인정되고 급격성도 충족됩니다.","승낙 의제에 상인 간 상시 거래관계는 요건이 아니다":"낙부통지를 게을리해 승낙으로 간주하는 규정은 상인 사이에 계속 거래하는 관계가 없어도 적용됩니다.","승낙 전 보험보호가 적용되는 경우에도 보험기간이 보험계약기간보다 길다":"승낙 전에도 보험보호가 적용되면 보험기간이 계약이 성립하기 전부터 시작되어 계약기간보다 깁니다.","승인사항: 대통령령으로 정하는 자본감소(제18조제2항), 자산운용 제한 예외 중 일정 사유(제107조제1항제3호), 일정 자회사 소유(제115조제1항)":"승인을 받아야 하는 사항에는 대통령령이 정하는 자본감소와 자산운용 제한의 일정 예외와 일정 자회사 소유가 있습니다.","승인을 받으려면 퇴직연금 관련 전문가를 포함한 고용노동부장관 소속 심의위원회의 사전심의를 받는다. 사전지정운용방법은 우편 발송, 서면 교부, 정보통신망 전송 등으로 사용자에게 제시한다":"승인을 받으려면 전문가가 든 장관 소속 심의위원회의 사전심의를 거쳐야 하고 결정된 방법은 우편이나 서면, 전송으로 사용자에게 알립니다.","시행령상 추가 서류(주식회사·상호회사): 발기인회의 의사록, 임원·발기인 이력서·경력증명서, 합작계약서(외국기업과 합작 시), 자본금·기금 납입 증명서류, 재무제표와 부속서류, 주주(사원) 명세서. 종목 추가 시 가목~다목은 제출하지 않을 수 있다":"시행령상 추가 서류에는 발기인회의 의사록과 임원 이력서와 합작계약서와 자본금 납입 증명서류와 재무제표와 주주 명세서가 있습니다.","시행령상 협회 업무: 위탁받은 설계사·대리점 등록, 경영 관련 정보 수집·통계 작성, 차량수리비 실태 점검, 모집 관련 전문자격제도 운영·관리, 보험설계사·개인보험대리점 경력 관리, 보험가입 조회, 보험사기 방지 교육·홍보와 포상금 지급, 단순 민원 상담·처리 등":"협회의 시행령상 일은 설계사 등록, 통계, 수리비 점검, 자격제도, 경력과 가입 조회, 사기 방지 교육과 포상금 지급 등입니다.","신고사항: 겸영업무(제11조), 부수업무(제11조의2), 선임계리사 해임(제181조의2), 일정 사유의 기초서류 작성·변경(제127조제2항)":"신고만 하면 되는 사항에는 겸영업무와 부수업무와 선임계리사 해임과 일정 사유의 기초서류 작성과 변경이 있습니다.","신체검사를 받아야 하는 인보험에서 피보험자가 신체검사를 받지 않았다면, 승낙 전 사고에 대해 보험자는 책임이 없다":"신체검사가 필요한 인보험에서 검사를 받지 않았다면 승낙 전에 난 사고에 보험자는 책임이 없습니다.","신체의 상해에 관한 보험사고가 생길 경우 보험금액 기타의 급여를 한다":"상해보험자는 피보험자의 신체에 상해라는 보험사고가 생기면 보험금액이나 그 밖의 급여를 지급합니다.","실손보상의 원칙을 구현하는 제도: 선의의 중복보험의 비례주의, 손해보험계약의 잔존물대위, 선의의 초과보험. 신가보험·기평가보험은 예외로 본다":"실제 입은 손해만 보상한다는 원칙을 구현하는 제도에는 비례주의와 잔존물대위와 초과보험 규정이 있고 신가보험과 기평가보험은 예외입니다.","실손의료보험 서류 전송: 계약자 등은 요양기관에 보험금 청구서류를 보험회사에 전자적으로 전송해 달라고 요청할 수 있다. 보험회사는 전산시스템을 구축·운영하되 전송대행기관(보험요율 산출기관)에 위탁할 수 있고, 비용은 보험회사가 부담한다. 실손전산시스템운영위원회는 위원장 포함 18명, 위원 임기 2년":"계약자는 병원에 청구서류의 전자 전송을 요청할 수 있고 시스템 구축 비용은 보험회사가 대며 전송대행기관에 맡길 수 있습니다.","실효예고부 최고 약관(해지절차 없이 실효 처리)은 상법 제650조의 해지절차를 배제하므로 무효다":"최고만으로 계약이 자동 실효되게 한 약관은 상법이 정한 해지절차를 없애 버리므로 무효입니다.","심사기간: 허가신청을 받으면 2개월(예비허가를 받았으면 1개월) 이내에 심사하여 허가 여부를 통지한다":"금융위원회는 허가신청을 받으면 2개월 안에 심사해 통지하고 예비허가를 받았다면 1개월 안에 합니다.","안정성·유동성·수익성·공익성이 확보되도록 하고, 선량한 관리자의 주의로 운용한다":"보험회사는 자산을 운용할 때 안정성과 유동성과 수익성과 공익성을 확보하고 선량한 관리자의 주의로 운용해야 합니다.","암보험의 원발부위 기준 분류조항, 전문직업배상책임보험의 서면통지 약관은 설명의무의 대상이다":"암보험에서 원발부위를 기준으로 분류하는 조항과 전문직업배상책임보험의 서면통지 약관은 설명해야 하는 중요한 내용입니다.","암 진단 확정 전 가입한 경우 계약 무효로 하는 약관, 기존 장해 후유장해보험금 차감 약관은 유효하다":"진단 확정 전 가입한 계약을 무효로 하는 약관과 기존 장해를 차감하는 약관은 유효하다고 봅니다.","약관은 고객 평균 이해가능성을 기준으로 객관적·획일적으로 해석한다. 의미가 일의적으로 명확하면 작성자 불이익 원칙이 적용되지 않는다":"약관은 평균적인 고객이 이해할 수준으로 획일적으로 해석하고 뜻이 하나로 분명하면 작성자에게 불리하게 풀지 않습니다.","약관의 모든 내용이 아니라 중요한 내용이다. 약정면책사유는 원칙적으로 설명의무의 대상이다":"설명할 대상은 약관 전체가 아니라 중요한 내용이며 약정 면책사유는 원칙적으로 중요한 내용에 해당합니다.","양도담보권자는 양도담보 목적물이 화재로 소실된 경우 설정자의 화재보험금청구권에 대해 압류 및 추심명령으로 추심권을 행사할 수 있다":"양도담보 목적물이 불에 타면 담보권자는 설정자의 화재보험금청구권을 압류하고 추심명령으로 받아 낼 수 있습니다.","양도 통지의무를 위반해도 위험의 현저한 변경·증가가 없다면 보험자는 보험금을 지급할 의무가 있다. 통지한다고 보험계약이 계약자 A·피보험자 B의 타인을 위한 보험으로 바뀌는 것은 아니다":"양도 통지를 하지 않았어도 위험이 현저히 늘지 않았다면 보험금을 줘야 하며 통지한다고 계약이 타인을 위한 보험으로 바뀌지는 않습니다.","업무 위탁: 설계사·대리점 등록업무는 보험협회에, 보험중개사·보험계리사·보험계리업·손해사정사·손해사정업 등록업무는 금융감독원장에게 위탁한다":"설계사와 대리점의 등록업무는 보험협회에 맡기고 중개사와 계리사와 손해사정사 등의 등록업무는 금융감독원장에게 위탁합니다.","영국법 준거 보험증권에 감항증명서 발급을 담보하는 명시 규정이 있으면 그 규정에 따르고, 감항증명서는 매 항해마다 발급받아야 한다":"영국법을 따르는 증권에서 감항증명서를 담보하는 명시 규정이 있으면 그에 따르고 증명서는 항해마다 발급받아야 합니다.","영국해상보험법상 선박기간보험의 피보험자 악의(privity): 감항능력 없음을 아는 것뿐 아니라 없을 수도 있음을 알면서 조치하지 않은 경우까지 포함한다":"영국법의 악의는 감항능력이 없음을 알았던 경우는 물론 없을 가능성을 알고도 방치한 경우까지 넓게 봅니다.","영업보증금: 5억원 이하의 금액 범위에서 보험회사와 협의. 금융기관보험대리점은 예탁의무 면제. 금융위원회가 지정하는 영업보증금예탁기관에 예탁":"영업보증금은 5억원 이하 범위에서 보험회사와 협의해 정하고 금융위원회가 지정한 기관에 예탁하며 금융기관보험대리점은 예탁이 면제됩니다.","영업보증금: 개인 1억원 이상, 법인 3억원 이상. 금융기관보험중개사는 예탁 면제. 금융위원회가 지정하는 기관에 예탁하거나 보험 가입 등을 하게 할 수 있다":"보험중개사의 영업보증금은 개인 1억원 이상 법인 3억원 이상이며 금융기관보험중개사는 예탁이 면제되고 보험 가입으로 대신하게 할 수도 있습니다.","영업 전부정지·허가취소(제134조제2항): 부정한 방법으로 허가를 받은 경우, 허가의 내용·조건 위반, 정지기간 중 영업, 시정명령 불이행 등에 해당하면 6개월 이내 영업 전부정지를 명하거나 청문을 거쳐 허가를 취소할 수 있다":"허가를 부정하게 받거나 조건을 어기거나 정지 중 영업하면 6개월 이내 전부정지나 청문 후 허가취소를 할 수 있습니다.","영업책임보험: 피보험자의 대리인 또는 그 사업감독자의 제3자에 대한 책임도 보험의 목적에 포함된다":"영업책임보험에서는 피보험자의 대리인이나 사업감독자가 제삼자에게 지는 책임도 보험의 목적에 포함됩니다.","영업책임보험: 피보험자의 대리인 또는 사업감독자의 제3자에 대한 책임도 보험의 목적에 포함된다":"영업책임보험은 피보험자뿐 아니라 그 대리인이나 사업감독자가 제삼자에게 지는 책임도 보험의 대상에 넣습니다.","영 제16조제1항 겸영 업무: 자산유동화법상 유동화자산 관리, 한국주택금융공사법상 채권유동화자산 관리, 전자금융거래법상 전자자금이체업무, 신용정보법상 본인신용정보관리업 (2021 기출 당시 주택저당채권 유동화회사법상 관리업무도 포함. 2024 기출 정답 3은 이 업무가 현행 목록에 없음을 묻는다)":"신고하고 겸영할 수 있는 업무에는 유동화자산 관리와 채권유동화자산 관리와 전자자금이체업무와 본인신용정보관리업이 있습니다.","영 제16조제2항(인가·허가·등록 필요 금융업): 집합투자업, 투자자문업, 투자일임업, 신탁업, 집합투자증권 투자매매·중개업, 외국환업무, 퇴직연금사업자 업무, 선불전자지급수단 발행·관리":"집합투자업과 신탁업, 외국환업무, 퇴직연금사업자 업무 등은 인가나 허가나 등록을 받고 겸영하는 금융업입니다.","영 제17조 대상: 자영업자, 퇴직급여제도 미설정 대상인 근로자(계속근로기간 1년 미만, 4주 평균 주 소정근로시간 15시간 미만), 퇴직금제도를 적용받는 근로자, 공무원연금법 적용 공무원, 군인연금법 적용 군인, 사립학교교직원 연금법 적용 교직원, 별정우체국법 적용 직원":"자영업자와 퇴직급여제도 미설정 근로자, 퇴직금제도 적용자, 공무원과 군인, 사립학교 교직원, 별정우체국 직원이 영 제17조 대상입니다.","영화촬영장비 임차인이 임대인을 피보험자로 한 손해보험을 체결하고 임차인의 과실로 파손된 경우 보험자는 임차인에게 청구권대위를 할 수 있다":"임차인이 임대인을 피보험자로 보험을 들었는데 임차인의 과실로 장비가 파손되면 보험자는 임차인에게 청구권대위를 할 수 있습니다.","예외: 고지의무 위반 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급해야 한다. 인과관계 부존재의 증명책임은 보험계약자·피보험자에게 있다":"위반한 사실이 사고에 영향을 주지 않았다고 증명되면 보험금을 줘야 하며 그 증명은 계약자와 피보험자가 해야 합니다.","예외: 제659조제1항의 보험사고가 보험계약자에 의하여 생긴 경우에는 다른 약정이 없으면 적립금을 지급하지 않는다. 따라서 계약자 고의로 보험사고가 발생한 경우가 정답(지급 안 함)이다":"사고가 보험계약자의 고의 등으로 생겼다면 다른 약정이 없는 한 보험자는 적립금을 돌려주지 않습니다.","예정보험: 계약 체결 당시 주요 원칙만 합의하고 적하물 종류·적재 선박·보험금액 등 증권 기재사항 일부가 확정되지 않은 보험":"예정보험은 계약 때 주요 원칙만 합의하고 적하물 종류와 선박과 보험금액 같은 일부 사항을 나중에 확정하는 보험입니다.","예탁자산에 대한 우선변제권: 금융위원회 명령으로 예탁한 자산에서 다른 채권자보다 우선하여 변제받는다. 특별계정은 구분 적용":"금융위원회의 명령으로 맡겨 둔 자산에서 계약자 등은 다른 채권자보다 우선해 변제받고 특별계정은 구분해서 적용합니다.","외국보험회사국내지점에는 제8조, 해산·합병 관련 제138조·제139조, 제148조, 제149조 등 일부 규정을 적용하지 않는다":"외국보험회사 국내지점에는 보험회사의 해산과 합병 등에 관한 일부 규정이 맞지 않아 적용하지 않습니다.","외국보험회사국내지점은 이 법에 따른 보험회사로 본다. 허가취소 사유(본점): 합병·영업양도 등으로 소멸, 위법행위·불건전 영업행위로 외국감독기관으로부터 허가취소에 상당하는 조치(영업 전부 정지 등), 휴업·영업 중지":"외국보험회사 국내지점은 보험회사로 취급하며 본점이 소멸하거나 외국감독기관에서 영업 전부 정지 등을 받거나 휴업하면 허가취소 사유가 됩니다.","외국보험회사등의 국내사무소: 설치일부터 30일 이내 신고. 보험업 경영, 보험계약 체결의 중개·대리 등을 해서는 안 되며 명칭에 사무소 글자를 포함해야 한다. 금융위원회는 6개월 이내 업무정지나 폐쇄를 명할 수 있다":"국내사무소는 설치 30일 안에 신고하며 영업이나 중개와 대리는 못 하고 6개월 이내 정지나 폐쇄를 받을 수 있습니다.","외국보험회사의 영업기금은 30억원 이상으로 하며 제1항·제2항의 자본금으로 본다":"외국보험회사의 영업기금은 30억원 이상이어야 하며 일반 보험회사의 자본금과 같은 것으로 취급합니다.","외국보험회사의 허가 요건: 영업기금 보유, 국내에서 경영하려는 보험업과 같은 보험업을 외국 법령에 따라 경영, 자산상황·재무건전성·영업건전성이 충분하고 국제적으로 인정, 인력·물적시설·사업계획 요건":"외국사는 영업기금과 본국에서의 같은 업종 영위, 국제적으로 인정되는 건전성, 인력 및 시설 요건을 충족해야 합니다.","외래성, 급격성, 우연성. 사고의 급격성·우연성·외래성 및 사고와 신체 손상 간 인과관계의 증명책임은 보험금을 청구하는 자가 진다":"상해의 요소는 외래성과 급격성과 우연성이며 이 요소와 사고와 상해의 인과관계는 보험금을 청구하는 사람이 증명해야 합니다.","외래의 사고와 기왕증이 공동원인이 된 경우에도 사고와 후유장해 간 인과관계가 인정되면 보험금을 지급한다. 기여도 감액은 약관에 감액 조항이 있어야 하며, 기여도는 기왕증의 원인·정도, 상관관계, 연령·직업·건강상태를 종합해 정한다":"사고와 기왕증이 겹친 후유장해도 인과관계가 있으면 지급하고 기여도 감액은 약관에 감액 근거가 있을 때만 가능합니다.","우선변제: 최종 3년간의 퇴직급여등(퇴직금, DB 급여, DC·중소기업퇴직연금기금·IRP의 미납입 부담금과 지연이자)은 사용자의 총재산에 대해 질권·저당권으로 담보된 채권, 조세·공과금 및 다른 채권에 우선하여 변제된다":"최종 3년치 퇴직급여는 사용자 전 재산에서 저당 잡힌 채권이나 세금보다도 먼저 갚아야 하는 우선변제 대상입니다.","우선취득권: 보험계약자나 보험금을 취득할 자는 피보험자를 위하여 적립한 금액을 다른 법률에 특별한 규정이 없으면 주식회사의 자산에서 우선하여 취득한다. 특별계정이 설정되면 특별계정과 그 밖의 계정을 구분하여 적용한다":"계약자와 수취인은 적립금을 다른 채권자에 앞서 회사 자산에서 받을 수 있고 특별계정은 따로 취급합니다.","우연한 사건(질병·상해·간병 제외)으로 발생하는 손해(채무불이행·의무불이행 손해 포함)에 관하여 급여를 지급하기로 하는 계약":"손해보험상품은 질병과 상해와 간병을 뺀 우연한 사건으로 생기는 손해에 대해 급여를 지급하기로 하는 계약입니다.","운송물의 보험가액: 발송한 때와 곳의 가액과 도착지까지의 운임 기타의 비용. 운송물의 도착으로 얻을 이익은 약정이 있는 때에 한하여 보험가액에 산입한다":"운송물의 보험가액은 발송한 때와 곳의 가액에 운임 등을 더한 금액이고 도착으로 얻을 이익은 약정이 있을 때만 넣습니다.","운송보험자의 책임: 다른 약정이 없으면 운송인이 운송물을 수령한 때부터 수하인에게 인도할 때까지 생길 손해를 보상한다":"운송보험의 보상 기간은 특약이 없으면 운송인이 물건을 받은 때부터 수하인에게 인도할 때까지입니다.","운송보험증권의 추가 기재사항: 운송의 노순과 방법, 운송인의 주소·성명(상호), 운송물의 수령·인도 장소, 운송기간을 정한 때 그 기간, 보험가액을 정한 때 그 가액":"운송보험증권에는 일반 사항에 더해 운송의 경로와 방법과 운송인 정보와 수령과 인도 장소와 운송기간과 보험가액이 적힙니다.","운용관리업무: 적립금 운용방법 및 정보 제공, 사전지정운용제도 설정·운영(DC만), 연금제도 설계 및 연금 회계처리(DB만), 운용현황 기록·보관·통지, 운용지시 전달 등. 자산관리업무: 계좌 설정·관리, 부담금 수령, 적립금 보관·관리, 운용지시 이행, 급여 지급 등":"운용관리업무는 운용방법 제시와 운용현황 통지, 운용지시 전달 등이고 자산관리업무는 계좌와 보관, 지시 이행, 급여 지급 등입니다.","운용관리업무 수행 사업자의 금지행위: 손실 전부·일부를 부담하겠다는 약속, 과도한 부가서비스 등 특별한 이익 제공, 개인정보 목적 외 사용, 자기·제3자 이익을 위해 특정 운용방법 제시":"운용관리 사업자는 손실을 대신 떠안겠다고 약속하거나 지나친 부가서비스를 주거나 개인정보를 목적 외로 쓰면 안 됩니다.","운용관리업무 수행 퇴직연금사업자는 (1) 적립금의 원리금이 보장되는 운용유형 또는 (2) 일정 요건의 집합투자증권 운용유형(목표시점 펀드, 위험관리 분산투자, 단기금융상품 등) 중 하나 이상을 포함해 고용노동부장관의 승인을 받는다. 원리금보장형을 반드시 포함할 필요는 없다":"사전지정운용방법은 원리금보장형이나 목표시점 펀드 같은 집합투자증권형 중 하나 이상으로 장관 승인을 받으며 원리금보장형이 꼭 필요하진 않습니다.","운용관리·자산관리 업무의 수수료는 사용자가 부담한다. 사용자는 매년 1회 이상 정기적으로 부담금을 납입한다":"운용과 자산관리 업무에 드는 수수료는 사용자가 내고 부담금도 해마다 한 번 이상 정기적으로 내야 합니다.","운용방법 제시 요건: 정보 취득과 이해가 쉬울 것, 운용방법 간 변경이 쉬울 것, 운용결과 평가 방법과 절차가 투명할 것, DC·IRP는 원리금보장 운용방법이 하나 이상 포함될 것, 분산투자 등 대통령령 기준에 따를 것":"제시하는 운용방법은 이해와 변경이 쉽고 평가가 투명해야 하며 DC와 IRP에는 원금을 지켜 주는 방법이 하나 이상 있어야 합니다.","운용현황의 통지: 퇴직연금사업자는 매년 1회 이상 적립금액 및 운용수익률 등을 가입자에게 알린다":"연금사업자는 해마다 한 번 이상 적립금과 수익률을 가입자에게 알려 줘야 합니다.","월간 업무보고서: 매월의 업무 내용을 다음 달 말일까지 금융위원회에 제출한다. 제출서류는 대통령령에 따라 전자문서로 제출할 수 있다":"보험회사는 매월의 업무 내용을 다음 달 말일까지 금융위원회에 제출하며 서류는 전자문서로 낼 수 있습니다.","월급·일당과 함께 퇴직금을 미리 지급하기로 하는 약정은 중간정산이 인정되는 경우가 아니면 퇴직금청구권의 사전 포기로서 강행법규 위반이라 무효다":"퇴직금을 월급에 얹어 미리 주기로 한 약정은 정산 요건에 맞지 않으면 사전 포기에 해당해 강행법규에 어긋나 무효입니다.","위부권행사 요건: 무조건이어야 하고, 보험의 목적 전부에 대해 해야 하며(원인이 일부에 생기면 그 부분만), 일부보험이면 보험금액의 보험가액에 대한 비율로만 위부할 수 있다":"위부권은 조건 없이 목적 전부에 대해 행사해야 하고 원인이 일부에만 있으면 그 부분만 하며 일부보험이면 비율만큼만 할 수 있습니다.","위부 원인: (1) 피보험자가 선박·적하의 점유를 상실하여 회복 가능성이 없거나 회복비용이 회복했을 때의 가액을 초과하리라 예상될 때. (2) 선박이 심하게 훼손되어 수선비용이 수선 후 가액을 초과하리라 예상될 때. (3) 적하가 심하게 훼손되어 수선비용과 목적지까지 운송비용의 합계가 도착 시 적하가액을 초과하리라 예상될 때":"위부는 회복 불가능이나 회복비용이 가치보다 큰 경우, 수선비가 수선 후 가액을 넘는 경우에 가능합니다.","위부의 법적 성질: 피보험자의 일방적 의사표시로 효과가 생기는 형성권이다. 잔존물대위는 법률상 당연히 취득하고 현실전손이 필요하며, 위부는 해상보험에만 있고 인보험에는 적용되지 않는다":"위부는 피보험자 혼자의 의사표시로 효과가 생기는 형성권이고 잔존물대위는 법률상 당연히 취득하며 위부는 해상보험에만 있고 인보험에는 없습니다.","위부의 승인: 보험자가 승인한 후에는 이의를 하지 못한다. 승인하지 않으면 피보험자는 위부의 원인을 증명해야 보험금액을 청구할 수 있다":"보험자가 위부를 승인한 뒤에는 이의를 못 하고 승인하지 않으면 피보험자가 위부 원인을 증명해야 보험금액을 청구할 수 있습니다.","위부의 효과: 보험자는 보험의 목적에 관한 피보험자의 모든 권리를 취득하고, 피보험자는 목적에 관한 모든 서류를 보험자에게 교부해야 한다":"위부가 이루어지면 보험자는 보험의 목적에 관한 피보험자의 모든 권리를 얻고 피보험자는 관련 서류를 모두 넘겨야 합니다.","위부 통지: 피보험자가 위부하려면 상당한 기간 내에 보험자에게 통지를 발송해야 한다":"피보험자가 보험의 목적을 위부하려면 상당한 기간 안에 보험자에게 위부 통지를 보내야 합니다.","위탁 시 준수: 선정기준 등 업무위탁기준을 마련해 준수, 자회사인 손해사정업자에게 직전 사업연도 위탁 비율의 100분의 50을 초과하여 위탁하면 선정기준과 결과를 이사회에 보고하고 공시":"위탁 때는 선정기준을 두고 지키며 자회사에 직전 연도 비율의 100분의 50을 넘게 맡기면 이사회 보고와 공시를 해야 합니다.","위험변경증가의 입증책임은 보험자에게 있다":"위험이 현저하게 변경되거나 증가했다는 사실은 보험자가 증명해야 합니다.","음주운전 중 보험사고라도 고의에 의한 사고가 아니면 음주운전 면책약관으로 보험금 지급을 거절할 수 없다":"고의가 아닌 음주운전 사고에는 음주운전 면책약관을 근거로 보험금을 거절할 수 없습니다.","의결권: 사원은 총회에서 각각 1개의 의결권을 가진다. 정관에 특별한 규정이 있으면 예외":"상호회사의 사원은 총회에서 각각 한 표의 의결권을 가지며 정관에 특별한 규정이 있으면 예외입니다.","의미: 그 위험이 계약 체결 당시 존재했다면 보험자가 계약을 체결하지 않았거나 적어도 그 보험료로는 인수하지 않았을 정도":"위험이 현저히 늘었다는 것은 계약 때 그 위험이 있었다면 보험자가 계약하지 않거나 그 보험료로는 받지 않았을 정도를 말합니다.","이로(離路): 선박이 정당한 사유 없이 정한 항로를 이탈한 경우 보험자는 그때부터 책임이 없고, 손해 발생 전에 원항로로 돌아온 경우에도 같다":"선박이 정당한 사유 없이 정한 항로를 벗어나면 그때부터 보험자는 책임이 없고 손해 전에 원래 항로로 돌아왔어도 마찬가지입니다.","이의제기한 보험계약자가 이전될 계약자 총수의 10분의 1을 초과하거나 그 보험금액이 이전될 보험금 총액의 10분의 1을 초과하면 보험계약을 이전하지 못한다":"이의를 낸 계약자가 이전될 계약자 총수의 10분의 1을 넘거나 그 보험금액이 총액의 10분의 1을 넘으면 보험계약을 이전할 수 없습니다.","이의 제출 계약자 수·보험금이 비율을 넘지 않으면 이사는 상법 제232조 절차가 끝나면 7일 이내에 소집한다. 계약자 과반수 출석과 의결권의 4분의 3 이상 찬성으로 결의한다":"이의가 기준 비율을 넘지 않으면 7일 안에 총회를 열고 과반수 출석과 4분의 3 이상 찬성으로 결의합니다.","이전 공고: 보험계약을 이전한 경우 7일 이내에 취지를 공고한다. 이전하지 않게 된 경우도 같다":"보험계약을 이전했을 때는 7일 안에 취지를 공고해야 하고 이전하지 않게 된 경우에도 같습니다.","이전 시 계약조건 변경: 계산의 기초 변경, 보험금액의 삭감과 장래 보험료 감액, 계약조항 변경을 정할 수 있다. 보험금액을 삭감하기로 하면 결의 때부터 이전 전까지 자산 처분이나 채무 부담을 하지 못한다(금융위 허가 시 예외)":"이전할 때 계약조건을 바꿀 수 있고 보험금을 삭감하기로 했다면 이전 전까지 자산 처분과 채무 부담이 막힙니다.","이중이득 금지: 손해보험에서는 피보험자의 이중이득을 막기 위해 실손보상 원칙이 철저히 지켜진다. 제3자의 손해배상에 앞서 보험금을 지급한 때 피보험자의 제3자에 대한 청구권은 소멸하지 않고 지급한 한도에서 보험자에게 이전된다":"손해보험은 이중이득을 막으려고 실손보상을 지키고 보험금을 먼저 줬다면 피보험자의 제삼자 청구권이 지급 한도에서 보험자에게 넘어갑니다.","인가사항: 해산의 결의·합병·보험계약 이전(제139조), 영업의 양도·양수(제150조), 상호협정의 체결·변경·폐지(제125조), 보험요율 산출기관의 설립(제176조)":"인가를 받아야 하는 사항에는 해산 결의와 합병과 보험계약 이전과 영업의 양도 양수와 상호협정과 보험요율 산출기관의 설립이 있습니다.","인보험계약의 피보험자가 신체검사를 받아야 하는 경우 낙부통지 기간은 신체검사를 받은 날부터 기산한다":"신체검사가 필요한 인보험에서는 낙부통지 기간이 청약일이 아니라 신체검사를 받은 날부터 시작됩니다.","인보험에서는 잔존물대위가 인정되지 않는다":"인보험은 사람의 생명이나 신체를 대상으로 하므로 잔존물대위가 인정되지 않습니다.","인보험에서 피보험자 등이 제3자에 대한 권리를 보험자에게 양도하는 것은 가능하다":"인보험에서도 피보험자 등이 제삼자에 대한 권리를 보험자에게 넘겨주는 것은 막지 않고 가능합니다.","인보험은 피보험이익·보험가액이 없으므로 중복보험 규정이 준용되지 않는다. 상법은 손해보험에만 피보험이익 규정을 둔다":"인보험은 피보험이익과 보험가액이 없어서 중복보험 규정을 가져다 쓰지 않으며 상법은 손해보험에만 피보험이익 규정을 둡니다.","인보험증권의 추가 기재사항: 보험계약의 종류, 피보험자의 주소·성명·생년월일, 보험수익자를 정한 때 그 주소·성명·생년월일":"인보험증권에는 보험계약의 종류와 피보험자의 주소와 성명과 생년월일을 적고 수익자를 정했다면 그 인적사항도 적습니다.","일반계정/특별계정: 동일 개인·법인 신용공여 총자산 3%/5%, 동일법인 채권·주식 합계 7%/10%, 동일차주 12%/15%, 거액 신용공여 합계 20%/20%, 대주주·자회사 신용공여 자기자본 40%(총자산 2% 한도)/2%, 대주주·자회사 채권·주식 자기자본 60%(총자산 3% 한도)/3%, 동일 자회사 신용공여 자기자본 10%/4%, 부동산 25%/15%, 외국환·외국부동산 50%/50%":"일반계정과 특별계정마다 신용공여, 채권과 주식, 부동산, 외국환에 대해 총자산이나 자기자본 대비 상한이 따로 있습니다.","임의해지: 보험사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다":"보험사고가 나기 전이라면 계약자는 이유 없이 언제든 계약의 전부나 일부를 해지할 수 있습니다.","임의해지 시 보험계약자는 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다":"계약자가 임의로 해지하면 다른 약정이 없는 한 아직 지나지 않은 기간의 보험료를 돌려 달라고 할 수 있습니다.","임차인 등 타인의 물건을 보관하는 자가 지급할 손해배상을 위해 그 물건을 보험에 붙인 경우 소유자는 보험자에게 직접 보상을 청구할 수 있다":"임차인처럼 남의 물건을 보관하는 사람이 배상에 대비해 그 물건을 보험에 붙였다면 물건 소유자가 보험자에게 직접 보상을 청구할 수 있습니다.","임차인이 임차건물을 자기 소유로 기재하여 화재보험을 체결한 경우 다른 특약이 없으면 임차인은 건물 보험금을 청구할 권리가 없다":"임차인이 빌린 건물을 자기 소유로 적어 화재보험을 들었다면 다른 특약이 없는 한 건물 보험금을 받을 권리가 없습니다.","자금지원 관련 금지: 자산운용한도를 피하기 위한 교차 주식 보유·신용공여, 자기주식 취득 제한을 피하기 위한 교차 취득 등. 위반 취득 주식은 의결권 행사 불가":"한도를 피하려는 교차 보유나 교차 취득은 금지되며 이를 어겨 취득한 주식은 의결권을 행사할 수 없습니다.","자기신체사고 자동차보험은 상해보험에 속한다":"자기신체사고 자동차보험은 운전자와 탑승자의 몸 손해를 보상하는 보험이라 상해보험으로 분류됩니다.","자동차보험은 법령에 따라 가입이 강제되지 않는 계약도 제3자 보호(보험금 지급 보장) 대상이다":"자동차보험은 법령상 가입이 강제되지 않는 계약이라도 피해자인 제삼자에게 보험금 지급을 보장하는 보호 대상에 들어갑니다.","자동차보험의 중복보험: 합계 보험금액이 손해액을 초과하면 부진정연대책임을 지고 각자 보험금액 비율로 분담한다. 분담금청구권과 보험자대위는 선택적으로 행사한다":"자동차보험이 중복되어 합계 보험금액이 손해액을 넘으면 부진정연대책임을 지고 보험금액 비율로 분담하며 분담금청구와 대위는 선택해서 행사합니다.","자동차 보험증권의 추가 기재사항: 소유자와 그 밖의 보유자의 성명·생년월일(상호), 피보험자동차의 등록번호·차대번호·차형년식·기계장치, 차량가액을 정한 때 그 가액":"자동차보험증권에는 소유자와 보유자의 인적사항과 차량의 등록번호, 차대번호, 연식 등을 추가로 적습니다.","자동차 운행 위험을 담보하는 보험은 기업보험일 수도 가계보험일 수도 있다":"자동차보험은 영업용이면 기업보험이고 개인이 쓰면 가계보험이 되어 한쪽으로 고정되지 않습니다.","자동차임대업자가 지입차주의 유상운송 제공을 허용한 것은 중요한 사실에 해당하지 않는다":"자동차임대업자가 지입차주의 유상운송을 허용한 사실은 중요한 사실로 인정되지 않았습니다.","자본감소의 공고에는 이의가 있는 보험계약자가 1개월 이상의 기간 안에 이의를 제출할 수 있다는 내용을 포함해야 한다. 자본감소는 이의를 제기한 보험계약자에게도 효력이 미친다":"자본감소 공고에는 보험계약자가 1개월 이상의 기간 안에 이의를 낼 수 있음을 담아야 하고 이의를 낸 계약자에게도 효력이 미칩니다.","자본금 10억원 이상의 범위에서 대통령령 금액(20억원). 모집 상품은 생명보험 일부, 손해보험 일부(책임·동물보험 등), 질병·상해 일부. 보험기간 2년 이내 범위에서 고시, 보험금 상한 5천만원, 연간 총보험료 상한 500억원":"소액단기전문회사는 자본금 20억원이고 보험기간 2년 이내, 보험금 5천만원 이하의 일부 상품만 취급합니다.","자본금 또는 기금: 300억원 이상. 종목 일부만 취급하면 50억원 이상의 범위에서 대통령령으로 다르게 정한다":"보험회사의 자본금이나 기금은 300억원 이상이어야 하고 일부 종목만 취급하면 50억원 이상 범위에서 대통령령으로 달리 정합니다.","자산관리업무 계약은 근로자 또는 가입자를 피보험자 또는 수익자로 하여 보험업법 제108조에 따른 특별계정 보험계약 또는 특정금전신탁계약으로 한다":"자산관리업무 계약은 근로자나 가입자를 수익자로 한 특별계정 보험계약이나 특정금전신탁계약이어야 합니다.","자산·부채 기재: 제118조에 따라 금융위원회에 제출한 서류의 내용과 다른 내용을 적지 못한다. 장래 이익배당·잉여금 분배 예상은 적지 못하되, 금융위원회가 이해를 돕기 위해 필요하다고 인정하여 정하는 경우는 예외":"자산과 부채 기재는 위원회 제출 서류와 달라선 안 되고 앞으로의 배당 예상도 쓸 수 없으며 위원회가 정한 경우만 예외입니다.","자회사 보고: 소유한 날부터 15일 이내 정관·업무의 종류 및 방법, 주주현황, 재무제표와 영업보고서, 자회사가 발행주식 총수의 100분의 10을 초과하여 소유한 회사의 현황을 제출. 사업연도 종료 후 3개월 이내 재무상태표와 재무제표·영업보고서, 자회사와의 주요 거래 상황 제출":"자회사를 갖게 되면 15일 안에 정관과 재무제표 등을 내고 사업연도 후 3개월 안에 거래 상황을 다시 보고합니다.","자회사 소유: (승인) 금융기관이 경영하는 금융업, 신용정보업·채권추심업, 보험계약 유지·해지·변경·부활 관리 업무 등. (신고) 보험업 경영과 밀접한 업무로 손해사정, 보험수리, 보험대리 등. (보고) 자산운용과 밀접한 업무는 소유한 날부터 2개월 이내. 비금융주력자가 대주주인 보험회사는 은행을 자회사로 소유할 수 없다":"자회사는 업무에 따라 승인과 신고와 보고 절차로 소유하며 비금융주력자가 대주주인 보험회사는 은행을 자회사로 가질 수 없습니다.","자회사와의 금지행위: 자산 무상 양도 또는 뚜렷하게 불리한 조건의 거래, 자회사 보유 주식을 담보로 한 신용공여와 자회사의 다른 회사 출자 지원 신용공여, 자회사 임직원 대출":"자회사에 자산을 무상 양도하거나 불리하게 거래하거나 자회사 주식을 담보로 신용을 주거나 임직원에게 대출하는 것은 금지입니다.","잔무처리자: 본점이 폐업·해산하거나 국내 보험업을 폐업하거나 허가가 취소되면 금융위원회가 필요하다고 인정하면 잔무처리자를 선임·해임할 수 있다":"본점이 폐업하거나 해산하거나 국내 허가가 취소되면 금융위원회가 필요하다고 보아 잔무처리자를 선임하거나 해임할 수 있습니다.","재무건전성 유지: 자본의 적정성, 자산의 건전성, 그 밖에 경영건전성 확보에 필요한 사항에 관한 기준을 지킨다. 위반으로 경영건전성을 해칠 우려가 있으면 금융위원회는 자본금·기금 증액명령, 위험자산 소유 제한 등을 할 수 있다":"회사는 자본의 적정성과 자산의 건전성 기준을 지켜야 하며 어기면 위원회가 증자명령이나 위험자산 제한을 할 수 있습니다.","재무제표 및 사업보고서는 일반인이 열람할 수 있도록 제출일부터 본점·지점·영업소에 비치하거나 전자문서로 제공한다":"재무제표와 사업보고서는 일반인이 볼 수 있도록 제출일부터 본점과 지점에 두거나 전자문서로 제공해야 합니다.","재무제표 제출: 매년 12월 31일에 장부를 폐쇄하고 폐쇄한 날부터 3개월 이내에 재무제표(부속명세서 포함)와 사업보고서를 금융위원회에 제출한다":"보험회사는 매년 12월 31일 장부를 폐쇄하고 3개월 안에 재무제표와 부속명세서와 사업보고서를 금융위원회에 제출해야 합니다.","재보험: 보험자가 보험사고로 인하여 부담할 책임에 대해 다른 보험자와 체결하는 계약. 원보험계약의 효력에 영향을 미치지 않는다":"재보험은 보험자가 자기 책임의 일부를 다른 보험자에게 넘기는 계약이고 원보험계약의 효력에는 영향을 주지 않습니다.","재보험계약은 손해보험계약이며 원보험계약은 생명보험계약일 수 있다":"재보험은 손해보험으로 분류되지만 그 대상이 되는 원보험은 생명보험일 수도 있습니다.","재정검증: 운용관리업무 수행 퇴직연금사업자는 매 사업연도 종료 후 6개월 이내에 적립금이 최소적립금을 넘는지 확인해 사용자에게 알린다. 적립금이 최소적립금보다 적으면 근로자대표(노조 또는 전체 근로자)에게도 알린다":"연금사업자는 사업연도가 끝나고 6개월 안에 적립금이 최소적립금을 넘는지 확인해 사용자에게 알리고 부족하면 근로자대표에게도 알립니다.","재화·용역 판매자 등이 자신이 판매·제공·중개하는 재화·용역과 관련 있는 보험상품을 모집. 영업범위는 개인·가계의 일상생활 중 위험을 보장하는 보험종목으로 금융위원회 고시":"간단보험대리점은 재화나 용역을 파는 자가 그 상품과 관련된 일상 위험 보험을 모집하는 것입니다.","적립금 부족 해소: 적립금이 최소적립금의 100분의 95에 미치지 못하면 부족분 비율의 3분의 1 이상을 직전 사업연도 종료 후 1년 이내에 해소해야 한다":"적립금이 최소적립금의 100분의 95에 못 미치면 부족분의 3분의 1 이상을 1년 안에 메워야 합니다.","적립금운용위원회를 구성하지 않거나 운용계획서를 작성하지 않은 사용자에게는 500만원 이하의 과태료":"위원회를 만들지 않거나 운용계획서를 쓰지 않으면 사용자에게 500만원 이하의 과태료가 붙습니다.","적립금의 중도인출에 관한 사항은 DB 규약에 포함되지 않는다(DC 규약에는 포함)":"적립금 중도인출은 DC 규약에만 넣는 사항이고 DB 규약의 기재사항에는 들어가지 않습니다.","적용범위: 근로자를 사용하는 모든 사업·사업장. 동거하는 친족만을 사용하는 사업 및 가구 내 고용활동에는 적용하지 않는다":"퇴직급여제도는 근로자를 쓰는 모든 사업장에 적용되지만 친족만 쓰는 사업과 가사 고용은 제외됩니다.","적을 수 없는 것: 다른 보험회사 상품과 비교한 사항, 계약자에게 유리한 내용만 골라 안내, 보험계약 내용과 다른 사항, 확정되지 않은 사항에 근거한 유리한 비교 등":"안내자료에는 타사 상품과의 비교, 유리한 내용만 고른 설명, 계약과 다른 내용, 미확정 사항을 근거로 한 비교를 쓸 수 없습니다.","적하매각: 항해도중 불가항력으로 적하를 매각하면 대금에서 운임·필요비용을 공제한 금액과 보험가액의 차액을 보상한다. 매수인이 대금을 지급하지 않으면 그 금액을 지급하고 매수인에 대한 권리를 취득한다":"항해 중 불가항력으로 화물을 팔면 매각대금에서 운임 등을 던 금액과 보험가액의 차액이 보상됩니다.","적하보험의 보험가액은 선적한 때와 곳의 적하의 가액과 선적 및 보험에 관한 비용이다":"적하보험의 보험가액은 선적한 때와 곳의 적하 가액에 선적과 보험에 든 비용을 더한 금액입니다.","적하의 일부손해: 훼손된 상태가 양륙항에 도착한 때 훼손된 상태의 가액과 훼손되지 않은 상태의 가액의 비율에 따라 보험가액의 일부 손해를 보상한다":"적하의 일부 손해는 양륙항에 도착했을 때 훼손된 상태와 온전한 상태의 가액 비율에 따라 보험가액의 일부로 보상합니다.","전문보험계약자 중 대통령령으로 정하는 자가 같은 대우를 받겠다는 의사를 서면으로 통지하면 보험회사는 정당한 사유가 없으면 동의해야 하고, 동의한 때 일반보험계약자로 본다":"전문보험계약자가 일반계약자 대우를 서면으로 요청하면 회사는 정당한 사유가 없는 한 받아들여야 합니다.","전쟁 기타 변란으로 인한 사고는 당사자 간에 다른 약정이 없으면 보험자가 보험금액을 지급할 책임이 없다":"전쟁이나 변란으로 생긴 사고는 다른 약정이 없다면 보험자가 보험금을 지급하지 않습니다.","전화 모집: 계약자의 동의를 받아 질문·설명 내용과 답변·확인을 음성녹음 등으로 확보·유지하고 지체 없이 청약서에 자필서명을 받는다. 전화로 청약 확인·정정·철회·계약 확인·해지를 하려는 경우 상대방의 동의를 받아 본인 확인 후 음성녹음 등 증거자료를 확보·유지한다":"전화 모집은 동의를 받아 설명과 답변을 녹음하고 곧바로 청약서에 자필서명을 받으며 해지 등에도 본인 확인과 녹음을 합니다.","전환 가능: 지방자치단체, 주권상장법인, 외국금융기관, 해외 증권시장 상장 국내법인 등. 국가·한국은행은 전환 대상이 아니다":"일반보험계약자로 바꿀 수 있는 전문보험계약자는 지방자치단체와 주권상장법인 등이고 국가와 한국은행은 전환 대상이 아닙니다.","정관 변경: 변경한 날부터 7일 이내에 금융위원회에 알려야 한다":"보험회사가 정관을 바꾸면 변경한 날부터 7일 안에 금융위원회에 알려야 합니다.","정당한 사유 없이 발항 또는 항해를 지연한 경우 보험자는 지체한 이후의 사고에 책임이 없다":"정당한 사유 없이 출항이나 항해를 미루었다면 보험자는 지체한 뒤에 생긴 사고에 대해 책임이 없습니다.","정신질환 면책약관은 유효하고, 음주운전 면책약관은 중과실 면책 금지(제663조·제732조의2) 때문에 무효다":"정신질환 면책약관은 유효하지만 음주운전 면책약관은 중과실 면책을 금지하는 규정에 어긋나 무효입니다.","정액보험: 사망보험·변액보험의 지급보험금은 약정액이고, 변액보험은 자산운용성과에 따라 지급보험금이 달라질 뿐 비정액보험이 아니다":"정액보험은 지급액이 미리 정해진 보험이고 변액보험도 운용성과로 액수가 달라질 뿐 정액보험에 속합니다.","정액보험형 상해보험에서 피보험자와 보험수익자가 일치하지 않는 지정도 유효하다":"정액보험 형태의 상해보험에서는 피보험자와 보험수익자가 다른 사람으로 지정되어도 유효합니다.","정차 중인 화물차에 통나무를 내려놓는 충격으로 발판이 떨어져 다른 인부가 추락한 경우는 운행 중 사고에 해당하지 않는다":"서 있는 화물차에서 통나무를 내려놓다가 발판이 떨어져 인부가 추락한 사고는 운행 중 사고에 해당하지 않습니다.","제3보험업의 보험종목: 상해보험, 질병보험, 간병보험, 그 밖에 대통령령으로 정하는 종목":"제3보험업은 사람의 몸과 건강에 관한 보험으로 상해보험과 질병보험과 간병보험과 대통령령이 정하는 종목을 다룹니다.","제3보험업의 보험종목: 상해보험, 질병보험, 간병보험, 그 밖에 대통령령으로 정하는 종목. 연금보험·퇴직보험은 생명보험, 보증보험은 손해보험이다":"제3보험업은 상해와 질병과 간병보험을 다루며 연금보험과 퇴직보험은 생명보험에 보증보험은 손해보험에 속합니다.","제3보험에 부가되는 보험(영 제15조제2항): 질병 원인 사망을 특약 형식으로 담보하며 보험만기 80세 이하, 보험금액 개인당 2억원 이내, 만기환급금은 납입보험료 합계액 범위 내":"질병사망 특약은 만기 80세 이하, 개인당 2억원 이내이고 만기환급금은 납입보험료 합계 범위 안입니다.","제3자는 피보험자가 책임을 질 사고로 입은 손해에 대해 보험금액의 한도 내에서 보험자에게 직접 보상을 청구할 수 있다. 보험자는 피보험자가 그 사고에 관해 가지는 항변으로 제3자에게 대항할 수 있다":"피해자는 보험금액 한도 안에서 보험자에게 직접 보상을 청구할 수 있고 보험자는 피보험자가 가진 항변을 피해자에게도 내세울 수 있습니다.","제3자 보험금 지급 보장: 손해보험회사는 법령상 가입이 강제되는 손해보험계약(자동차보험은 강제되지 않는 계약도 포함)으로 대통령령 계약의 제3자가 보험사고로 입은 손해에 대한 보험금 지급을 보장한다. 예금보험 대상이 아닌 법인이 계약자인 경우는 제외. 지급불능 시 즉시 손해보험협회장에게 보고하고 협회에 출연한다":"손해보험회사는 강제가입 보험의 제삼자 피해에 대한 지급을 보장하며 지급불능이 되면 손해보험협회에 보고하고 출연합니다.","제3자에 대한 보험대위(청구권대위): 손해가 제3자의 행위로 발생한 경우 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다. 일부 지급이면 피보험자의 권리를 침해하지 않는 범위에서 행사한다":"보험금을 낸 보험자는 지급액만큼 제삼자에 대한 권리를 넘겨받되 일부 지급이면 피보험자 권리를 침해하지 않게 씁니다.","제3자에 대한 보험대위 금지: 보험자는 보험사고로 생긴 보험계약자·보험수익자의 제3자에 대한 권리를 대위하여 행사하지 못한다":"인보험에서는 사고로 생긴 계약자나 수익자의 제삼자에 대한 권리를 보험자가 대위해서 행사할 수 없습니다.","제4조에 따른 허가를 받아 보험업을 경영하는 자":"보험회사는 보험업법에 따라 금융위원회의 허가를 받아 보험업을 경영하는 자를 말합니다.","제83조에 따라 모집할 수 있는 자만 할 수 있고(별도 허가 불요), 모집에 동의한 자를 대상으로 한다. 평온한 생활을 침해하는 방법은 금지":"통신수단 모집은 모집할 수 있는 자만 별도 허가 없이 할 수 있고 모집에 동의한 사람을 대상으로 하며 평온한 생활을 침해하는 방법은 금지됩니다.","제도 미설정: 퇴직급여제도나 IRP(10명 미만 특례)를 설정하지 않으면 퇴직금제도를 설정한 것으로 본다. 퇴직연금제도가 폐지·중단된 기간에도 퇴직금제도를 적용한다":"제도를 만들지 않은 사업장이나 연금제도가 멈춘 기간에는 법이 퇴직금제도를 설정한 것으로 간주합니다.","제재(제134조제1항): 금융감독원장의 건의에 따라 보험회사에 대한 주의·경고 또는 임직원에 대한 주의·경고·문책 요구, 해당 위반행위에 대한 시정명령, 임원의 해임권고·직무정지(업무집행책임자 제외), 6개월 이내의 영업 일부정지를 할 수 있다":"감독원장 건의로 위원회는 주의와 경고, 문책 요구, 시정명령, 임원 해임권고와 직무정지, 6개월 이내 영업 일부정지를 합니다.","제한 예외: 자산가격 변동 등 의사와 무관한 사유로 상태가 변동된 경우(1년 내 해소), 회계처리기준 변경(3년), 금융위원회 승인을 받은 재무건전성 기준 준수·기업구조조정 지원·계약자 이익 보호 필수 경우. 경영능력 혁신으로 자산상태가 변동된 경우는 예외 사유가 아니다":"가격 변동 같은 의사 무관 사유는 1년, 회계기준 변경은 3년 안에 해소하며 경영 혁신으로 인한 변동은 예외가 아닙니다.","조사 대상(관계자): 보험회사, 보험계약자, 피보험자, 보험금을 취득할 자, 그 밖에 보험계약에 관하여 이해관계가 있는 자":"보험조사의 대상인 관계자는 보험회사와 보험계약자와 피보험자와 보험금을 받을 자와 그 밖의 이해관계자입니다.","조사 방법: 사실과 상황에 대한 진술서 제출, 장부·서류 등 제출을 요구할 수 있다. 관계자가 조사를 방해하거나 허위 자료를 제출하거나 제출을 게을리하면 관계자가 소속된 단체의 장에게 문책 등을 요구할 수 있다(문책 요구권이 있다)":"조사 때 진술서와 장부를 요구하며 방해하거나 허위 자료를 내면 소속 단체장에게 문책을 요구할 수 있습니다.","조사 사유: 이 법 및 명령·조치를 위반한 사실이 있는 경우, 공익 또는 건전한 보험거래질서의 확립을 위하여 필요한 경우":"보험조사는 법과 명령과 조치를 위반한 사실이 있거나 공익이나 건전한 보험거래질서 확립을 위해 필요할 때 합니다.","조사정보 공표: 금융위원회는 관계자에 대한 조사실적, 처리결과, 그 밖에 위법행위 예방에 필요한 정보·자료를 공표할 수 있다":"금융위원회는 조사실적과 처리결과와 위법행위 예방에 필요한 정보를 공표할 수 있습니다.","조직변경 결과 공고: 주식회사가 상호회사로 된 경우 또는 되지 않게 된 경우 모두 7일 이내에 그 취지를 공고한다(보험계약 이전 공고 규정 준용)":"주식회사가 상호회사로 되었든 되지 않게 되었든 7일 이내에 그 취지를 공고해야 합니다.","조직변경 등기: 변경한 날부터 2주일 이내. 주식회사의 보험계약자는 조직변경에 따라 상호회사의 사원이 된다":"변경한 날부터 2주일 안에 등기하며 그때 주식회사의 보험계약자는 상호회사의 사원 지위를 얻습니다.","조치 사실 공표: 금융감독원장의 건의에 따라 제재 사실을 공표하게 할 수 있다. 퇴임한 임원·퇴직한 직원이 재직 중이었다면 받았을 조치 내용을 해당 보험회사의 장에게 통보할 수 있고, 장은 퇴임·퇴직자에게 알리고 인사기록부에 기록한다":"제재 사실은 공표할 수 있고 이미 퇴임한 임원이나 직원이 받았을 조치도 회사 대표에게 통보해 인사기록에 남깁니다.","종목별 자본금: 생명 200억, 연금(퇴직 포함) 200억, 화재 100억, 해상 150억, 자동차 200억, 보증 300억, 재보험 300억(전업), 책임 100억, 기술 50억, 권리 50억, 상해 100억, 질병 100억, 간병 100억, 그 밖 50억. 둘 이상이면 합계, 300억 이상이면 300억":"종목별 자본금은 50억원에서 300억원까지이며 여러 종목이면 합산하되 300억원을 상한으로 합니다.","주식회사는 그 조직을 변경하여 상호회사로 할 수 있다. 조직변경한 상호회사는 기금 총액을 300억원 미만으로 하거나 설정하지 않을 수 있고, 손실 보전을 위해 금융위원회가 필요하다고 인정하는 금액을 준비금으로 적립해야 한다":"조직을 상호회사로 바꾸면 기금 총액은 300억원 미만이어도 되고 손실 보전용 준비금은 반드시 쌓아야 합니다.","주식회사의 이사가 조직변경에 관한 사항을 보험계약자 총회에 보고한다":"조직변경에 관한 사항은 주식회사의 이사가 보험계약자 총회에 보고합니다.","주주총회 결의를 거치며 상법 제434조에 따라 출석 주주 의결권의 3분의 2 이상과 발행주식 총수의 3분의 1 이상으로 한다":"조직변경은 주주총회 결의로 하며 출석 주주 의결권의 3분의 2 이상과 발행주식 총수의 3분의 1 이상 찬성이 있어야 합니다.","주주총회 등의 결의 때부터 이전하거나 이전하지 않게 될 때까지 이전하려는 계약과 같은 종류의 보험계약을 체결하지 못한다. 예외로 외국지점의 국내법인 전환, 모회사가 자회사를 합병하는 경우 등":"결의 때부터 이전이 끝나거나 무산될 때까지는 이전할 계약과 같은 종류의 새 보험계약을 맺지 못하며 외국지점의 국내법인 전환 등만 예외입니다.","주택구입 등 대통령령 사유로 근로자가 요구하는 경우 사용자는 퇴직 전에 미리 정산하여 지급할 수 있다(의무가 아님). 정산 후 계속근로기간은 정산시점부터 새로 계산한다":"집 구입 같은 사유가 있으면 퇴직 전에 정산해 줄 수 있고 의무는 아니며 그 뒤 근속은 정산 시점부터 다시 셉니다.","준수사항: 대출 등을 받는 자에게 보험계약을 체결하지 않아도 대출에 영향이 없음을 알림, 금융기관이 보험대리점·중개사이며 지급책임은 보험회사에 있음을 알림, 보험 모집 장소와 대출 취급 장소를 분리, 본점에 보험민원 전담창구 설치":"대출 때 가입 여부가 대출에 무관함을 알리고 모집 장소를 대출 장소와 나누며 본점에 민원 전담창구를 둡니다.","준수사항: 재화·용역 판매·제공·중개를 조건으로 보험가입을 강요하지 않을 것, 재화·용역과 별도로 보험계약 체결·취소 기회를 보장할 것, 재화·용역과 보험을 동시에 체결할 때와 보험만 체결할 때 보험료·지급조건에 차이가 없도록 할 것":"간단대리점은 판매를 조건으로 가입을 강요하지 못하고 체결과 취소 기회를 따로 주며 보험료와 조건에 차이를 두지 않습니다.","준용: 국내사무소·보험대리점·보험중개사에는 제131조제1항, 제133조, 제134조를 준용한다. 보험업과 밀접한 업무를 하는 자회사·수탁자에는 제133조를 준용한다. 보험계리업자·손해사정업자에는 제131조제1항·제133조·제134조제1항을 준용한다":"사무소, 대리점, 중개사에는 명령과 검사와 제재 규정을, 자회사와 수탁자에는 검사 규정을 각각 같은 방식으로 적용합니다.","중간정산 사유(영 제3조): (1) 무주택자인 근로자가 본인 명의 주택 구입, (2) 무주택자가 전세금·임차보증금 부담(한 사업 근로 중 1회), (3) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 질병·부상 의료비를 본인 연간 임금총액의 1천분의 125 초과하여 부담, (4) 신청일부터 거꾸로 5년 이내 파산선고, (5) 5년 이내 개인회생절차개시 결정, (6) 정년 연장·보장 조건으로 일정 나이·근속시점·임금액을 기준으로 임금을 줄이는 제도 시행, (6의2) 합의에 따라 소정근로시간을 1일 1시간 또는 1주 5시간 이상 단축해 3개월 이상 계속 근로, (6의3) 근로기준법 개정에 따른 근로시간 단축으로 퇴직금 감소, (7) 재난 피해(고시 사유)":"중간정산은 무주택자의 집 구입과 전세금, 의료비, 파산, 개인회생, 임금피크제, 근로시간 단축, 재난 때 허용됩니다.","중간정산 사유 증명서류는 근로자가 퇴직한 후 5년이 되는 날까지 사용자가 보존한다":"중간정산을 허용한 근거 서류는 근로자가 퇴직하고 5년이 되는 날까지 사용자가 보관해야 합니다.","중과실: 통상인에게 요구되는 정도의 상당한 주의를 하지 않더라도 약간의 주의를 하면 손쉽게 위법·유해한 결과를 예견할 수 있음에도 간과한 경우로 고의에 가까운 현저한 주의 결여 상태. 위조 면허증 복사본만 보고 원본·주민등록증을 확인하지 않은 대여업자는 중과실이다":"중과실은 약간만 주의해도 결과를 예견할 수 있었는데 놓친 고의에 가까운 주의 결여이며 위조 면허증 사본만 본 대여업자가 그 예입니다.","중도인출 사유(영 제14조): (1) 무주택자인 가입자가 본인 명의 주택 구입, (2) 무주택자인 가입자가 전세금·임차보증금 부담(한 사업 근로 중 1회), (3) 재난 피해(고시), (4) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 의료비를 본인 연간 임금총액의 1천분의 125 초과하여 부담, (5) 신청일부터 거꾸로 5년 이내 파산선고, (6) 5년 이내 개인회생절차개시 결정, (7) 급여를 받을 권리를 담보로 대출받은 가입자의 대출 원리금 상환(고시 사유, 상환에 필요한 금액 이하)":"DC 중도인출 사유는 집 구입, 전세금, 재난, 큰 의료비, 파산, 개인회생, 담보대출 원리금 상환 일곱 가지입니다.","중도인출 사유가 아닌 것: 사업주의 휴업 실시로 임금이 감소한 경우(담보 제공 사유일 뿐 중도인출 사유는 아님), 본인의 대학등록금·혼례비·장례비 부담(담보 제공 사유일 뿐 중도인출 사유는 아님)":"휴업으로 임금이 줄었거나 대학등록금, 혼례비, 장례비를 낼 때는 담보 제공은 되지만 중도인출 사유는 되지 못합니다.","중복계약 체결 확인의무: 실손의료보험계약(실제 부담한 의료비만 지급하는 제3보험상품)과 기타손해보험계약을 모집하기 전에 계약자가 되려는 자의 동의를 얻어 동일 위험 보장 계약 체결 여부를 확인하고 즉시 알려야 한다. 국외체류 중 위험, 일부 여행보험은 제외":"실손의료보험 등을 모집하기 전에 계약자가 되려는 자의 동의를 얻어 같은 위험을 보장하는 계약이 있는지 확인하고 곧바로 알려야 합니다.","중복보험의 통지: 보험계약자는 각 보험자에게 각 보험계약의 내용을 통지해야 한다. 사기로 체결된 경우 무효이고 보험자는 안 때까지의 보험료를 청구할 수 있다(체결순서 무관)":"중복보험은 계약자가 각 보험자에게 알려야 하고 사기로 체결하면 무효이며 보험자는 안 때까지의 보험료를 받습니다.","중복보험자 1인이 정당한 보험금을 단독 지급하면 다른 보험자에게 각자의 보험금액 비율에 따른 분담금을 청구할 수 있다. 보험자대위와 분담금청구는 선택적으로 행사할 수 있다":"보험자 한 사람이 정당하게 보험금을 혼자 지급했다면 다른 보험자에게 각자의 보험금액 비율에 따른 분담금을 청구할 수 있습니다.","중소기업의 사용자는 공단이 작성해 고용노동부장관의 승인을 받은 중소기업퇴직연금기금표준계약서의 사항에 관해 근로자대표의 동의를 얻거나 의견을 들어 공단과 계약을 체결함으로써 설정한다(개별 근로자 동의·신고 방식이 아님)":"중소기업 사용자는 공단 표준계약서에 대해 근로자대표 동의나 의견청취를 거쳐 공단과 계약해 설정하며 개별 동의나 신고 방식은 아닙니다.","중소기업퇴직연금기금제도: 상시 100명 미만의 근로자를 사용하는 중소기업의 둘 이상 사용자·근로자가 납입한 부담금 등으로 공동의 기금을 조성·운영하여 급여를 지급하는 제도":"중소기업퇴직연금기금제도는 상시 100명 미만 사업장들이 돈을 모아 공동 기금으로 굴려 급여를 주는 제도입니다.","중소기업퇴직연금기금제도는 근로복지공단이 운영한다. 중소기업퇴직연금기금제도운영위원회를 둔다(위원장은 공단 이사장, 위원 10명 이상 15명 이내, 근로자 대표와 사용자 대표 위원 수는 같아야 함, 위촉위원 임기 3년)":"근로복지공단이 운영하는 중소기업기금제도에는 운영위원회가 있고 위원장은 이사장이며 노사 대표 위원 수가 같고 임기는 3년입니다.","중요한 사항: 객관적으로 보험자가 그 사실을 안다면 계약을 체결하지 않거나 적어도 동일한 조건으로는 체결하지 않았으리라고 평가되는 사항":"중요한 사항은 보험자가 알았다면 계약하지 않거나 같은 조건으로는 하지 않았으리라고 객관적으로 평가되는 사항입니다.","즉시 공시사항: 재무 및 손익, 자금의 조달 및 운용, 재무건전성 기준 미준수 등으로 받은 조치 내용, 보험약관·사업방법서·보험료·해약환급금·공시이율 등 비교자료, 그 밖에 고시 사항":"즉시 공시해야 하는 사항에는 재무와 손익과 자금 운용과 받은 조치 내용과 약관과 보험료와 해약환급금과 공시이율 같은 비교자료가 있습니다.","증권에 관한 이의약관: 증권 교부일부터 일정 기간 내에 증권 내용의 정부에 관한 이의를 제기할 수 있음을 약정할 수 있다. 그 기간은 1월을 내리지 못한다":"증권 내용이 맞는지 이의를 제기할 기간을 약정할 수 있지만 그 기간은 교부일부터 1월보다 짧을 수 없습니다.","증권을 멸실·현저히 훼손한 때 보험계약자는 재교부를 청구할 수 있고, 증권작성 비용은 보험계약자가 부담한다":"증권을 잃어버리거나 심하게 훼손하면 재교부를 청구할 수 있고 그 작성 비용은 보험계약자가 부담합니다.","지급되는 보험금은 약정 보험금액이 아무리 커도 보험가액을 초과할 수 없다":"약정한 보험금액이 아무리 커도 실제로 지급하는 보험금은 보험가액을 넘을 수 없습니다.","지정·변경의 의사표시가 보험자에게 도달하지 않아도 변경의 효력이 즉시 생긴다. 다만 계약 체결 후 지정·변경은 보험자에게 통지하지 않으면 보험자에게 대항하지 못한다":"수익자 변경은 보험자에게 도달하지 않아도 곧바로 효력이 생기지만 계약 후의 변경은 보험자에게 통지하지 않으면 보험자에게 맞설 수 없습니다.","직원이 배우자의 동의 없이 동료로 하여금 대신 서명하게 하여 체결한 생명보험은 타인의 생명보험이고 서면동의가 없어 무효다":"직원이 배우자의 동의 없이 동료에게 대신 서명시켜 맺은 생명보험은 타인의 생명보험인데 서면동의가 없어 무효입니다.","직접 수행 시 준수: 손해사정사를 고용해 담당하게 할 것, 고용한 손해사정사 평가기준에 보험금 삭감을 유도하는 지표를 사용하지 않을 것, 손해사정서 작성 시 지체 없이 계약자 등에게 내어 주고 중요한 내용을 알릴 것":"직접 손해사정을 하는 회사는 손해사정사를 고용하고 평가에서 보험금 삭감 유도 지표를 쓰지 않으며 서류를 지체 없이 계약자에게 줍니다.","직접청구권(제724조제2항)은 강행규정이므로 이를 부인하거나 행사를 어렵게 하는 약관은 무효다":"직접청구권은 당사자가 바꿀 수 없는 강행규정이라서 이를 부인하거나 행사를 어렵게 만드는 약관은 무효입니다.","직접청구권은 보험계약을 전제로 하므로 보험계약상 책임한도액 범위 내에서 인정된다. 약관의 보험금 지급기준은 책임한도액이 아니라 지급기준에 불과하면 제3자에게 대항할 수 없다":"직접청구권은 보험계약을 전제로 하므로 계약상 책임한도액 안에서 인정되며 약관의 지급기준이 한도액이 아니라면 피해자에게 맞설 수 없습니다.","직접청구권은 피해자의 피보험자에 대한 손해배상청구권을 전제로 하므로 부종성이 있고 보험자는 책임관계상 항변을 원용할 수 있다":"직접청구권은 피해자의 배상청구권에 딸려 있으므로 보험자는 그 책임관계에서 생기는 항변을 내세울 수 있습니다.","직접청구권의 소멸시효: 민법 제766조에 따라 피해자 또는 법정대리인이 손해 및 가해자를 안 날부터 3년이다. 시효기산점인 안 날은 현실적·구체적으로 인식한 때다":"직접청구권은 민법에 따라 피해자가 손해와 가해자를 안 날부터 3년이면 시효가 끝나고 안 날은 현실적이고 구체적으로 인식한 때입니다.","직접청구권의 준거법: 영국법이 준거법인 책임보험의 피보험자에 대해 우리 법률에 따른 손해배상청구권을 가진 제3자의 직접청구권은 영국법에 따른다":"영국법을 준거법으로 한 책임보험에서 우리 법에 따른 배상청구권을 가진 피해자의 직접청구권은 영국법을 따릅니다.","질병보험자의 책임: 피보험자의 질병에 관한 보험사고가 발생하면 보험금이나 그 밖의 급여를 지급한다. 질병보험은 성질에 반하지 않는 범위에서 생명보험·상해보험 규정을 준용한다":"질병보험의 보험자는 질병 사고 때 보험금이나 급여를 주며 성질이 허락하는 범위에서 생명보험과 상해보험 규정을 따릅니다.","집합된 물건의 일부가 보험기간 중 수시로 교체되어도 보험사고 발생 시에 현존한 물건은 보험의 목적에 포함된다":"보험기간 중 집합된 물건의 일부가 수시로 바뀌어도 사고가 났을 때 있던 물건은 보험의 목적에 들어갑니다.","집합보험: 집합된 물건을 일괄하여 보험의 목적으로 한 때 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함되고, 그 가족·사용인을 위해서도 체결한 것으로 본다":"집합된 물건을 한꺼번에 보험의 목적으로 하면 피보험자의 가족과 사용인의 물건도 포함되고 그들을 위해서도 계약한 것으로 봅니다.","집합보험(제686조): 집합된 물건을 일괄하여 보험의 목적으로 한 때 피보험자의 가족·사용인의 물건도 포함하며, 가족·사용인을 위해서도 체결한 것으로 본다(추정이 아니라 간주)":"집합보험은 가족과 사용인의 물건도 포함하고 그들을 위해서도 체결한 것으로 보며 이는 추정이 아니라 간주입니다.","차량 소유자의 관리 과실과 무단운전자의 과실이 경합한 사고에서 소유자의 보험자가 무단운전자 부담부분까지 배상하면 그 부담 비율에 따라 무단운전자에게 구상할 수 있다":"소유자와 무단운전자의 과실이 겹친 사고에서 소유자의 보험자가 운전자 몫까지 배상했다면 그 비율에 따라 운전자에게 구상할 수 있습니다.","창고보험처럼 물건의 수시 교체가 이뤄지는 총괄보험도 사고 시 현존 물건이 객체로 확정되어야 한다":"물건이 수시로 바뀌는 창고보험 같은 총괄보험도 사고가 났을 때 있던 물건이 보험의 대상으로 정해져야 합니다.","창립총회: 발기인은 기금의 납입이 끝나고 사원 수가 예정된 수가 되면 그날부터 7일 이내에 소집해야 한다. 사원 과반수 출석과 의결권의 4분의 3 이상 찬성으로 결의한다":"발기인은 기금 납입이 끝나고 사원 수가 채워진 날부터 7일 안에 창립총회를 소집하며 과반수 출석과 4분의 3 이상 찬성으로 결의합니다.","책임보험은 재보험에도 성질에 반하지 않는 범위에서 준용한다":"책임보험의 규정은 재보험에도 성질에 어긋나지 않는 범위에서 가져와 적용합니다.","책임보험의 방어비용: 피보험자가 제3자의 청구를 방어하기 위해 지출한 재판상·재판외의 필요비용은 보험의 목적에 포함된다":"책임보험에서 피보험자가 제삼자의 청구를 막으려고 쓴 재판상과 재판 외의 필요한 비용도 보험의 목적에 포함됩니다.","책임보험의 보험금청구권은 피보험자의 배상책임이 변제·승인·화해·재판으로 확정되어 행사할 수 있는 때부터 소멸시효가 진행한다":"책임보험은 배상책임이 확정되어 청구가 가능해진 시점에 소멸시효가 시작됩니다.","책임보험의 중복: 피보험자가 동일 사고로 제3자에게 배상책임을 지는 수개의 책임보험 보험금액 총액이 손해배상액을 초과하면 제672조·제673조를 준용한다":"한 사고로 지는 배상책임에 여러 책임보험이 있고 보험금액 합계가 배상액을 넘으면 중복보험 규정을 준용합니다.","책임준비금·비상위험준비금: 결산기마다 계상하고 따로 작성한 장부에 기재. 대통령령에 따라 책임준비금의 적정성 검증을 받아야 하는 보험회사가 있다":"책임준비금과 비상위험준비금은 결산기마다 계상해 따로 만든 장부에 적으며 일부 보험회사는 책임준비금의 적정성 검증을 받아야 합니다.","청구권대위 금지 특약: 보험모집 종사자가 제3자에 대한 청구권대위 행사의 포기를 약속하는 것은 특별이익 제공으로 금지된다":"보험모집 종사자가 제삼자에 대한 청구권대위를 포기하겠다고 약속하는 것은 특별이익 제공으로 금지됩니다.","청구권대위의 제3자: 타인을 위한 보험의 보험계약자도 포함되고, 불법행위뿐 아니라 채무불이행 책임자도 포함된다. 제3자가 가입한 책임보험의 피해자 직접청구권도 대위 대상이다":"청구권대위의 제삼자에는 타인을 위한 보험의 계약자도 들고 불법행위자뿐 아니라 채무불이행 책임자도 포함되며 피해자의 직접청구권도 대위 대상입니다.","청산인은 일반채무 변제, 사원의 보험금액·환급금 지급, 기금 상각 순으로 자산을 처분한다":"상호회사의 청산인은 일반채무를 먼저 갚고 사원의 보험금과 환급금을 준 뒤 기금을 상각하는 순서로 자산을 처분합니다.","청약과 승낙의 합의만으로 성립하는 불요식 낙성계약이다":"보험계약은 청약과 승낙이 맞으면 서류 없이도 성립하는 낙성계약이고 특별한 방식도 요구하지 않습니다.","청약과 함께 보험료 상당액을 받은 경우 승낙 전에 보험사고가 생기면, 청약을 거절할 사유가 없는 한 보험자는 보험계약상 책임을 진다":"청약과 함께 보험료를 받았다면 승낙 전에 사고가 나도 거절할 사유가 없는 한 보험자가 보험금을 지급해야 합니다.","청약을 거절할 사유가 있다는 점은 보험자가 증명한다":"승낙 전 사고에서 청약을 거절할 사유가 있었다는 사실은 책임을 피하려는 보험자가 증명해야 합니다.","청약을 철회하면 청약이 소멸하므로 보험자는 낙부통지의무를 지지 않는다":"청약자가 청약을 거둬들이면 청약 자체가 사라져 보험자가 승낙 여부를 알릴 의무도 없어집니다.","청약 이후 보험료를 전혀 지급하지 않은 경우 손해보험자는 다른 약정이 없으면 낙부통지의무가 없다":"청약 후 보험료를 전혀 받지 못했다면 손해보험자는 다른 약정이 없는 한 낙부통지를 할 의무가 없습니다.","초과보험의 가액은 계약당시의 가액으로 정한다. 보험가액이 보험기간 중 현저하게 감소된 때도 감액을 청구할 수 있다":"초과보험인지는 계약 당시의 가액으로 따지며 보험기간 중 가액이 현저히 줄어든 경우에도 감액을 청구할 수 있습니다.","초과 적립금: 적립금이 기준책임준비금을 초과하면 향후 부담금에서 상계할 수 있고, 기준책임준비금의 100분의 150을 초과하고 사용자가 반환을 요구하면 퇴직연금사업자는 초과분을 사용자에게 반환할 수 있다":"적립금이 필요액을 넘으면 앞으로의 부담금에서 빼 줄 수 있고 100분의 150을 넘는 초과분은 사용자 요구로 돌려줄 수 있습니다.","총괄(floating)보험은 보험가액을 정하지 않는 것이 일반적이다":"총괄보험은 대상 물건이 계속 바뀌므로 보험가액을 미리 정하지 않는 것이 보통입니다.","총회는 정관 변경 등 상호회사 조직에 필요한 사항을 결의하며, 조직변경을 위한 주주총회 결의를 변경할 수 있다. 다만 주식회사 채권자의 이익을 해치지 못하고, 주주에게 손해를 입히면 주주총회 동의를 받아야 한다":"총회는 정관 변경 등을 정하되 주식회사 채권자의 이익은 침해하지 못하고 주주에게 불리하면 동의가 필요합니다.","총회 대행기관: 주식회사는 조직변경 결의 시 보험계약자 총회를 갈음하는 기관에 관한 사항을 정할 수 있고, 그 구성방법을 공고 내용에 포함한다":"주식회사는 조직변경을 결의하면서 보험계약자 총회를 대신하는 기관을 정할 수 있고 그 구성 방법을 공고에 포함해야 합니다.","총회소집청구: 100분의 5 이상의 사원(정관으로 다른 기준 가능)":"사원의 100분의 5 이상은 총회 소집을 청구할 수 있고 정관으로 다른 기준을 정할 수 있습니다.","최소적립금: 매 사업연도 말 기준책임준비금(예상 비용 기준액과 가입기간 급여비용 중 큰 금액)에 100분의 60 이상으로 대통령령이 정하는 비율(100분의 80 이상, 고용노동부령)을 곱한 금액 이상을 적립금으로 적립한다":"최소적립금은 사업연도 말 기준책임준비금에 법령이 정한 비율(100분의 80 이상)을 곱한 금액 이상을 적립한다는 뜻입니다.","최초(제1회) 보험료: 계약체결 후 지체없이 지급해야 하며, 지급하지 않으면 다른 약정이 없는 한 계약성립 후 2월이 경과한 때 계약이 해제된 것으로 본다":"첫 보험료는 계약 후 곧바로 내야 하며 내지 않으면 다른 약정이 없는 한 계약 성립 후 2월이 지난 때 해제된 것으로 봅니다.","추운 겨울 승용차 시동을 켜놓고 자다가 뒷좌석 부근에서 발화된 화재로 사망한 사고는 운행 중 사고가 아니다":"승용차 시동을 켜 놓고 자다가 뒷좌석 부근에서 불이 나 사망한 사고는 차를 운행하다 난 사고가 아니라고 판단했습니다.","타인은 당연히 계약의 이익을 받는다. 손해보험에서 보험계약자가 타인에게 손해를 배상한 때는 타인의 권리를 해하지 않는 범위에서 보험금을 청구할 수 있다":"타인은 계약의 이익을 당연히 받으며 손해보험의 계약자가 타인에게 배상했다면 타인의 권리를 해치지 않는 범위에서 보험금을 청구할 수 있습니다.","타인을 위한 보증보험에서 피보험자와 보험자가 보험금 지급기한을 유예하기로 한 합의는 보험계약자 또는 구상금채무 연대보증인의 동의가 없어도 효력이 있다":"보증보험에서 지급 시기를 미루자는 피보험자와 보험자의 합의는 계약자나 연대보증인이 몰라도 유효합니다.","타인을 위한 보험에서 보험계약자가 파산선고를 받거나 보험료 지급을 지체한 때 타인은 그 권리를 포기하지 않는 한 보험료를 지급할 의무가 있다":"타인을 위한 보험에서 계약자가 파산하거나 보험료를 지체하면 타인이 권리를 포기하지 않는 한 보험료를 낼 의무가 있습니다.","타인을 위한 보험의 임의해지: 보험계약자가 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다(둘 중 하나를 갖추면 가능)":"타인을 위한 보험의 임의해지는 계약자가 타인의 동의를 얻거나 보험증권을 갖고 있어야 가능하고 둘 중 하나만 갖춰도 됩니다.","타인을 위한 생명보험에서 보험수익자는 원칙적으로 보험료 지급의무가 없으나, 계약자가 파산하거나 보험료 지급을 지체하면 수익자가 권리를 포기하지 않는 한 지급 의무가 있다":"타인을 위한 생명보험의 수익자는 원칙적으로 보험료를 내지 않으나 계약자가 파산하거나 지체하면 권리를 포기하지 않는 한 낼 의무가 있습니다.","타인을 위한 채무보증 금지: 타인을 위해 소유자산을 담보로 제공하거나 채무보증을 할 수 없다. 예외는 이 법·대통령령":"보험회사는 타인을 위해 자기 자산을 담보로 제공하거나 채무를 보증할 수 없고 법과 대통령령이 정한 예외만 허용됩니다.","타인의 사망을 보험사고로 하는 보험계약은 체결 시에 그 타인의 서면(요건을 갖춘 전자서명 전자문서 포함)에 의한 동의를 얻어야 한다. 강행규정이며 위반하면 무효다":"타인의 사망을 보험사고로 하는 계약은 체결 때 그 타인의 서면동의가 필요하고 전자서명으로도 할 수 있으며 강행규정이라 위반하면 무효입니다.","타인의 사망을 보험사고로 하는 보험계약은 체결 시에 그 타인의 서면 동의를 얻어야 한다. 이를 위반한 계약은 무효이고, 무효를 스스로 주장해도 신의칙 위반이 아니다":"타인의 사망을 보험사고로 하는 계약은 체결 때 그 타인의 서면동의가 있어야 하며 없으면 무효이고 그 무효를 주장해도 신의칙 위반이 아닙니다.","통신판매전문보험회사: 총보험계약건수·수입보험료의 100분의 90 이상을 통신수단으로 모집하는 보험회사로 자본금이 제1항 금액의 3분의 2":"통신판매전문회사는 계약 건수와 보험료의 100분의 90 이상을 통신으로 모집하며 자본금은 3분의 2로 줄어듭니다.","통지를 받은 보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다":"위험 증가 통지를 받은 보험자는 1월 안에 보험료를 올려 달라고 하거나 계약을 해지할 수 있습니다.","통지의무자는 보험계약자 또는 피보험자다. 보험수익자는 통지의무자가 아니다. 한 사람이라도 통지하면 의무를 이행한 것이다":"통지의무자는 계약자와 피보험자이고 수익자는 포함되지 않으며 그중 한 사람만 통지해도 의무를 다한 것입니다.","퇴사한 사원의 환급: 퇴사한 날이 속하는 사업연도 종료일부터 3개월 이내. 환급청구권은 그 기간이 지난 후 2년 동안 행사하지 않으면 시효로 소멸한다":"퇴사한 사원에게는 사업연도 종료일부터 3개월 안에 환급하고 그 기간이 지나 2년 동안 청구하지 않으면 환급청구권이 시효로 소멸합니다.","퇴직금 소멸시효: 퇴직금을 받을 권리는 3년간 행사하지 않으면 시효로 소멸한다":"퇴직금을 달라고 할 권리는 3년 동안 행사하지 않으면 시효가 지나 사라집니다.","퇴직금의 개인형퇴직연금제도 계정 이전: 근로자가 지정한 IRP 계정 또는 기금제도가입자부담금계정으로 이전하는 방법으로 지급. 미지정 시 근로자 명의 IRP 계정으로 이전":"퇴직금은 근로자가 지정한 IRP 계좌로 보내는 것이 원칙이고 지정이 없으면 근로자 이름의 IRP 계좌로 이전합니다.","퇴직금의 법적 성격: 후불임금, 사회보장적 급여, 공로보상의 성격을 아울러 가진다":"퇴직금은 미뤄 둔 임금이면서 사회보장 급여이자 오래 일한 데 대한 보상이라는 성격을 함께 지닙니다.","퇴직금 지급: 지급사유가 발생한 날부터 14일 이내. 특별한 사정이 있으면 당사자 합의로 연장":"퇴직금은 지급사유가 생기고 14일 안에 주어야 하며 당사자가 합의하면 그 기한을 늘릴 수 있습니다.","퇴직급여 감소 예방: DB 또는 퇴직금제도를 설정한 사용자가 정년 연장·보장 조건 임금조정, 소정근로시간 단축(1일 1시간 또는 주 5시간 이상, 3개월 이상 계속 근로), 근로기준법 개정에 따른 근로시간 단축으로 임금이 감소하는 경우 등에는 퇴직급여가 감소할 수 있음을 미리 알리고 근로자대표와 협의해 DC·중소기업기금 전환 등 조치를 해야 한다":"정년 연장이나 근로시간 단축으로 임금이 줄 수 있으면 퇴직급여 감소 가능성을 알리고 근로자대표와 협의해 DC 전환 등을 해야 합니다.","퇴직급여등 계산: 퇴직금·DB 급여는 계속근로기간 1년에 대하여 30일분의 평균임금. DC·중소기업기금·IRP 부담금은 가입자의 연간 임금총액의 12분의 1":"퇴직금과 DB급여는 근속 1년당 평균임금 30일분으로, DC와 IRP 부담금은 연간 임금총액의 12분의 1로 셉니다.","퇴직급여제도: 확정급여형퇴직연금제도, 확정기여형퇴직연금제도, 중소기업퇴직연금기금제도, 퇴직금제도":"퇴직급여제도에는 확정급여형과 확정기여형, 중소기업기금제도, 그리고 일반 퇴직금제도가 모두 들어갑니다.","퇴직급여제도를 설정하거나 다른 종류로 변경하려면 근로자대표(과반수 노조 또는 근로자 과반수)의 동의를 받는다. 설정된 제도의 내용 변경은 의견을 듣고, 근로자에게 불리하면 동의를 받는다":"제도를 새로 만들거나 종류를 바꿀 때는 근로자대표 동의가 필요하고 내용 변경은 의견을 듣되 불리하면 동의를 받습니다.","퇴직급여제도 설정의무: 사용자는 퇴직급여제도 중 하나 이상을 설정해야 한다. 계속근로기간이 1년 미만인 근로자, 4주간을 평균하여 1주간의 소정근로시간이 15시간 미만인 근로자는 제외. 이 제외는 헌법상 근로조건 법정주의·평등원칙에 위반되지 않는다":"사용자는 퇴직급여제도 중 하나를 반드시 만들어야 하나 근속 1년 미만이거나 주 15시간 미만 근로자는 빠지며 이는 합헌입니다.","퇴직 등 사유가 발생한 때 미납 부담금이 있으면 사유 발생일부터 14일 이내에 부담금과 지연이자를 해당 가입자의 DC 계정에 납입한다. 당사자 합의로 연장 가능":"퇴직 등 사유가 생겼는데 미납이 있으면 14일 안에 부담금과 지연이자를 가입자 계정에 넣어야 하고 합의로 늘릴 수 있습니다.","퇴직연금사업자가 되려는 자는 재무건전성 및 인적·물적 요건을 갖춰 고용노동부장관에게 등록한다. 대상: 투자매매업자·투자중개업자·집합투자업자, 보험회사, 은행, 신용협동조합중앙회, 새마을금고중앙회, 근로복지공단(상시 30명 이하 사업), 신탁업 인가를 받은 자":"퇴직연금사업자는 재무건전성과 인적, 물적 요건을 갖춰 고용노동부장관에게 등록하며 증권사, 보험사, 은행 등이 대상입니다.","퇴직연금사업자가 운영할 수 있다. 설정할 수 있는 사람: 퇴직급여제도의 일시금을 수령한 사람, DB·DC·중소기업퇴직연금기금제도 가입자로서 자기 부담으로 추가 설정하려는 사람, 자영업자 등 안정적인 노후소득 확보가 필요한 사람":"IRP는 퇴직연금사업자가 운영하며 일시금 수령자, DB·DC 가입자의 추가 가입, 자영업자 등이 만들 수 있습니다.","퇴직연금사업자는 모집인이 모집업무를 수행하며 사용자·가입자에게 손해를 끼친 경우 민법 제756조에 따라 배상책임을 진다. 모집인 등록취소 또는 6개월 이내 모집업무 정지는 고용노동부장관이 한다":"모집인이 일하다 사용자나 가입자에게 손해를 끼치면 사업자가 민법 제756조에 따라 배상하며 등록취소나 정지는 장관이 합니다.","퇴직연금사업자의 정당한 사유 없는 금지행위: 운용관리·자산관리 계약 체결 거부, 특정 사업자와 계약 체결 강요, 사용자·가입자 이익 침해 행위(특정 운용방법 선택 강요, 확정되지 않은 수익 제시, 통상 조건을 벗어난 현저히 유리한 조건 제시, 사전지정운용방법에서 특정 가입자 우대 등). 적립금 운영현황을 공개하는 것은 금지행위가 아니다":"사업자는 정당한 이유 없이 계약을 거부하거나 특정 사업자를 강요하거나 확정 안 된 수익을 제시하면 안 되며 운영현황 공개는 허용됩니다.","퇴직연금제도(중소기업퇴직연금기금제도 포함)의 급여를 받을 권리는 양도 또는 압류하거나 담보로 제공할 수 없다. 반액에 한정한 것이 아니다":"연금제도의 급여를 받을 권리는 팔거나 압류하거나 담보로 잡힐 수 없으며 그 금지는 절반만이 아니라 전부에 미칩니다.","퇴직연금제도: 확정급여형, 확정기여형, 개인형퇴직연금제도":"퇴직연금제도는 퇴직급여제도 가운데 연금 방식인 DB형과 DC형, 그리고 개인이 가입하는 IRP를 가리킵니다.","퇴직연금제도 모집인: 퇴직연금사업자는 요건(임직원이 아님, 서면 계약, 교육과정 이수, 등록취소 후 3년 경과)을 갖춘 자에게 모집업무를 위탁하고 위탁받은 자를 고용노동부장관에게 등록한다. 등록하지 않은 모집인에게 위탁하면 안 된다":"연금사업자는 임직원이 아닌 일정 요건의 모집인에게 모집업무를 맡기고 장관에게 등록해야 하며 미등록 모집인에게 맡기면 안 됩니다.","퇴직연금제도 설정 사용자는 자기 또는 제3자의 이익을 도모할 목적으로 운용관리·자산관리업무 계약을 체결해서는 안 된다. DB·DC 설정 사용자는 매년 1회 이상 가입자 교육을 한다":"연금제도를 둔 사용자는 자기나 제삼자의 이익을 위한 계약을 맺으면 안 되고 DB와 DC 가입자에게 해마다 교육을 해야 합니다.","퇴직연금제도 폐지: 폐지일부터 1개월 이내 폐지신고서 제출, 가입자에게 통지, 14일 이내에 미납 부담금을 납입하고 퇴직연금사업자가 급여를 지급하게 해야 한다. 급여를 받은 가입자는 중간정산을 받은 것으로 본다":"연금제도를 없앨 때는 1개월 안에 신고하고 가입자에게 알리며 14일 안에 미납분을 내고 급여를 주게 하며 중간정산으로 봅니다.","특례 IRP 급여 수급요건은 법 제17조제1항과 같다(연금 55세 이상·가입기간 10년 이상·지급기간 5년 이상)":"특례 IRP의 급여 요건은 법 제17조제1항과 같아서 55세 이상, 가입 10년 이상, 5년 이상 지급입니다.","특례 준수사항: 사업자 선정 시 개별 근로자의 동의(근로자가 요구하면 스스로 선정), 사용자는 가입자별 연간 임금총액의 12분의 1 이상의 부담금을 현금으로 IRP 계정에 납입, 가입자 추가 부담금 납입 가능, 매년 1회 이상 정기 납입, 퇴직 등 사유 발생 시 14일 이내 미납 부담금과 지연이자 납입":"특례에서는 근로자 동의로 사업자를 고르고 연간 임금총액의 12분의 1 이상을 현금으로 해마다 내며 미납분은 14일 안에 냅니다.","특별계정: 연금저축계좌 계약, 퇴직보험계약(근퇴법 제29조제2항), 변액보험계약, 금융위원회가 필요하다고 인정하는 계약. 다른 계정과 구분하여 회계처리하며 이익을 계정상 계약자에게 분배할 수 있다":"특별계정은 연금저축계좌와 퇴직보험과 변액보험 등을 다른 계정과 구분해 회계처리하는 것이며 그 이익을 해당 계정의 계약자에게 분배할 수 있습니다.","특별비용: 보험의 목적의 안전·보존을 위해 지급할 특별비용은 보험금액의 한도 내에서 보상한다":"보험의 목적을 안전하게 보존하려고 쓴 특별비용은 보험금액 한도 안에서 보상합니다.","특별이익 제공 금지: 금품(최초 1년 납입 보험료의 100분의 10과 3만원 중 적은 금액 이하는 제외, 위험을 감소시키는 물품은 20만원), 기초서류에서 정한 사유에 근거하지 않은 보험료 할인·수수료 지급, 기초서류보다 많은 보험금 약속, 보험료·대출이자·수표 이자의 대납, 상법 제682조 청구권 대위행사 포기":"특별이익 제공 금지에는 일정 한도 초과 금품, 기초서류 밖 할인, 과다한 보험금 약속, 보험료 대납, 대위권 포기가 있습니다.","특별한 위험을 예기하여 보험료를 정한 경우 보험기간 중 그 위험이 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다":"특별한 위험을 예상해 보험료를 정했는데 기간 중 그 위험이 사라지면 계약자는 그 뒤의 보험료 감액을 청구할 수 있습니다.","특정한 타인을 위한 보험에서 보험계약자가 보험료 지급을 지체하면 보험자는 그 타인에게도 상당한 기간을 정해 최고한 후가 아니면 해제·해지하지 못한다":"특정한 타인을 위한 보험에서는 계약자가 보험료를 늦게 내도 보험자가 그 타인에게도 최고한 뒤에야 해제하거나 해지할 수 있습니다.","평가 대상자: 금융감독원장 추천 소비자 3명, 한국소비자원장 추천 소비자 3명, 요율산출기관장 추천 전문가 1명, 생명·손해보험협회장 추천 모집종사자 각 1명, 보험연구원장 추천 법률전문가 1명":"이해도 평가에는 금융감독원장과 한국소비자원장이 각각 추천한 소비자 3명과 전문가와 모집종사자와 법률전문가가 참여합니다.","폐업: 보험업 전부 또는 일부를 폐업하려면 60일 전에 사업 폐업에 따른 정리계획서를 금융위원회에 제출한다":"보험업의 전부나 일부를 폐업하려면 60일 전에 정리계획서를 금융위원회에 제출해야 합니다.","포괄적 예정보험: 일정 기간 일정 조건의 다수 선적화물을 포괄·계속적으로 보험의 목적으로 하며, 화주는 개개 화물의 명세를 보험자에게 통지해야 한다":"포괄적 예정보험은 일정 기간의 여러 선적화물을 한꺼번에 계속 보험의 목적으로 하고 화주가 개개 화물의 명세를 통지해야 합니다.","표준계약서에 사전지정운용제도에 관한 사항을 반드시 기재하는 것은 아니다. 표준계약서 기재사항은 제23조의5제1항 각 호(가입자·가입기간·급여 종류, 부담금, 기금 관리·운용, 운용현황 통지, 계좌·적립금·급여 지급 등)":"표준계약서에 사전지정운용제도를 꼭 적을 필요는 없으며 가입자, 부담금, 기금 운용, 급여 지급 등이 기재사항입니다.","피보험이익: 보험의 목적에 대하여 보험사고 발생 여부에 따라 피보험자가 가지는 경제적 이익 또는 이해관계. 금전으로 산정할 수 있는 이익에 한해 보험계약의 목적으로 할 수 있다":"피보험이익은 보험의 목적에 대해 사고 여부에 따라 피보험자가 가지는 경제적 이해관계이며 금전으로 산정할 수 있어야 합니다.","피보험이익은 보험사고 발생 시까지 확정할 수 있으면 되고, 미등기건물처럼 소유권 등기가 없어도 금전으로 산정할 수 있으면 족하다":"피보험이익은 사고 발생 때까지만 확정할 수 있으면 되고 등기가 없는 건물이라도 금전으로 산정할 수 있다면 충분합니다.","피보험자가 보험기간 중의 사고로 제3자에게 배상할 책임을 진 경우 이를 보상한다":"책임보험은 피보험자가 보험기간 중 사고로 제삼자에게 배상해야 할 책임을 지게 된 경우 그 손해를 보상합니다.","피보험자가 보험기간 중 자동차를 양도하면 양수인은 보험자의 승낙을 얻은 경우에 한해 보험계약상 권리와 의무를 승계한다":"자동차를 양도하면 양수인은 보험자의 승낙을 얻어야만 보험계약상의 권리와 의무를 이어받습니다.","피보험자가 보험의 목적을 양도하면 양수인은 보험계약상의 권리와 의무를 승계한 것으로 추정한다. 양도인 또는 양수인은 보험자에게 지체없이 통지해야 한다":"보험의 목적을 넘기면 양수인이 보험계약상의 권리와 의무를 이어받은 것으로 추정하고 양도인이나 양수인이 보험자에게 바로 알려야 합니다.","피보험자가 보험자 동의 없이 변제·승인·화해를 한 경우 보험자가 책임을 면하기로 합의했어도, 그 행위가 현저하게 부당하지 않으면 보험자는 보상책임을 면하지 못한다":"동의 없이 변제나 화해를 했더라도 그것이 현저히 부당하지 않다면 보험자는 보상 책임에서 벗어날 수 없습니다.","피보험자가 서면동의를 하려면 전제가 된 사정이 있어야 하며, 전제 사정이 중대하게 변경되면 성립 후에도 동의를 철회할 수 있다. 동의 행위 자체의 흠은 민법상 무효·취소 주장이 가능하다":"동의의 전제가 된 사정이 크게 바뀌면 성립 후에도 동의를 철회할 수 있고 동의 행위 자체의 흠은 민법상 무효나 취소로 다툴 수 있습니다.","피보험자가 자동차를 소유·사용 또는 관리하는 동안에 발생한 사고로 생긴 손해를 보상한다":"자동차보험자는 피보험자가 자동차를 소유하고 사용하고 관리하는 동안 사고로 생긴 손해를 보상합니다.","피보험자가 정당한 이유 없이 사고발생을 통지하지 않거나 보험자의 협조요구에 응하지 않아 손해가 증가되었다면 보험자는 증가된 손해에 대한 책임을 면할 수 있고, 이는 보험자가 증명한다":"사고 통지나 협조를 정당한 이유 없이 거부해 늘어난 손해에 대해서는 보험자가 증명해 책임을 면합니다.","피보험자가 정신질환 등으로 자유로운 의사결정을 할 수 없는 상태에서 사망한 경우 면책되지 않는다. 그러나 정신질환을 독립된 면책사유로 규정한 약관은 유효하다":"정신질환 등으로 자유로운 의사결정이 불가능한 상태에서 숨진 경우는 면책되지 않지만 정신질환을 독립된 면책사유로 정한 약관은 유효합니다.","피보험자가 타인의 졸음운전으로 중상해를 입고 수혈을 거부해 사망한 경우 수혈거부가 사망의 유일한 원인 중 하나였다는 점만으로 보험자가 면책되지는 않는다":"타인의 졸음운전으로 중상을 입은 피보험자가 수혈을 거부해 숨졌더라도 수혈 거부가 원인 중 하나라는 이유만으로 보험자가 면책되지는 않습니다.","피보험자는 계약 성립 전까지 동의를 철회할 수 있고, 계약자·수익자의 동의가 있으면 효력 발생 후에도 철회할 수 있다":"피보험자의 동의는 계약이 성립하기 전이면 철회되고 이후에는 계약자와 수익자가 함께 동의해야 철회됩니다.","피보험자는 계약 성립 전까지 동의를 철회할 수 있다. 성립 후에는 계약자·수익자 동의가 있거나 서면동의의 전제가 된 사정에 중대한 변경이 있을 때 철회할 수 있다":"성립 후 철회는 계약자와 수익자의 동의가 있거나 서면동의의 전제 사정이 크게 달라졌을 때만 허용됩니다.","피보험자는 제3자로부터 배상청구를 받으면 지체없이 통지를 발송해야 하며, 게을리하여 손해가 증가되면 증가분을 보상하지 않는다. 다만 제657조제1항의 보험사고 통지를 발송했다면 그렇지 않다":"제삼자에게서 배상청구를 받으면 바로 보험자에게 알려야 하고 게을러서 손해가 커졌다면 커진 만큼 보상하지 않으며 사고 통지를 했다면 예외입니다.","피보험자는 제3자에 대한 변제·승인·화해·재판으로 채무가 확정되면 지체없이 통지를 발송해야 하며, 보험자는 특별한 기간 약정이 없으면 통지를 받은 날부터 10일 내에 보험금액을 지급한다":"배상채무가 확정되면 바로 통지하고 보험자는 따로 정한 기간이 없으면 받은 날부터 10일 안에 보험금을 줍니다.","피보험자 또는 그 상속인이 아닌 자를 수익자로 지정하려면 단체 규약에서 명시적으로 정한 경우 외에는 피보험자의 서면동의를 받아야 하며, 받지 않은 지정은 무효다":"피보험자나 상속인이 아닌 자를 수익자로 지정하려면 규약에 명시된 경우 외에는 피보험자의 서면동의가 필요하고 없으면 그 지정은 무효입니다.","피보험자와 피보험이익이 명확하지 않은 손해보험은 보험계약서·약관·체결 경위·실무 관행 등을 참작해 타인을 위한 보험인지 정한다":"피보험자와 피보험이익이 불분명한 손해보험은 계약서와 약관과 체결 경위와 관행을 종합해 타인을 위한 보험인지 판단합니다.","피보험자의 사망, 생존, 사망과 생존에 관한 보험사고가 발생할 경우 약정한 보험금을 지급한다":"생명보험자는 피보험자의 사망이나 생존이나 사망과 생존을 함께 담보하는 사고가 생기면 약정한 보험금을 지급합니다.","피보험자의 생명이나 신체에 관하여 보험사고가 발생하면 보험계약으로 정하는 바에 따라 보험금이나 그 밖의 급여를 지급한다. 보험금은 약정에 따라 분할하여 지급할 수 있다":"인보험자는 피보험자의 생명이나 신체에 보험사고가 생기면 계약에서 정한 보험금이나 급여를 지급하며 약정에 따라 나누어 지급할 수도 있습니다.","피성년후견인·피한정후견인, 복권되지 않은 파산선고자, 이 법·금융소비자보호법에 따른 벌금 이상 형 집행 종료·면제 후 2년 미경과, 금고 이상 집행유예 기간 중인 자, 등록취소 후 2년 미경과, 등록취소 2회 이상이면 최종 취소일부터 3년 미경과, 과태료·과징금·업무정지·등록취소 처분 관련 임직원 2년 미경과, 법정대리인이 결격인 미성년자, 임원이 결격인 법인·단체, 모집 관련 보험료 유용 후 3년 미경과":"후견을 받는 사람, 복권 안 된 파산자, 형 집행 후 2년이 안 된 사람, 등록취소 후 일정 기간 안 지난 사람은 결격입니다.","피해자는 피보험자에 대한 손해배상청구권과 보험자에 대한 직접청구권을 임의로 선택해 행사할 수 있다":"피해자는 피보험자에 대한 손해배상청구와 보험자에 대한 직접청구 중 어느 쪽이든 마음대로 골라 행사할 수 있습니다.","필요비용은 보험의 목적에 포함되고 선급을 청구할 수 있다":"피보험자가 제삼자의 청구를 막으려고 쓰는 필요한 방어비용은 보험의 목적에 들어가므로 미리 지급해 달라고 청구할 수 있습니다.","하나의 사업에서 급여 및 부담금 산정방법의 적용 등에 차등을 두어서는 안 된다":"한 사업장 안에서 근로자마다 급여나 부담금 계산 방식을 다르게 정하는 차등은 허용되지 않습니다.","하물 선적에 착수한 후 계약이 체결된 경우 보험기간은 계약이 성립한 때 개시한다":"하물 선적을 시작한 뒤에 계약했다면 보험기간은 선적 착수 때가 아니라 계약이 성립한 때부터입니다.","합병: 결의일부터 2주 이내에 합병계약의 요지와 각 보험회사의 재무상태표를 공고. 합병은 이의를 제기한 계약자 등에게도 효력이 미친다. 합병인가 신청서 첨부: 합병계약서, 존속·신설회사 정관, 재산목록·재무상태표, 보험계약건수·금액·계약자 수 통계표 등":"합병은 결의 후 2주 안에 요지와 재무상태표를 공고하며 이의를 낸 계약자에게도 효력이 미치고 인가 신청서에는 합병계약서와 정관 등을 붙입니다.","항해변경: 보험계약에서 정한 발항항이 아닌 항에서 출항하거나, 도착항이 아닌 항을 향하여 출항하면 보험자는 책임을 지지 않는다. 책임 개시 후 도착항이 변경되면 변경이 결정된 때부터 책임이 없다":"출항지나 도착지가 계약과 다르면 보험자는 면책되고 책임이 시작된 뒤 도착항이 바뀌면 결정 시점부터 면책됩니다.","해당 사용자는 적립금운용위원회의 심의를 거친 적립금운용계획서에 따라 적립금을 운용한다. 계획서는 매년 1회 이상 작성하며 운용 목적·방법, 목표수익률, 운용성과 평가, 운용 담당자 의무 등을 포함한다":"그런 사용자는 위원회 심의를 거친 운용계획서대로 적립금을 굴려야 하며 계획서는 목표수익률과 성과평가 등을 담아 해마다 만듭니다.","해당하는 예: 화재보험의 건물 구조·용도를 변경하는 증·개축공사, 자동차 구조의 현저한 변경, 피보험자의 직종을 위험이 높은 직종으로 변경":"건물의 구조나 용도를 바꾸는 증개축과 자동차 구조의 큰 변경과 위험이 높은 직종으로의 변경이 위험 증가의 예입니다.","해산결의 인가신청서 첨부(주식회사, 2022 기출): 주주총회 의사록, 청산 사무 추진계획서, 보험계약자 및 이해관계인 보호절차 이행 증명서류, 상법 등 관계 법령 절차 이행에 흠이 없음을 증명하는 서류 — 모두 포함":"해산 인가 신청에는 총회 의사록, 청산 추진계획서, 계약자 보호 증명서류, 절차 적법 증명서류가 모두 붙습니다.","해산등기 신청서 첨부: 이전계약서, 각 보험회사 주주총회 등의 의사록, 제141조의 공고 및 이의에 관한 서류, 이전 인가를 증명하는 서류":"해산등기 신청서에는 이전계약서와 각 회사의 주주총회 의사록과 공고와 이의에 관한 서류와 이전 인가를 증명하는 서류를 붙입니다.","해산 사유: 존립기간 만료·정관 사유, 주주총회 등의 결의, 합병, 보험계약 전부의 이전, 파산, 보험업 허가취소, 해산을 명하는 재판":"보험회사는 존립기간 만료나 정관 사유와 총회 결의와 합병과 계약 전부 이전과 파산과 허가취소와 해산 재판으로 해산합니다.","해산·합병·보험계약 이전의 결의는 제39조제2항(상호회사) 또는 상법 제434조에 따른다":"해산과 합병과 보험계약 이전의 결의는 상호회사이면 법에 정한 방식으로 주식회사이면 상법 제434조의 특별결의로 합니다.","해산 후 보험금 지급: 결의·허가취소·해산재판으로 해산한 경우 보험금 지급 사유가 해산일부터 3개월 이내에 발생한 경우에만 지급하고, 그 후에는 적립금이나 미경과 보험료를 돌려준다. 허가취소로 해산하면 금융위원회가 청산인을 선임한다":"해산 뒤 3개월 안에 생긴 사고만 보험금을 주고 이후에는 적립금이나 미경과 보험료를 돌려주며 청산인은 위원회가 정합니다.","해산 후 이전 결의: 해산한 후에도 3개월 이내에는 보험계약 이전을 결의할 수 있다(6개월이 아님)":"해산한 뒤에도 3개월 안에는 보험계약 이전을 결의할 수 있으며 6개월이 아닙니다.","해상보험증권 기재사항: 선박 보험은 선박의 명칭·국적·종류·항해의 범위, 적하 보험은 선박의 명칭·국적·종류·선적항·양륙항 및 출하지·도착지를 정한 때 그 지명, 보험가액을 정한 때 그 가액":"해상보험증권에는 선박보험이면 선박의 명칭과 국적과 항해 범위를 적하보험이면 선적항과 양륙항 등을 보험가액을 정했다면 그 가액을 적습니다.","해상사업에 관한 사고로 인하여 생길 손해를 보상한다":"해상보험자는 해상사업에 관한 사고로 생기는 손해를 보상할 책임을 집니다.","해임 제한: 선임일이 속한 사업연도의 다음 사업연도부터 연속하는 3개 사업연도가 끝나는 날까지 해임할 수 없다. 예외: 회사 기밀 누설, 업무 태만으로 손해 발생, 계리업무 관련 부당한 요구·압력, 금융위원회의 해임 요구":"선임계리사는 선임 후 3개 사업연도가 끝날 때까지 해임할 수 없고 기밀 누설, 태만 손해, 위원회 요구 등은 예외입니다.","해지권 행사기간: 보험자가 그 사실을 안 날로부터 1월 내, 계약을 체결한 날로부터 3년 내에 한한다":"고지의무 위반 해지는 보험자가 그 사실을 안 날부터 1월 안, 계약을 맺은 날부터 3년 안에 해야 합니다.","해지의 의사표시는 보험계약자에게 한다. 보험수익자에게 한 해지통지는 효력이 없다":"해지는 계약의 당사자인 보험계약자에게 해야 하며 수익자에게 통지했다고 해지가 되지는 않습니다.","해지환급금이 지급된 경우에는 부활을 청구할 수 없다. 다만 약정지급사유 발생 후 해지되었다는 직원 말만 믿고 환급금을 수령한 경우는 해지 의사표시가 아니므로 부활 청구가 가능하다":"해지환급금을 받았다면 부활을 청구할 수 없으나 직원의 말만 믿고 받은 경우는 해지 의사표시가 아니라 부활 청구가 가능합니다.","해태의 효과: 보험자는 그 사실을 안 날로부터 1월 내에 한하여 계약을 해지할 수 있다":"통지를 게을리했을 때 보험자는 그 사실을 안 날부터 1월 안에만 계약을 해지할 수 있습니다.","허가를 받은 자는 해당 종목의 재보험 허가를 받은 것으로 본다":"어떤 종목의 보험업 허가를 받았다면 그 종목의 재보험 허가도 받은 것으로 간주합니다.","허가사항: 보험업의 허가(제4조), 재평가적립금의 보험계약자 배당 처분(제122조), 보험계약 이전 시 보험업 유지를 위한 비용 지출 외 자산 처분(제144조제1항 단서) 등":"허가를 받아야 하는 사항에는 보험업의 허가와 재평가적립금의 계약자 배당 처분과 계약 이전 때의 자산 처분 등이 있습니다.","허가 신청서 첨부서류: 정관, 업무 시작 후 3년간의 사업계획서(추정재무제표 포함), 보험종목별 사업방법서·보험약관·보험료 및 해약환급금 산출방법서. 보험종목을 추가하는 경우 정관은 제출하지 않을 수 있다":"허가 신청에는 정관과 3년 치 사업계획서, 사업방법서, 약관, 산출방법서가 필요하고 종목 추가 때는 정관이 빠집니다.","허가 요건: 자본금·기금 보유, 전문 인력과 전산설비 등 물적 시설, 타당하고 건전한 사업계획, 대주주의 결격사유 없음·출자능력·건전한 재무상태·건전한 경제질서 비훼손":"허가를 받으려면 자본금, 인력과 전산 같은 시설, 건전한 사업계획, 결격 없는 대주주를 갖춰야 합니다.","현저한 부주의로 중요한 사항임을 알지 못한 것도 고지의무 위반이 된다":"심한 부주의로 그것이 중요한 사항인 줄 몰랐더라도 알리지 않았다면 고지의무 위반이 됩니다.","협의회 기능: 조사업무의 효율적 수행을 위한 공동 대책 수립·시행, 조사한 정보의 교환, 공동조사 등 기관 간 협조, 조사 지원 등. 회의는 재적위원 과반수 출석, 출석위원 과반수 찬성으로 의결":"협의회는 공동 대책, 정보 교환, 공동조사 같은 조사 협력을 맡고 재적 과반수 출석과 출석 과반수 찬성으로 의결합니다.","화재가 피보험자와 생계를 같이 하는 가족의 고의로 발생한 경우 보험자는 보험금을 지급한 후 그 가족에게 청구권대위를 할 수 있다":"피보험자와 생계를 같이하는 가족의 고의로 불이 났다면 보험자는 보험금을 준 뒤 그 가족에게 청구권대위를 할 수 있습니다.","화재로 인하여 생길 손해를 보상한다":"화재보험자는 화재 때문에 생기는 손해를 보상할 책임을 집니다.","화재보험증권의 추가 기재사항: 건물이 목적이면 소재지·구조·용도, 동산이면 존치한 장소의 상태와 용도, 보험가액을 정한 때 그 가액":"화재보험증권에는 건물이면 소재지와 구조와 용도를 동산이면 보관 장소의 상태와 용도를 보험가액을 정했다면 그 가액을 더 적습니다.","확정급여형퇴직연금제도(DB): 근로자가 받을 급여의 수준이 사전에 결정되어 있는 퇴직연금제도":"DB형은 퇴직 때 받을 급여액을 미리 정해 두고 회사가 이를 책임지는 방식의 연금제도입니다.","확정기여형퇴직연금제도(DC): 급여의 지급을 위하여 사용자가 부담하여야 할 부담금의 수준이 사전에 결정되어 있는 제도":"DC형은 회사가 넣어 줄 부담금의 수준만 미리 정해 두고 운용 결과에 따라 급여가 달라지는 제도입니다.","회사 채권자에 대해 직접적인 의무를 지지 않으며, 채무에 관한 책임은 보험료를 한도로 한다. 보험료 납입에 관해 상계로 회사에 대항하지 못한다":"사원은 회사 채권자에게 직접 의무를 지지 않고 책임은 보험료 한도이며 보험료 납입에 대해 상계로 회사에 맞서지 못합니다.","회의는 연 1회 이상 개최. 재적위원 과반수가 소집을 요구하거나 위원장이 필요하다고 인정하는 경우 소집하고, 위원장이 의장이 된다":"위원회는 1년에 한 번 이상 열리고 재적위원 과반수 요구나 위원장 판단이 있으면 소집하며 의장은 위원장입니다.","후유장해보험금청구권 소멸시효는 후유장해로 인한 손해가 발생한 때부터 진행하며, 그 시기는 소멸시효를 주장하는 자가 입증한다":"후유장해보험금청구권은 장해로 인한 손해가 발생한 때부터 시효가 시작되고 그 시기는 시효를 주장하는 쪽이 입증합니다.","후유장해보험금청구권은 후유장해로 인한 손해가 발생한 때부터 진행하고, 그 발생시기는 소멸시효를 주장하는 자가 입증한다. 보험자의 잘못된 면책 통보는 기산점이 아니다":"후유장해보험금은 장해 손해가 발생한 때부터 시효가 가고 그 시기는 시효를 주장하는 쪽이 입증하며 잘못된 면책 통보는 기산점이 아닙니다.","희망이익보험: 적하의 도착으로 얻을 이익·보수의 보험은 계약으로 보험가액을 정하지 않으면 보험금액을 보험가액으로 한 것으로 추정한다":"적하가 도착하면 얻을 이익을 대상으로 한 보험은 보험가액을 정하지 않았다면 보험금액을 보험가액으로 정한 것으로 추정합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
